WordHunterWoW_QuestEN[36923] = { title = "Nemesis: Becoming Death", description = "You have chosen your quarry and surely soon they will feel your merciless wrath, but first you must venture out into the wilds of Draenor and rip out the still-beating heart of a dwarf in mortal combat. Return here with your prize.\n\nThrough the heart of your enemy the spirits will attune your senses, granting you second sight and keenness in hearing - all to stalk your prey and claim dominance.", objectives = "" }
WordHunterWoW_QuestEN[36924] = { title = "Nemesis: Dwarfstalker", description = "<Raza'kul hands you the bloody heart.>\n\nThe ritual is complete. Your nemesis is marked for death.\n\nNow your work to rid this world of the enemy truly begins. Kill all dwarves that stand defiantly against the Horde. Let their deaths serve as a warning to the rest of the Alliance: they will leave Draenor or they will die.\n\nReturn when you have quenched your rage with the blood of dwarf.\n\nConquer our enemy and be known as dwarfstalker. Fail and be nothing.", objectives = "" }
