WordHunterWoW_QuestEN[36940] = { title = "Warning Orgrimmar", description = "We have slowed the Iron Horde down, but this war is far from over... I'll stay here and continue our efforts to hold back the Iron Horde.\n\nThe Warchief needs to know about what we have accomplished here today, and the threat we face in the future.\n\nIt is probably best if you report to High Overlord Saurfang yourself, {class}.", objectives = "" }
WordHunterWoW_QuestEN[36941] = { title = "Report to the King", description = "We have slowed the Iron Horde down, but this war is far from over... I'll stay here and continue our efforts to hold back the Iron Horde.\n\nThe King needs to know about what we have accomplished here today, and the threat we face in the future.\n\nIt is probably best if you report to King Wrynn yourself, {name}.", objectives = "" }
WordHunterWoW_QuestEN[36944] = { title = "Besting a Boar", description = "The great boars of Gorgrond appear to serve as both a mount and an excellent source of food. Having a few of them in the garrison would not be an unwise idea.\n\nI have created for you another rope, should you wish to ride one down. Be wary of the Iron Horde presence nearby.", objectives = "" }
WordHunterWoW_QuestEN[36945] = { title = "Requisition a Riverbeast", description = "I have seen great beasts floating slowly along the rivers of Talador. The 'riverbeasts,' I believe they are called.\n\nTheir hides are solid, like rock, and yet they float along the waters easily. I would quite like to see one of these up close, if you should head that way. Tormak has created for you another rope, if you are interested.", objectives = "" }
WordHunterWoW_QuestEN[36946] = { title = "Entangling an Elekk", description = "The plains of Nagrand are the most lush and fertile that I have ever seen. Should you ever see them, you will come upon the mightiest beasts that this place has to offer.\n\nAmong them, the great elekk. A magnificent beast with horns that can grow larger than you or I.\n\nHere is another rope, should you wish to tangle with such a beast.", objectives = "" }
WordHunterWoW_QuestEN[36947] = { title = "New Strength", description = "", objectives = "" }
WordHunterWoW_QuestEN[36948] = { title = "Auctioning for Parts", description = "<The power crystal for this unit has been disconnected. Whatever did this also managed to rip out the other support modules. \n\nIf you found all of these items, you're confident you could restore it>", objectives = "" }
WordHunterWoW_QuestEN[36950] = { title = "Wrangling a Wolf", description = "The wolves of this land have jaws of steel. It is no wonder that the orcs have taken them as their own.\n\nYet, deep in Nagrand, there are young wolves, ripe for taming. They will present a great challenge to you, as they are more fast and agile than any beast in this land.\n\nHere is your final rope, may luck be with you.", objectives = "" }
WordHunterWoW_QuestEN[36951] = { title = "Arakkoa Exodus", description = "I assume you're familiar with the arakkoa, commander? Great, flying birdfolk. Extremely territorial.\n\nSome, however, have withered wings - a disease, maybe. They seem to be outcast from arakkoa society. You find them now and then, squatting in forgotten ruins or peddling trinkets on the roadside.\n\nIt seems the Iron Horde has incited the arakkoa by moving into their lands, and the outcasts are fleeing in droves.\n\nWe should make contact with these outcasts - they could have valuable information.", objectives = "" }
WordHunterWoW_QuestEN[36952] = { title = "Taking the Fight to Nagrand", description = "**Eyes Only -- Commander {name}**\n\nDurotan recommended dat we be gettin' a foothold in Nagrand, so I taken the liberty of dispatchin' some of da boys.\n\nThrall's already reportin' the new outpost be nearly complete. He been askin' me to let ya know they be ready for ya.\n\nA windrider be waitin' to catch ya up with the latest caravan shipment whenever you be ready, sir.\n\n-- Rokhan", objectives = "" }
WordHunterWoW_QuestEN[36953] = { title = "It's a Matter of Strategy", description = "**Eyes Only -- Commander {name}**\n\nThe Iron Horde have proved themselves worthy foes.\n\nThey managed to get their fleet moving to Talador from Gorgrond without my spies seeing a thing. Talador be a crossroads for the whole continent. We can't let them have it.\n\nDon't worry boss, we got a plan. Foreman Grobash be setting up an outpost for our forces as we speak. They be ready for you when you arrive, commander.\n\n--Rokhan", objectives = "" }
WordHunterWoW_QuestEN[36955] = { title = "Nemesis: Hunter - Hunted", description = "Our enemies surround us, and with each passing day their numbers grow. It is time to make a decisive strike against their armies, champion.\n\nAround me stand effigies of our most hated adversaries. You will be their downfall, {name}. You will become nemesis and they will run in fear at the sight of you.\n\nNow select the target of your rage and burn in effigy that race which you mean to eradicate. Speak to me when you have made your selection.", objectives = "" }
WordHunterWoW_QuestEN[36957] = { title = "Nemesis: Becoming Death", description = "You have chosen your quarry and surely soon they will feel your merciless wrath, but first you must venture out into the wilds of Draenor and rip out the still-beating heart of a blood elf in mortal combat. Return here with your prize.\n\nThrough the heart of your enemy the spirits will attune your senses, granting you second sight and keenness in hearing - all to stalk your prey and claim dominance.", objectives = "" }
WordHunterWoW_QuestEN[36958] = { title = "Nemesis: Slayer of Sin'dorei", description = "<Kuros hands you the bloody heart.>\n\nThe ritual is complete. Your nemesis is marked for death.\n\nNow your work to rid this world of the enemy truly begins. Kill all blood elves that stand defiantly against the Alliance. Let their deaths serve as a warning to the rest of the Horde: they will leave Draenor or they will die.\n\nReturn when you have quenched your rage with the blood of blood elf.\n\nConquer our enemy and be known as slayer of Sin'dorei. Fail and be nothing.", objectives = "" }
WordHunterWoW_QuestEN[36959] = { title = "Nemesis: Becoming Death", description = "You have chosen your quarry and surely soon they will feel your merciless wrath, but first you must venture out into the wilds of Draenor and rip out the mostly-dead heart of a Forsaken in mortal combat. Return here with your prize.\n\nThrough the heart of your enemy the spirits will attune your senses, granting you second sight and keenness in hearing - all to stalk your prey and claim dominance.", objectives = "" }
