WordHunterWoW_QuestEN[36993] = { title = "Clefthoof Training: Orc Hunters", description = "The Warsong Clan of Nagrand are some of the best hunters I've ever had the misfortune of meeting. If anyone can pose a real test for your future mount, it's one of their chief beast-killers.\n\nOut in Nagrand, you'll find an orc by the name of Karak. They call him the Great Hunter, and he's taken down more fierce beasts than any other in the clan. Get astride your clefthoof and bring him down. In the name of the poor wee beasts!", objectives = "" }
WordHunterWoW_QuestEN[36994] = { title = "Clefthoof Training: The Garn", description = "I've got one last challenge for ye, commander, but if it isn't a doozy.\n\nThey call them the garn. Wolves as black as night, and twice the size of a normal wolf, they can tear a man apart in seconds. Any beast in their right mind would be scared witless at the sight of such a predator.\n\nThere's a lone garn that's made it from their usual home in Frostfire, all the way over to Nagrand. Take your clefthoof, mount up, and bring it down. If the two of you survive, your clefthoof will truly be ready.", objectives = "" }
WordHunterWoW_QuestEN[36995] = { title = "Boar Training: Riplash", description = "That boar's seen it's share of combat out in Gorgrond, so it'll be a bit easier to train. We'll start off in it's home, as you've done with yer other beasties.\n\nSee if the two of you can't take down the mighty raptor known as Riplash.", objectives = "" }
WordHunterWoW_QuestEN[36996] = { title = "Boar Training: Gezz'ran", description = "There's plenty more beasts out in the wild that can make a snack of your favorite mount. One of the most cunning on Draenor is the stalker.\n\nStalkers can blend into their environments, allowing them to sneak in and steal the eggs of nearby prey. See if you and your boar can't overcome this natural defense mechanism. You'll find some mean stalkers out in Talador.", objectives = "" }
WordHunterWoW_QuestEN[36997] = { title = "Boar Training: Bulbapore", description = "Way down south in the Spires of Arak, the land's being overtaken by the mushrooms that grow underwater. The result? Strange fungal creatures sprouting up all over the place.\n\nTaking on a strange creature, like the fungal giant Bulbapore, gives us a great chance to expose your boar to predators it's unfamiliar with.", objectives = "" }
WordHunterWoW_QuestEN[36998] = { title = "Boar Training: Cruel Ogres", description = "Nagrand is home to the mightiest beasts in Draenor, and the ogres of the region have learned to tame them using brutal techniques.\n\nThere is one ogre in particular, the Gorian Beast-Lasher, that smells of blood and fear. Go on and see how your boar reacts to that.", objectives = "" }
WordHunterWoW_QuestEN[36999] = { title = "Boar Training: Darkwing Roc", description = "The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both of em.'\n\nHead on out to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc. That'll be a good test for the both of ye.", objectives = "" }
WordHunterWoW_QuestEN[37000] = { title = "Boar Training: Moth of Wrath", description = "Deep in the forests of Nagrand are some beasts capable of evading almost any predator. The greatest of them all, the Moth of Wrath, is coated with a foul-smelling dust.\n\nIf the moth dust is enough to keep wolves at bay, it'll probably be a pretty good test for your boar. See if you can't keep it focused and take down that moth.", objectives = "" }
WordHunterWoW_QuestEN[37001] = { title = "Boar Training: Thundercall", description = "The elements can sometimes pose a problem for some beasts. Ever seen a ram in a thunderstorm? They'll hide behind anything larger than themselves. I'm not sure if they think the world is ending or what, but it's not great if you're atop one at the time.\n\nIn Nagrand, off on a windswept cliff high above the shore, is a creature made of pure thunderstorms. Hop atop your boar and face off against Thundercall, and we'll see if it gets spooked.", objectives = "" }
WordHunterWoW_QuestEN[37002] = { title = "Boar Training: Ironbore", description = "Alright, we've taken on foes in the sky and on land, and even in the rain. What happens when the beasts are below your feet, though? We're about to find out!\n\nThe rockworm is a cunning predator, striking at prey from below the sands. Many beasts of Nagrand have grown wary of the rumbling of the earth. Take your boar on out to the sandy shores and see if you can't take down one of the elder rockworms: Ironbore.", objectives = "" }
WordHunterWoW_QuestEN[37003] = { title = "Boar Training: Orc Hunters", description = "The Warsong Clan of Nagrand are some of the best hunters I've ever had the misfortune of meeting. If anyone can pose a real test for your future mount, it's one of their chief beast-killers.\n\nOut in Nagrand, you'll find an orc by the name of Karak. They call him the Great Hunter, and he's taken down more fierce beasts than any other in the clan. Get astride your boar and bring him down. In the name of the poor wee beasts!", objectives = "" }
WordHunterWoW_QuestEN[37004] = { title = "Boar Training: The Garn", description = "I've got one last challenge for ye, commander, but if it isn't a doozy.\n\nThey call them the garn. Wolves as black as night, and twice the size of a normal wolf, they can tear a man apart in seconds. Any beast in their right mind would be scared witless at the sight of such a predator.\n\nThere's a lone garn that's made it from their usual home in Frostfire, all the way over to Nagrand. Take your boar, mount up, and bring it down. If the two of you survive, your boar will truly be ready.", objectives = "" }
WordHunterWoW_QuestEN[37005] = { title = "Riverbeast Training: Gezz'ran", description = "This beast's spent quite a few years out in the wilds of Talador, I'd say we start the training there. It's fairly docile, as well. I don't think it will take quite as long to train as the others.\n\nAs ye probably know, stalkers can blend into their environments, allowing them to sneak in and steal the eggs of nearby prey. See if you and your riverbeast can't overcome this natural defense mechanism.", objectives = "" }
WordHunterWoW_QuestEN[37006] = { title = "Riverbeast Training: Bulbapore", description = "Way down south in the Spires of Arak, the land's being overtaken by the mushrooms that grow underwater. The result? Strange fungal creatures sprouting up all over the place.\n\nTaking on a strange creature, like the fungal giant Bulbapore, gives us a great chance to expose your riverbeast to predators it's unfamiliar with.", objectives = "" }
