WordHunterWoW_QuestEN[37014] = { title = "Auctioning for Parts", description = "<The power crystal for this unit has been disconnected. Whatever did this also managed to rip out the other support modules. \n\nIf you found all of these items, you're confident you could restore it>", objectives = "" }
WordHunterWoW_QuestEN[37015] = { title = "Elekk Training: Cruel Ogres", description = "This beast is surely at home in Nagrand, and I bet ye after all of the years of domestication by Draenei, it's going to be a snap to train.\n\nLet's set it loose against the ogres of the region that yer familiar with. That Gorian Beast-Lasher, the one that smells of blood and fear, go on and see how your elekk  reacts to that.", objectives = "" }
WordHunterWoW_QuestEN[37016] = { title = "Elekk Training: Darkwing Roc", description = "The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both of em.'\n\nHead on out to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc. That'll be a good test for the both of ye.", objectives = "" }
