WordHunterWoW_QuestEN[37057] = { title = "Clefthoof Training: Ironbore", description = "You have defeated foes in the sky and on land, and even in the rain. Next, you face beasts beneath your very feet.\n\nThe rockworm is a cunning predator, striking at prey from below the sands. Many beasts of Nagrand have grown wary of the rumbling of the earth. Take your mount on out to the sandy shores and test it against the elder worm Ironbore.", objectives = "" }
WordHunterWoW_QuestEN[37058] = { title = "Clefthoof Training: Orc Hunters", description = "The Warsong Clan of Nagrand are some of the finest hunters the world of Draenor has ever known. Their beast-killers will aid us in putting this mount to the test.\n\nOut in Nagrand, you will find an orc by the name of Karak, the Great Hunter. He has slain more fierce beasts than any other in the clan. Face him astride your mount, and avenge the slain.", objectives = "" }
WordHunterWoW_QuestEN[37059] = { title = "Clefthoof Training: The Garn", description = "The last test for your mount will pit it against one of the great terrors of this land.\n\nThe garn. Wolves as black as night, and twice the size of a normal wolf, they can tear an orc apart in mere moments. The beasts here wisely fear them.\n\nThere is a lone garn that calls Nagrand its home. Take your clefthoof, mount up, and bring it down. If the two of you survive, your clefthoof will truly be ready.", objectives = "" }
WordHunterWoW_QuestEN[37060] = { title = "Lost in Transition", description = "Sir, the storehouse is fully operational and I've seen to it that your supplies are safely stored away and accounted for.\n\nUnfortunately, during the rest of my audit I found that we are missing a few crates of surplus material - probably misplaced by one of the porters.\n\nIf you happen to come across any of the surplus crates while making your rounds, please bring them to me and I'll update our ledger.", objectives = "" }
WordHunterWoW_QuestEN[37062] = { title = "Tricks of the Trade", description = "To pass the time, traders have been known to consume beverages of an inspired nature, if you know what I mean.\n\nSometimes, they drink a bit too much. Your trader might have stumbled beyond the gates and passed out under a tree. It's been known to happen from time to time.\n\nLuckily, I have a brew that I use to rouse groggy traders. One splash and I find they're more willing to work.", objectives = "" }
WordHunterWoW_QuestEN[37063] = { title = "Elekk Training: Cruel Ogres", description = "This beast is surely at home in Nagrand, and after the years of domestication by Draenei it will be quite easy to train.\n\nWe shall face it against the ogres of the region that you are familiar with. The Gorian Beast-Lasher, the one that smells of blood and fear, see how this elekk reacts to him.", objectives = "" }
WordHunterWoW_QuestEN[37064] = { title = "Elekk Training: Darkwing Roc", description = "The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both.\n\nTravel to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc. It will be a good test for your mount.", objectives = "" }
WordHunterWoW_QuestEN[37065] = { title = "Elekk Training: Moth of Wrath", description = "Deep in the forests of Nagrand are some beasts capable of evading almost any predator. The greatest of them all, the Moth of Wrath, is coated with a foul-smelling dust.\n\nIf the moth dust is enough to keep wolves at bay, it will probably be a pretty good test for your elekk. See if you can keep it focused and defeat the moth.", objectives = "" }
WordHunterWoW_QuestEN[37066] = { title = "Elekk Training: Thundercall", description = "The elements can sometimes pose a problem for some beasts. Even the mightiest wolf will often cower at the sound of thunder in the distance.\n\nIn Nagrand, off on a windswept cliff high above the shore, is a creature made of pure thunderstorms. Hop atop your beast and face off against Thundercall, and we will see how your mount fares.", objectives = "" }
WordHunterWoW_QuestEN[37067] = { title = "Elekk Training: Ironbore", description = "You have defeated foes in the sky and on land, and even in the rain. Next, you face beasts beneath your very feet.\n\nThe rockworm is a cunning predator, striking at prey from below the sands. Many beasts of Nagrand have grown wary of the rumbling of the earth. Take your mount on out to the sandy shores test it against the elder worm Ironbore.", objectives = "" }
WordHunterWoW_QuestEN[37068] = { title = "Elekk Training: Orc Hunters", description = "The Warsong Clan of Nagrand are some of the finest hunters the world of Draenor has ever known. Their beast-killers will aid us in putting this mount to the test.\n\nOut in Nagrand, you will find an orc by the name of Karak, the Great Hunter. He has slain more fierce beasts than any other in the clan. Face him astride your mount, and avenge the slain.", objectives = "" }
WordHunterWoW_QuestEN[37069] = { title = "Elekk Training: The Garn", description = "The last test for your mount will pit it against one of the great terrors of this land.\n\nThe garn. Wolves as black as night, and twice the size of a normal wolf, they can tear an orc apart in mere moments. The beasts here wisely fear them.\n\nThere is a lone garn that calls Nagrand its home. Take your elekk, mount up, and bring it down. If the two of you survive, your elekk will truly be ready.", objectives = "" }
WordHunterWoW_QuestEN[37070] = { title = "Power of the Nether", description = "", objectives = "" }
WordHunterWoW_QuestEN[37071] = { title = "Riverbeast Training: Gezz'ran", description = "This bulbous beast has spent a number of years in the wilds of Talador. We will begin the training there. It is already docile, as well, so I do not think it will take as long to train as the others.\n\nAs you know, stalkers can blend into their environments, allowing them to sneak in and steal the eggs of nearby prey. See if you and your riverbeast can't overcome this natural defense mechanism.", objectives = "" }
WordHunterWoW_QuestEN[37072] = { title = "Riverbeast Training: Bulbapore", description = "In the far south, in the Spires of Arak, the land is being swallowed by the mushrooms that grow underwater, and strange fungal creatures grow uninhibited.\n\nTaking on a strange creature, like the fungal giant Bulbapore, will grant you a chance to expose your mount to unfamiliar predators.", objectives = "" }
WordHunterWoW_QuestEN[37073] = { title = "Riverbeast Training: Cruel Ogres", description = "Nagrand is home to the mightiest beasts in Draenor, and the ogres of the region have learned to tame them using brutal techniques.\n\nThere is one ogre in particular, the Gorian Beast-Lasher, that smells of blood and fear. Go on and see how your beast reacts to that.", objectives = "" }
WordHunterWoW_QuestEN[37074] = { title = "Riverbeast Training: Darkwing Roc", description = "The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both.\n\nTravel to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc. It will be a good test for your mount.", objectives = "" }
WordHunterWoW_QuestEN[37075] = { title = "Riverbeast Training: Moth of Wrath", description = "Deep in the forests of Nagrand are some beasts capable of evading almost any predator. The greatest of them all, the Moth of Wrath, is coated with a foul-smelling dust.\n\nIf the moth dust is enough to keep wolves at bay, it will probably be a pretty good test for your riverbeast. See if you can keep it focused and defeat the moth.", objectives = "" }
WordHunterWoW_QuestEN[37076] = { title = "Riverbeast Training: Thundercall", description = "The elements can sometimes pose a problem for some beasts. Even the mightiest wolf will often cower at the sound of thunder in the distance.\n\nIn Nagrand, off on a windswept cliff high above the shore, is a creature made of pure thunderstorms. Hop atop your beast and face off against Thundercall, and we will see how your mount fares.", objectives = "" }
WordHunterWoW_QuestEN[37077] = { title = "Riverbeast Training: Ironbore", description = "You have defeated foes in the sky and on land, and even in the rain. Next, you face beasts beneath your very feet.\n\nThe rockworm is a cunning predator, striking at prey from below the sands. Many beasts of Nagrand have grown wary of the rumbling of the earth. Take your mount on out to the sandy shores test it against the elder worm Ironbore.", objectives = "" }
WordHunterWoW_QuestEN[37078] = { title = "Riverbeast Training: Orc Hunters", description = "The Warsong Clan of Nagrand are some of the finest hunters the world of Draenor has ever known. Their beast-killers will aid us in putting this mount to the test.\n\nOut in Nagrand, you will find an orc by the name of Karak, the Great Hunter. He has slain more fierce beasts than any other in the clan. Face him astride your mount, and avenge the slain.", objectives = "" }
WordHunterWoW_QuestEN[37079] = { title = "Riverbeast Training: The Garn", description = "The last test for your mount will pit it against one of the great terrors of this land.\n\nThe garn. Wolves as black as night, and twice the size of a normal wolf, they can tear an orc apart in mere moments. The beasts here wisely fear them.\n\nThere is a lone garn that calls Nagrand its home. Take your riverbeast, mount up, and bring it down. If the two of you survive, your riverbeast will truly be ready.", objectives = "" }
WordHunterWoW_QuestEN[37080] = { title = "Glorious Slaughter", description = "", objectives = "" }
WordHunterWoW_QuestEN[37081] = { title = "Burning Rage", description = "", objectives = "" }
WordHunterWoW_QuestEN[37082] = { title = "Call of the Gladiator", description = "Your merciless rampage has not gone unnoticed, gladiator. So many of your enemies have fallen before your might. It is because of your unrelenting savagery that Imperator Mar'gok himself has requested your presence at the grand Highmaul Coliseum. It is at Highmaul that a battle of epic proportions awaits.\n\nShould you heed the call of the gladiator, present this sigil to my brother, Kharg. He is the arena master residing outside of the Coliseum in Nagrand.", objectives = "" }
WordHunterWoW_QuestEN[37083] = { title = "Fight, Kill, Salute!", description = "The greatest gladiators on Draenor have fought for glory and honor inside the Coliseum. Will you become a legend like Kargath Bladefist or will you be nothing more than bone dust beneath the boots of a more savage gladiator? There is only one way to find out.\n\nYou must enter the competition and fight! The price of victory is 100 lives!\n\nI will admit you without cost once per day, but if you fail and wish to fight again you must pay the price of admission in blood and bone!", objectives = "" }
WordHunterWoW_QuestEN[37084] = { title = "The Shadows Call", description = "", objectives = "" }
WordHunterWoW_QuestEN[37085] = { title = "Fury of the Clan", description = "", objectives = "" }
WordHunterWoW_QuestEN[37086] = { title = "Salvaging the Situation", description = "Here at the Salvage Yard we inspect any extra material your followers bring back from the field, preserving anything that may be useful.\n\nI have an extra pack of material our people brought in that I've yet to go through. Why don't you take it over to the incinerator and see if it contains anything useful?", objectives = "" }
WordHunterWoW_QuestEN[37087] = { title = "Lost in Transition", description = "Sir, the storehouse is fully operational and I've seen to it that your supplies are safely stored away and accounted for.\n\nUnfortunately, during the rest of my audit I found that we are missing a few crates of surplus material - probably misplaced by one of the porters.\n\nIf you happen to come across any of the surplus crates while making your rounds, please bring them to me and I'll update our ledger.", objectives = "" }
WordHunterWoW_QuestEN[37088] = { title = "Tricks of the Trade", description = "To pass the time, traders have been known to consume beverages of an inspired nature, if you know what I mean.\n\nSometimes, they drink a bit too much. Your trader might have stumbled beyond the gates and passed out under a tree. It's been known to happen from time to time.\n\nLuckily, I have a brew that I use to rouse groggy traders. One splash and I find they're more willing to work.", objectives = "" }
WordHunterWoW_QuestEN[37091] = { title = "Unconventional Inventions", description = "The workshop is bustling with the whir of minds and motors. We're coming up with new inventions all the time.\n\nTry out today's glorious invention on the workbench behind me.", objectives = "" }
WordHunterWoW_QuestEN[37092] = { title = "Scraps of Iron", description = "At the Dwarven Bunker, we can take scraps of Iron Horde armor that you collect and turn them into new gear. It's not the strongest stuff in the world, but it looks good.\n\nGet some Iron Horde scraps and come back my way. I'll set you up with a nice tabard for your troubles.", objectives = "" }
WordHunterWoW_QuestEN[37093] = { title = "Talbuk Training: Great-Tusk", description = "The talbuk is ready for more training, and for this, we will return to its home in Shadowmoon Valley.\n\nOne of the great beasts of this land, Great-Tusk, has taken the valley for his own. Pit your beast against him in combat, and if you should survive, it will have greater confidence in its own abilities.", objectives = "" }
WordHunterWoW_QuestEN[37094] = { title = "Talbuk Training: Rakkiri", description = "We shall start training the talbuk here, on the icy plains of Frostfire Ridge. We must train it rigorously, or else it may become afraid at the sight of combat, and run.\n\nFind the great blood-sucker, Rakkiri, out on the frozen plains, and bring him down astride your talbuk. That will give it a taste for combat.", objectives = "" }
WordHunterWoW_QuestEN[37095] = { title = "Talbuk Training: Riplash", description = "Many beasts will cower in fear at the sight of a mighty predator. In the desolate cliffs of Gorgrond lives one of the most fierce. It will prove your next challenge.\n\nTake your beast to the nest of the great Riplash, and see if you cannot emerge victorious.", objectives = "" }
WordHunterWoW_QuestEN[37096] = { title = "Talbuk Training: Gezz'ran", description = "Many of the creatures of Draenor have grown and thrived in a most hostile environment. One of the most cunning is the stalker.\n\nStalkers can blend into their environments, allowing them to sneak in and steal the eggs of nearby prey. See if you and your beast can overcome this natural defense mechanism. You will find a proper predator in Talador.", objectives = "" }
WordHunterWoW_QuestEN[37097] = { title = "Talbuk Training: Bulbapore", description = "In the far south, in the Spires of Arak, the land is being swallowed by the mushrooms that grow underwater, and strange fungal creatures grow uninhibited.\n\nTaking on a strange creature, like the fungal giant Bulbapore, will grant you a chance to expose your mount to unfamiliar predators.", objectives = "" }
