WordHunterWoW_QuestEN[37100] = { title = "Talbuk Training: Moth of Wrath", description = "Deep in the forests of Nagrand are some beasts capable of evading almost any predator. The greatest of them all, the Moth of Wrath, is coated with a foul-smelling dust.\n\nIf the moth dust is enough to keep wolves at bay, it will probably be a pretty good test for your talbuk. See if you can keep it focused and defeat the moth.", objectives = "" }
WordHunterWoW_QuestEN[37101] = { title = "Talbuk Training: Thundercall", description = "The elements can sometimes pose a problem for some beasts. Even the mightiest wolf will often cower at the sound of thunder in the distance.\n\nIn Nagrand, off on a windswept cliff high above the shore, is a creature made of pure thunderstorms. Hop atop your beast and face off against Thundercall, and we will see how your mount fares.", objectives = "" }
WordHunterWoW_QuestEN[37102] = { title = "Talbuk Training: Ironbore", description = "You have defeated foes in the sky and on land, and even in the rain. Next, you face beasts beneath your very feet.\n\nThe rockworm is a cunning predator, striking at prey from below the sands. Many beasts of Nagrand have grown wary of the rumbling of the earth. Take your mount on out to the sandy shores test it against the elder worm Ironbore.", objectives = "" }
WordHunterWoW_QuestEN[37103] = { title = "Talbuk Training: Orc Hunters", description = "The Warsong Clan of Nagrand are some of the finest hunters the world of Draenor has ever known. Their beast-killers will aid us in putting this mount to the test.\n\nOut in Nagrand, you will find an orc by the name of Karak, the Great Hunter. He has slain more fierce beasts than any other in the clan. Face him astride your mount, and avenge the slain.", objectives = "" }
WordHunterWoW_QuestEN[37104] = { title = "Talbuk Training: The Garn", description = "The last test for your mount will pit it against one of the great terrors of this land.\n\nThe garn. Wolves as black as night, and twice the size of a normal wolf, they can tear an orc apart in mere moments. The beasts here wisely fear them.\n\nThere is a lone garn that calls Nagrand its home. Take your talbuk, mount up, and bring it down. If the two of you survive, your talbuk will truly be ready for war.", objectives = "" }
WordHunterWoW_QuestEN[37105] = { title = "Wolf Training: Cruel Ogres", description = "The wolves of this land are the most savage beasts I have seen, and surely do not fear orc nor ogre.\n\nBring him to bear against once of the ogres that you are familiar with. The Gorian Beast-Lasher, the one that smells of blood and fear, see how the wolf reacts to him.", objectives = "" }
WordHunterWoW_QuestEN[37106] = { title = "Wolf Training: Darkwing Roc", description = "The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both.\n\nTravel to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc. It will be a good test for your mount.", objectives = "" }
WordHunterWoW_QuestEN[37107] = { title = "Wolf Training: Moth of Wrath", description = "Deep in the forests of Nagrand are some beasts capable of evading almost any predator. The greatest of them all, the Moth of Wrath, is coated with a foul-smelling dust.\n\nIf the moth dust is enough to keep wolves at bay, it will probably be a pretty good test for your wolf. See if you can keep it focused and defeat the moth.", objectives = "" }
WordHunterWoW_QuestEN[37108] = { title = "Wolf Training: Thundercall", description = "The elements can sometimes pose a problem for some beasts. Even the mightiest wolf will often cower at the sound of thunder in the distance.\n\nIn Nagrand, off on a windswept cliff high above the shore, is a creature made of pure thunderstorms. Hop atop your beast and face off against Thundercall, and we will see how your mount fares.", objectives = "" }
WordHunterWoW_QuestEN[37109] = { title = "Wolf Training: Ironbore", description = "You have defeated foes in the sky and on land, and even in the rain. Next, you face beasts beneath your very feet.\n\nThe rockworm is a cunning predator, striking at prey from below the sands. Many beasts of Nagrand have grown wary of the rumbling of the earth. Take your mount on out to the sandy shores test it against the elder worm Ironbore.", objectives = "" }
WordHunterWoW_QuestEN[37110] = { title = "Wolf Training: Orc Hunters", description = "The Warsong Clan of Nagrand are some of the finest hunters the world of Draenor has ever known. Their beast-killers will aid us in putting this mount to the test.\n\nOut in Nagrand, you will find an orc by the name of Karak, the Great Hunter. He has slain more fierce beasts than any other in the clan. Face him astride your mount, and avenge the slain.", objectives = "" }
WordHunterWoW_QuestEN[37111] = { title = "Wolf Training: The Garn", description = "The last test for your mount will pit it against one of the great terrors of this land.\n\nThe garn. Wolves as black as night, and twice the size of a normal wolf, they can tear an orc apart in mere moments. The beasts here wisely fear them.\n\nThere is a lone garn that calls Nagrand its home. Take your wolf, mount up, and bring it down. If the two of you survive, your wolf will truly be ready.", objectives = "" }
WordHunterWoW_QuestEN[37112] = { title = "Rest and Relaxation", description = "Every adventurer should rest when exhaustion sets in - and there is no finer place to get rest and relaxation than at the Lion's Pride Inn!\n\nMy best friend, Innkeeper Farley, runs the Lion's Pride. If you tell him I sent you, he may give you the special discounted rates on food and drink.\n\nTo find the Lion's Pride Inn, travel south along the road from here -- you can't miss it!", objectives = "" }
WordHunterWoW_QuestEN[37113] = { title = "Thisalee Crow", description = "", objectives = "" }
WordHunterWoW_QuestEN[37114] = { title = "Choluna", description = "", objectives = "" }
WordHunterWoW_QuestEN[37119] = { title = "The Headhunter's Harvest", description = "The inn provides a perfect place for adventurers to take a rest between their travels. It's also a great place to talk them into joining our cause over a few rounds of drinks.\n\nGo through my selection and let's see if we can obtain a new recruit. I'll give you a little something as a finder's fee for your efforts.", objectives = "" }
WordHunterWoW_QuestEN[37121] = { title = "The Black Claw", description = "Behind me, as ye can probably see, is a giant black claw. We found it while we were out hunting new beasts to tame. The animals seem to be quite afraid of it, perhaps the beast it belonged to used to hunt them.", objectives = "" }
WordHunterWoW_QuestEN[37122] = { title = "Teeth of a Predator", description = "This necklace dropped off of one of the orc hunters we found while out taming beasts. I've never seen the animals react so strongly to anything!", objectives = "" }
WordHunterWoW_QuestEN[37123] = { title = "The Black Claw", description = "You've probably seen this enormous, black claw in our pile of supplies. We found it while we were out hunting new beasts to tame. The animals seem to be quite afraid of it, perhaps the beast it belonged to used to hunt them.", objectives = "" }
WordHunterWoW_QuestEN[37124] = { title = "Teeth of a Predator", description = "This necklace dropped off of one of the orc hunters we found while out taming beasts. I've never seen the animals react so strongly to anything.", objectives = "" }
WordHunterWoW_QuestEN[37126] = { title = "An Ogre Without His Sword...", description = "Before I was shipped off to Gorgrond, I was stationed at the Broken Precipice in Nagrand, maintaining order over the unruly dredges. Vizier Dar'gud refused to let me take my favorite sword; he told me \"I wouldn't need it where I was going.\"\n\nI want it back, commander, and we are powerful enough together to take it from Dar'gud's bloody corpse.\n\nIt would mean a great deal to me. An ogre without his sword isn't an ogre at all.", objectives = "" }
WordHunterWoW_QuestEN[37127] = { title = "The Light of Exodus", description = "My grandfather always told me stories of a powerful crystal made of the Light that would grant power to those who intended to use it for good. He called it the Light of Exodus.\n\nI never believed him... until now.\n\nYour scouts have found a crystal that sounds just like it. It has been taken by a terrible demon and is being corrupted at the Beacon of Sha'tar in Shattrath.\n\nWe have to hurry!", objectives = "" }
WordHunterWoW_QuestEN[37128] = { title = "Settling Grievances", description = "Our scouts have found a powerful draenei crystal being corrupted by Ambassador Hellmaw at the Beacon of Sha'tar in Shattrath. The draenei call it the Light of Exodus.\n\nCommander, I'd like to accompany you on this mission. Hellmaw slew my brother in Outland... this is personal.", objectives = "" }
WordHunterWoW_QuestEN[37129] = { title = "Unwelcome Memories", description = "The botani in the Everbloom Wilds are doin' some sorta foul magic to create these plant... well... zombies, basically.\n\nI've seen what happens with armies o' mindless slaves. The Lich King...\n\n<Delvar's eyes close.>\n\nNo matter. We cannae let this escalate any further. I heard o' a particularly nasty one they've just made... let's kill it and see what makes it tick.", objectives = "" }
WordHunterWoW_QuestEN[37131] = { title = "The Dark Lady's Concern", description = "The botani in the Everbloom Wilds kill anything foolish enough to wander too close to their blooms and are raising their corpses as mindless soldiers.\n\nThis is all too reminiscent of the Scourge... and the Dark Lady has taken notice. She has a special mission for us, commander.\n\nThere is a particularly large infested creature that was recently raised. We are to destroy it and retrieve its remains.", objectives = "" }
WordHunterWoW_QuestEN[37137] = { title = "Scrying Hard or Hardly Scrying", description = "There are others that harness the shadows to do their bidding. You know of them, commander... the Shadowmoon orcs.\n\nThey have begun to master their craft... they call to the shadows beyond this realm...\n\nI desire their power. They have one who possesses a staff of particular interest... we should claim it as our own.", objectives = "" }
WordHunterWoW_QuestEN[37140] = { title = "Leorajh's Prayer Beads", description = "When Leorajh became shaman, pridelord gave prayer beads. Beads help Leorajh hear elements.\n\nOne day bird-men attacked and took prayer beads. Took them to Skettis.\n\nMaster, you help Leorajh get prayer beads back?", objectives = "" }
WordHunterWoW_QuestEN[37141] = { title = "Talonpriest Ishaal", description = "", objectives = "" }
WordHunterWoW_QuestEN[37142] = { title = "Ogre Ancestry", description = "Lunk no like fight, want to learn. You help Lunk learn?\n\nFind Lunk ancestors. Lunk have many question. Where Lunk come from? Why Lunk Lunk?\n\nLunk stay here. Small ogres mean, big ogres meaner.", objectives = "" }
WordHunterWoW_QuestEN[37144] = { title = "Talon Guard Kurekk", description = "", objectives = "" }
WordHunterWoW_QuestEN[37145] = { title = "Budd's Gambit", description = "Listen, I don't know how I got here, but I have it on good authority that there is an entire island made of shiny things and it's just off of the coast a ways.\n\nAll we have to do is hop in the water and swim out there, then we can load up our pockets and swim back! I'm just going to rest up and do some stretching before heading out.\n\nDon't try and stop me!", objectives = "" }
WordHunterWoW_QuestEN[37146] = { title = "Go Fetch", description = "Now THIS is a savage land worthy of my level of heroism!\n\nOh, hello, I did not see you standing there, staring at me. Perhaps you have noticed that every piece of my armor is an ancient relic, forgotten by time.\n\nAs you have properly surmised, an adventurer of my stature does not have time to complete the menial requests I am given daily. I must remain here, yelling aloud to the trade district so that others may witness my heroicness and be inspired.\n\nToday I require a Nightmare Bell, do find one.", objectives = "" }
WordHunterWoW_QuestEN[37147] = { title = "Sky Dancers", description = "Greetings, {name}, and I thank you for your hospitality.\n\nThe Shado-pan have sent several warriors to aid against the Iron Horde, however we can. We are few, though, and they are many.\n\nThe arakkoa in the south are both beautiful and deadly. They appear lighter than air, their attacks a deadly dance that flits from opponent to opponent.\n\nThe winds are on their side, as the four winds lighten the steps of my own allies. Bring me a sample of their winds, if you are able. It will surely aid us.", objectives = "" }
WordHunterWoW_QuestEN[37148] = { title = "Oralius' Adventure", description = "Me n' Winky, off on adventures again! This is the life, I tell ye. No burning air to breathe, an' plenty of ogres to kill!\n\n<Oralius rubs his belly.>\n\nWe did leave a bit of a mess back there in the Blackrock Spire, though. A whole mess of these iron-plated orcs and some proto-dragons marched right on up from the south and took it over.\n\nOl' Winky, he couldn't take the guilt. Went on back by himself he did, to stop them!\n\nOr... to JOIN them! Winky, ye two-timing son of an orc. Ye've got to stop him!", objectives = "" }
WordHunterWoW_QuestEN[37149] = { title = "The Void-Gate", description = "My 'master' is an idiot, but you look like you've got some smarts in that oddly-shaped head.\n\nListen up, the Twisting Nether is a chaotic abyss, and things work differently there. I've felt some disturbances, and they don't bode well for any of us.\n\nYes, there are things happening here, in Draenor, that are causing ripples in the nether. No, don't try to wrap your head around how that works, you'll only hurt yourself.\n\nIt's simple: bring me a Void-Gate Key, and maybe I can stop the bad things.", objectives = "" }
WordHunterWoW_QuestEN[37150] = { title = "For the Birds", description = "Hi! Have you ever held a peachick hatchling?\n\n<Without warning, Mylune grabs both of your hands and then stuffs a tiny chirping bird in them.>\n\nIsn't it so small and light and downy? Like you're holding a beaky peepy lil' CLOUD! It's so adorable you can't help but hug it and cuddle it and stuff regurgitated food in its teeny-tiny mouth.\n\n{name}, the plantfolk in the Everbloom are turning peachicks into monsters before they can grow into beautiful swans. Or whatever they grow into. Please help them!", objectives = "" }
WordHunterWoW_QuestEN[37151] = { title = "Cold Steel", description = "Do you know what I want? What everyone who came through that portal wants. Every soldier running from a world that didn't understand us, didn't need us. I want that world to love us as much as we love it.\n\nBut we don't really belong there, not anymore. War is part of us, and we can't go back. To everyone back there, we're expendable.\n\nThe only thing that makes me feel better now is the feel of a cold iron cannon in my hands, pointed at the enemy.\n\n<Keeshan stares into his mug of ale.>", objectives = "" }
WordHunterWoW_QuestEN[37152] = { title = "Cro's Revenge", description = "HA! The fruit vendor was so cunning, but I, Cro Threadstrong, am even MORE cunning. I have come back into the past to defeat the ogre army before that fruit vendor can turn them against me!\n\nBring me the head of a big, strong ogre from the old slag mines, and I will have crushed the fruit vendor before a single apple has even grown!\n\nCAN YOU HEAR ME, FRUIT VENDOR? I WILL HAVE MY VICTORY!", objectives = "" }
WordHunterWoW_QuestEN[37153] = { title = "Time-Lost Vikings", description = "Oi, barely made it out of that place!\n\nWe came through the portal to help, and the next thing you know, we're prisoners in the Bloodmaul Slag Mine. It was brutal! We were shackled for days, and covered in filth.\n\nAnd they took my SHIELD!", objectives = "" }
WordHunterWoW_QuestEN[37154] = { title = "The Cure For Death", description = "Greetings, and my thanks for the warmth of this inn and your hospitality.\n\nAs you can see, this malady of death continues to plague me. My studies on Azeroth and in Northrend met with little luck, and all of my leads ran dry.\n\nI have come to Draenor in the hope of finding something, anything, to go on. My first pilgrimage will be to Auchindoun, a house where souls are put at ease.\n\nIf you should head there yourself, do let me know if you should happen upon anything of interest.", objectives = "" }
WordHunterWoW_QuestEN[37155] = { title = "The Brass Compass", description = "Greetings, commander. I have come on a mission directly from the captain.\n\nAboard any vessel on Azeroth that's manned by at least one orc, you'll hear sea shanties sung about a device capable of navigating the broad, rough ocean of Draenor. The orcs used it to keep their heading true in the choppiest of storms.\n\nPerhaps it's just an old sea tale, but this one chance to find that kind of prize has the captain willing to part with some fine treasure.", objectives = "" }
WordHunterWoW_QuestEN[37156] = { title = "The Soulcutter", description = "Don't look at me! Who do you think you are?\n\nYou and I are on the same side, you know. The necromancers here, we have to kill them. All of them.\n\nDon't you agree?\n\nOf course you do, and you can help me accomplish this goal. Find a Soulsever Blade in that hovel where the necromancers have holed up like rats. It has... special properties... that will aid us against the undead.", objectives = "" }
WordHunterWoW_QuestEN[37157] = { title = "Feeling A Bit Morose", description = "So many years of waking up as a spirit, reanimated by some unseen force time and again, has left one with certain desires - the comforting, velvet blackness of death being chief amongst them.\n\nOne will, however, settle for the lesser prize of a solution capable of removing the scuff marks that the commander's wonderful compatriots left behind in the dining hall in their woefully short stay in Karazhan, whereupon they barely had enough time to irreparably damage the priceless furniture.", objectives = "" }
WordHunterWoW_QuestEN[37158] = { title = "Gloriously Incandescent", description = "I did not come here to fight, I have seen too many die already. I have killed so many with my own hands.\n\nI have come to seek the light, and redemption.\n\nThe arakkoa of this land worship the sun as I do. But they are a violent, isolationist, and decadent race, who seem to derive a different message than my own people. This troubles me.\n\nBring me one of their Sun Crystals. I wish to see this light.", objectives = "" }
WordHunterWoW_QuestEN[37159] = { title = "Aviana's Request", description = "The arakkoa are creatures of the sky, and are thus within the domain of the great Aviana.\n\nI have been sent to procure a feather, that we may parley with them through the language of the winds. We will extend an invitation of peace, and a place on the Great Bough.\n\nWould you aid us in this quest? The feather must come from an arakkoan of nobility. You will find them in the place known as Skyreach.", objectives = "" }
WordHunterWoW_QuestEN[37160] = { title = "Cleaving Time", description = "I, Gamon, have come through the dark portal to cleave many orc skulls. Yet my weapon has not kept pace with my rage, and is nicked and dull.\n\nFind me a new weapon - one that is good for removing Hellscream limbs.", objectives = "" }
WordHunterWoW_QuestEN[37161] = { title = "Family Traditions", description = "He ran off with it! Oh what am I going to do, what am I going to DO?\n\nMy son, and my knife, they ran off to Blackrock Spire! Well, the knife didn't run, I suppose. That doesn't matter!\n\nYou've got to get it back! Yes, the knife! You've got to get me back my knife!\n\nGo! Now! Stop talking!", objectives = "" }
WordHunterWoW_QuestEN[37162] = { title = "Damsels and Dragons", description = "What ho, squire {name}! Forgive my lips, as they bear gravest news. Dragons have taken up stinking residence within the hallowed halls of Blackrock Spire!\n\nThese great wyrms hold a distressed damsel in their scaly graspers. Her name is Zaela, they say. Such a beautiful name!\n\nAs my squire, it is your Light-given duty to adventure yourself into this spire and procure evidence of these dragons, lest I waste my heroism on a dragonless quest.", objectives = "" }
WordHunterWoW_QuestEN[37163] = { title = "Shadowy Secrets", description = "Though the Lich King has been defeated, we are no closer to unlocking the secrets of the Frozen Throne than we were when jousting pointlessly at the Argent Tournament. Bolvar remains resigned to his fate.\n\nPerhaps there is something here, though, that can aid us. Ner'zhul was not always the Lich King, you know. Once, he was a mere orc dabbling in dark powers beyond his comprehension.\n\nFind whatever you can of his early studies, and we may have our answers.", objectives = "" }
WordHunterWoW_QuestEN[37164] = { title = "The Huntresses", description = "I do not wish to come out of the shadows, but I mean you no harm. My purpose here is my own secret to keep, I simply needed a warm place to bed down for the night.\n\nI can see that you are not the type to be easily swayed into leaving. Very well, perhaps you can aid me in my search.\n\nI am looking for someone, it is not important who. All you need to know is that I will reward you for any sign of high elven weaponry that you should come across.", objectives = "" }
WordHunterWoW_QuestEN[37165] = { title = "Cenarion Concerns", description = "Ey mon!\n\nDe Cenarion Circle sent Zen'kiki out here ta check out dem primals. I woulda been here sooner, but I had a little bit o' trouble gettin' my flight form ta work, mon.\n\nDe plants in dis place... I can hear dem talk. Dey be yellin' all the time. Angry an' violent yellin'.\n\nWould ya bring Zen'kiki back a leaf from dis Everbloom place dey be talkin' about? Maybe I can figure out what dey want.", objectives = "" }
WordHunterWoW_QuestEN[37166] = { title = "Titanic Evolution", description = "Ah, hello! Do not look so surprised! Did I not also brave the dangers of the Mogu'shan Vaults? I am more sturdy than I look!\n\nI have learned many things of this wonderful place in history already. Did you know that, just like on our world, the titans once came to this place?\n\nAt least, that is what I believe! Surely there are signs of the titans' presence here, even now. Should you find one, I would very much like to see it!", objectives = "" }
WordHunterWoW_QuestEN[37167] = { title = "And No Maces!", description = "There are far too many bright-eyed young rogues being sent through this portal and off to war. If I'm going to start up my academy again, some of them have got to survive this little excursion.\n\nWhile I'm here, I figured I might as well use the opportunity to gather some supplies for my grand opening. You can't start a business without plenty of daggers, after all.\n\nGrab me a crate of weaponry from the Grimrail Depot, there should be plenty lying around. I'll have something nice for you.", objectives = "" }
WordHunterWoW_QuestEN[37168] = { title = "Leorajh, the Enlightened", description = "", objectives = "" }
WordHunterWoW_QuestEN[37177] = { title = "Call of the Talon King", description = "{name}, you have done much for my people. I wish to thank you on their behalf.\n\nPlease visit Veil Terokk when you can.", objectives = "" }
WordHunterWoW_QuestEN[37179] = { title = "For The Children!", description = "Wait, wait! Don't attack me! I've changed!\n\nReally, I've turned over a new leaf, I promise. I haven't said \"DOOOOOOM!\" in months! All I care about now is saving the poor little orphans of Azeroth, whose parents have been taken by this tragic war.\n\nThat's why I'm here! Why, with just a single Miniature Iron Star, I could provide clean water and power for all of the orphans of Azeroth! And no one could stop me!\n\nSo, what do you think, sweetcheeks? Want to help ol' Milhouse save the orphans?", objectives = "" }
WordHunterWoW_QuestEN[37180] = { title = "An Ogre Without His Sword...", description = "Before I was shipped off to Gorgrond, I was stationed at the Broken Precipice in Nagrand, maintaining order over the unruly dredges. Vizier Dar'gud refused to let me take my favorite sword; he told me \"I wouldn't need it where I was going.\"\n\nI want it back, commander, and we are powerful enough together to take it from Dar'gud's bloody corpse.\n\nIt would mean a great deal to me. An ogre without his sword isn't an ogre at all.", objectives = "" }
WordHunterWoW_QuestEN[37181] = { title = "Leorajh's Prayer Beads", description = "When Leorajh became shaman, pridelord gave prayer beads. Beads help Leorajh hear elements.\n\nOne day bird-men attacked and took prayer beads. Took them to Skettis.\n\nMaster, you help Leorajh get prayer beads back?", objectives = "" }
WordHunterWoW_QuestEN[37182] = { title = "Scrying Hard or Hardly Scrying", description = "There are others that harness the shadows to do their bidding. You know of them, commander... the Shadowmoon orcs.\n\nThey have begun to master their craft... they call to the shadows beyond this realm...\n\nI desire their power. They have one who possesses a staff of particular interest... we should claim it as our own.", objectives = "" }
WordHunterWoW_QuestEN[37183] = { title = "The Critical Path", description = "The auburn forests of Talador sit at a critical crossroads of this continent, commander. The Iron Horde's fleet is already en route from Gorgrond to Shattrath on the west coast.\n\nTalador will fall if we don't reinforce them. I took the liberty of dispatching Foreman Eksos, who has already begun construction on an outpost for your forces not far from the Iron Horde landing point. He awaits your orders sir.", objectives = "" }
WordHunterWoW_QuestEN[37184] = { title = "Taking the Fight to Nagrand", description = "Commander, good to see you. With the fall of the rangari base at Telaar, Vindicator Yrel, recommended that we establish a new foothold in Nagrand.\n\nI've taken the liberty of dispatching some of our men and supplies. Rangari D'kaan's already reporting that the outpost is nearly complete. He asked me to let you know they are ready for you.\n\nA gryphon is waiting to catch you up with the latest caravan shipment whenever you're ready, sir.", objectives = "" }
WordHunterWoW_QuestEN[37191] = { title = "Sanketsu, The Burning Blade", description = "The blade is searing hot to the touch. The jewel on its hilt stares at you, as if daring you to claim it.\n\nPerhaps someone at your garrison would be interested in seeing this weapon.", objectives = "" }
WordHunterWoW_QuestEN[37192] = { title = "Sanketsu, The Burning Blade", description = "The blade is searing hot to the touch. The jewel on its hilt stares at you, as if daring you to claim it.\n\nPerhaps someone at your garrison would be interested in seeing this weapon.", objectives = "" }
WordHunterWoW_QuestEN[37201] = { title = "Cymre Brightblade", description = "I found some interesting artifacts on a recent dig, and I'd love to put them through their paces to see how they would have performed in their native cultures.  Don't suppose you have anything small and furry that can put up a fight?", objectives = "" }
WordHunterWoW_QuestEN[37203] = { title = "Ashlei", description = "I don't really like when my pets fight, but I love making them feel better when they're done.", objectives = "" }
WordHunterWoW_QuestEN[37204] = { title = "Rekindling an Old Flame", description = "I am dying, {race}. My flame, it smolders... soon my light will flicker and fade into nothing.\n\nYou mustn't allow this. Retrieve for me the Essence of Flame. Allow me to live another day and I will burn every breaker to ash, I swear it.\n\nI will take vengeance for my brothers and sisters.", objectives = "" }
WordHunterWoW_QuestEN[37205] = { title = "Gargra", description = "Do you wish to offer challenge?  My wolves must train to become strong.", objectives = "" }
WordHunterWoW_QuestEN[37206] = { title = "Tarr the Terrible", description = "Tarr is the true warlord!  Bring your army to fight and I show you.", objectives = "" }
WordHunterWoW_QuestEN[37207] = { title = "Vesharr", description = "I had a vision with one who had mastered pets came to challenge me.  Has the vision finally come to pass?", objectives = "" }
WordHunterWoW_QuestEN[37208] = { title = "Taralune", description = "I strive to teach through non-lethal pet battle.  Are you willing to learn?", objectives = "" }
WordHunterWoW_QuestEN[37209] = { title = "Cold Steel Part II", description = "Hey, you.\n\nI wanted to thank you for what you did for me. The feel of that cannon in my hands is all the therapy I'll ever need. But now...\n\n<Keeshan stares off into the distance and grimaces.>...I'm all out of bullets.\n\nGuess I'll just sit here and wait to die.", objectives = "" }
WordHunterWoW_QuestEN[37227] = { title = "Put a Bird on It", description = "{name}! Have you met the peachick you saved the other day?\n\n<Mylune holds up a peachick hatchling, then trills and twitters at it. She gestures to you, says your name, then continues chirping animatedly to the little bird. The two ignore you and engage in a lengthy bird-conversation, long enough to make you feel awkward. Finally the dryad turns her attention back to you.>\n\nDid you hear that? More peachicks are still trapped in the Everbloom! If you don't save them... well, you heard what will happen!", objectives = "" }
WordHunterWoW_QuestEN[37228] = { title = "A Fruitful Proposition", description = "The head of just ONE ogre won't be enough to stop the fruit vendor. No, the fruit vendor is wise, they would not put all of their fruit into one basket.\n\nBring me the head of ANOTHER ogre! Ha! Then what will the fruit vendor do? Cry onto their bananas as they rot and fall to the ground.\n\nDESPAIR, FRUIT VENDOR. SO DELICIOUS!", objectives = "" }
WordHunterWoW_QuestEN[37229] = { title = "Like A Dwarf In A Mine", description = "Baelog and Eric swear there's got to be treasure at the bottom of the mine. Why? Because it's a mine! An' we sure do love rocks that sparkle.\n\nOn our last trip, we were beaten back by huge ogres. Baelog held up the rear, swingin' his sword, while Eric rushed on ahead to try and find a quick exit.\n\nWouldn't you know, in all that excitement, I done lost my shield AGAIN?\n\n<Olaf looks at you imploringly.>", objectives = "" }
WordHunterWoW_QuestEN[37230] = { title = "Bloody Expensive", description = "Welcome back, commander. The commander is obviously in a great hurry, and certainly the thought of removing their coat or boots or not dripping all over the floor are much too far beyond consideration.\n\nThe commander remembers the acidic solution, yes? Quite effective it was, though one barrel was not enough to remove ALL of the blood stains from the portraits, or the tapestries, or the ceiling.\n\nSurely this must have been the most heroic and viscous battle in recent history.", objectives = "" }
WordHunterWoW_QuestEN[37231] = { title = "The Search Continues", description = "An old deckhand inspected that device you brought us, and thinks it was quite the forgery. This Iron Horde is trying to copy the mechanism, but they don't quite have the technology.\n\nWhen you get right down to it, we're not sure how these primitive beasts got a hold of this kind of tool. Wouldn't be half as good of a sea tale if we knew, ha!\n\nWe've still got a pile of treasure with your name on it, if you can find us the real compass.", objectives = "" }
WordHunterWoW_QuestEN[37232] = { title = "Soulcarver Voss", description = "You! You're the one that found me the blade, correct? I have need of your services again.\n\nThe blade worked wonderfully, allowing me to sever the tormented undead from this world. Their screams were such beautiful music.\n\nHowever, the Soulsever Blade cannot be repaired, as it is partially woven with spirit energy that is drawn upon each time a soul is released. I need another, as there are still dark forces at work in this place, raising spirits and turning them.", objectives = "" }
WordHunterWoW_QuestEN[37233] = { title = "Vessel of Virtue", description = "Hello, again, commander. This plague yet vexes me, but I shall remain resolute, with the light as my guide.\n\nThe Soulweave Vessel has aided our investigations into the world beyond and the transition from life to death. With more vessels, we may be able to discover the truth behind the bridge between worlds. Perhaps there is a reason why the scourged do not fully make this transition.\n\nAny additional help would be greatly appreciated by the Argent Dawn.", objectives = "" }
WordHunterWoW_QuestEN[37234] = { title = "The Dark Within", description = "The light... has gone out. I know not why.\n\nI am more troubled now than before. I can find little comfort in the everyday. Each day seems darker than the last.\n\nPlease, bring me another one of the Sun Crystals. Its light is so warm, so comforting.", objectives = "" }
WordHunterWoW_QuestEN[37235] = { title = "A Plea to the Sky", description = "We have, so far, been unsuccessful in our attempts to contact the arakkoa. Each attempt strips the plumage, and we are left with a feather that is tattered and broken.\n\nAviana implores you, commander, to find another plume for her. We do not wish to see our brethren become victim of their own violent nature. All beings of the sky have a place with us, in life or beyond.", objectives = "" }
WordHunterWoW_QuestEN[37236] = { title = "Like Father, Like Son", description = "He's done it again! My son took my knife and yelled something about a 'chromatic hide,' then ran off for the Spire! What would he even do with something like that, wear it around like a cape?\n\nIf it's not too much to ask, would you keep an eye out for the knife? You know, next time you're around Upper Blackrock Spire. Which, hopefully, is soon. VERY soon.", objectives = "" }
WordHunterWoW_QuestEN[37237] = { title = "A Hero's Quest is Never Complete", description = "What ho, squire {name}! Since last we spoke, I have heroically approached the gates of Blackrock Spire and nobly intended to end the toothy reign of its dragons.\n\nYet, as I neared the place, my mind drifted to thoughts of my Doloria's fair face, and to my own painfully unsatisfied desires.\n\nMy sword arm fell limp at my side.\n\nI charge THEE then, squire, to go in my stead and search Upper Blackrock Spire. I must know if the dragons still squirm within its corridors.", objectives = "" }
WordHunterWoW_QuestEN[37238] = { title = "Secrets of Soulbinding", description = "We have reviewed Ner'zhul's notes, which you brought to us previously. Though we are closer to understanding how these warlocks have learned to bind souls and control the undead, the picture is incomplete.\n\nWe will need more pages if we are to see the whole picture. I do not want to experiment with partial information and create an abomination. There are enough of those in Northrend as it is.", objectives = "" }
WordHunterWoW_QuestEN[37239] = { title = "Fate of the Fallen", description = "I feel that I can trust you, perhaps. You have, at least, not spoken of my secret to anyone, and for that I thank you.\n\nI have need of your aid again, and in return, I will share some of my own information. I am here, you see, to find an elf by the name of Alleria. She was lost years ago, on Draenor. It is my faint hope that the twisting nether brought her here.\n\nI do not know if such a thing is even possible, but do keep an eye out for any signs of high elves as you travel.", objectives = "" }
WordHunterWoW_QuestEN[37240] = { title = "The Leaf-Reader", description = "Good ta see you again, mon!\n\nDe Cenarion Circle sent Zen'kiki out here ta find some more of dem plants. We not likin' what we be seein' here.\n\nIf ya find any more of dem leaves, bring one on back. Dey can see right through Zen'kiki's tree disguise, even when he plant himself in da ground!\n\nAnd dat make it harder to run!", objectives = "" }
WordHunterWoW_QuestEN[37241] = { title = "Lessons of the Past", description = "I have returned! You must have known that a world so rich in history could not keep me away for long!\n\n<Lorewalker Cho chuckles, holding his enormous belly.>\n\nI have perhaps been taking part in too many celebratory feasts, now that the Vale has been cleansed. There is so much to celebrate in Pandaria!\n\nShould you find any future evidence of titanic influence on the native species, I will be here, heartily enjoying the roast clefthoof.", objectives = "" }
WordHunterWoW_QuestEN[37242] = { title = "Learning Is Painful", description = "The academy is up and running, in a secret location of course. Maybe it doesn't exist at all?\n\nBy the by, I appear to be running quite dry on sharp, pointy instruments of education.\n\n<Lonika winks at you several times before nudging you sharply in the ribs with her dagger.>", objectives = "" }
WordHunterWoW_QuestEN[37243] = { title = "An Axe to Grind", description = "I, Gamon, have cleaved many orc skulls. Yet many of the iron horde remain, full of limbs and blood. I will relieve them of these things!\n\nOr I would, if I had an axe. The last one broke in half in the middle of an orc's ribcage.\n\n<Gamon laughs heartily.>\n\nBring me another, so that I may continue cleaving my way through this land!", objectives = "" }
WordHunterWoW_QuestEN[37244] = { title = "Flamefly Trap", description = "Ol' Winky still hasn't come back! Now I'm gettin' worried.\n\nDo me a favor and get another one of those flameflies from Upper Blackrock Spire. If we get enough of em,' Winky's sure to see the glimmer and come heading on back.\n\nAn then we'll have him right where we want him!", objectives = "" }
WordHunterWoW_QuestEN[37245] = { title = "Whispers in the Darkness", description = "If you don't mind, I'm trying VERY hard to prevent all of our worlds from collapsing into the void, AGAIN.\n\nOh, right, you helped me last time, didn't you? Well, you've got great timing. I'm in need of another Gate-Key.\n\nWell? Go on! The infinite horrors of the abyss aren't just going to wait until you've had a nap! Having that many tentacles makes them really antsy.", objectives = "" }
WordHunterWoW_QuestEN[37256] = { title = "They Came From the Sea", description = "You're looking for Prince Farondis?\n\n<The ghostly elf narrows her eyes warily.>\n\nI can take you to Farondis... but first things first. These naga attacked suddenly. They take orders from one called Zarrin, in the low hills to the west.\n\nHelp me take Zarrin's head, and you'll have my ear.", objectives = "" }
WordHunterWoW_QuestEN[37257] = { title = "Our Very Bones", description = "You seek the Tidestone of Golganneth?\n\nYes, I know where it lies. It is in a place to which I prefer not to return.\n\nYou may be of use to me. In the midst of this naga attack, those horrid fish-men flopped their way onto my lands and raided our graveyards. They steal the bones of our ancestors, and indeed, the very bones of my people.\n\nHelp me bring some solace to my people. Then I shall tell you more about the Tidestone.", objectives = "" }
WordHunterWoW_QuestEN[37270] = { title = "Alchemy Experiment", description = "", objectives = "" }
WordHunterWoW_QuestEN[37276] = { title = "Standing United", description = "", objectives = "" }
WordHunterWoW_QuestEN[37281] = { title = "Standing United", description = "", objectives = "" }
WordHunterWoW_QuestEN[37284] = { title = "Da Big Score", description = "I know, I know. I be givin' ya these for ya treasures, but now I be wantin' dem back. It be complicated, mon. Do ya want da gold or not?", objectives = "" }
WordHunterWoW_QuestEN[37286] = { title = "The Bloodshed Never Ends", description = "You are insatiable, gladiator! Let none doubt your voracious appetite for destruction and death!\n\nImperator Mar'gok will be very pleased to see you battling upon the arena floor of the Coliseum once more!\n\nAs before, I will accept nothing less than 100 lives!\n\nKill or be killed, gladiator!", objectives = "" }
WordHunterWoW_QuestEN[37287] = { title = "Cleaning House", description = "Not long ago, a new recruit showed up by the name o' Jacob Anders. He's been trouble since he got here, always drinkin' and pickin' fights, but he crossed the line this time.\n\nOne o' our patrols spotted him tradin' intel with the Horde - he's a traitor, commander! I thought ye would want tae deal with him personally.\n\nHe was out drinkin' by the water last time I saw him, and I'd bet me pappy's beard he's still there.", objectives = "" }
WordHunterWoW_QuestEN[37288] = { title = "Resources in Ashran", description = "Bodrick has mentioned to me that you have acquired some interesting construction notes in your forays out there. A construction guide or assembly notes perhaps?\n\nYou should speak with Kinkade Jacobs in Stormshield. She is willing to exchange finished blueprints for such things.", objectives = "" }
WordHunterWoW_QuestEN[37289] = { title = "Shadowmoon Invasion!", description = "Your arrival couldn't be more timely, commander.\n\nShadowmoon raiders have been spotted closing in on the garrison.\n\nYou repelled their advances at Teluuna Observatory, and created chaos at Shaz'gul.\n\nNow, they surely seek retribution. They will throw everything they have at us.\n\nI have the entire garrison on high alert. Are you ready to face them?", objectives = "" }
WordHunterWoW_QuestEN[37290] = { title = "Upgrades in Ashran", description = "You got some construction guides or assembly notes on ya? Oh man that's good news!\n\nI know this guy in Ashran, goes by Torgg Flexington. He's got finished blueprints we need!\n\nGo talk to this guy and bring back some good stuff for us to build, ok?", objectives = "" }
WordHunterWoW_QuestEN[37291] = { title = "Thunderlord Invasion!", description = "Your timing could not have been better.\n\nYour scouts have reported the approach of a large Thunderlord army.\n\nMy clan can ride out and assist in severing their reinforcements, but you will need to see to the defense of your fort against the bulk of their forces.\n\nSergeant Grimjaw awaits your command.", objectives = "" }
WordHunterWoW_QuestEN[37292] = { title = "Not In Your Army", description = "Your men caught one of da new recruits,  talking with da alliance behind your back. She be a traitor, boss-mon! She be a danger to everything you've worked so hard for.\n\nWe have a wyvern ready to be takin' her to your garrison for proper punishment. I thought you would be wantin' to deal with da scoundrel personally.\n\nI last be seein' her on the back road out of Axefall.", objectives = "" }
WordHunterWoW_QuestEN[37293] = { title = "Clearing the Mist", description = "<The troll's skin looks pale. Beads of sweat dot his brow.>\n\nI know you owe me nouting, but if you be willin' ta help me, I have a favor to ask.\n\nTa da north, dere be da creature dat is da cause a' dis poisonous mist.\n\nOnly da heart a' dis beast has da power ta neutralize da toxins in my body.\n\nYa may have ta kill some a dose crawlers while you're at it.\n\nIf ya feel weak from da poison, eat some a dose glowing mushrooms ta counter da effects.", objectives = "" }
WordHunterWoW_QuestEN[37296] = { title = "A Lack of Wasps", description = "The stings! These cursed wasps drone day and night and their constant aggression taxes me so.\n\nI shall do nothing about your offer until these nuisances are dealt with.", objectives = "" }
WordHunterWoW_QuestEN[37305] = { title = "Bronze Victory", description = "Surrounded as we are, we cannot be weak. We must win every battle, and win them decisively.", objectives = "" }
WordHunterWoW_QuestEN[37306] = { title = "Silver Victory", description = "The harder we beat our enemies, the less quickly they'll return.", objectives = "" }
WordHunterWoW_QuestEN[37307] = { title = "Gold Victory", description = "The stronger our enemies, the more soundly we must beat them. With so much at stake, a single weak blow could prove disastrous.\n\nLead us to great victory, Commander.", objectives = "" }
WordHunterWoW_QuestEN[37318] = { title = "The Dead Do Not Forget...", description = "Many years ago my family and I were slain in this very spot.\n\nThe saberon you see around you are descended from the tribe that murdered my village. Long have I waited, here in this forgotten place, to see justice brought to the saberon for their crimes.\n\nThe Snarlpaw chief is a boneseer, a saberon who divines the future using the remains of the dead.\n\nCollect the ancient skulls of the Snarlpaw ancestors and place them in the boneseer's cauldron.\n\nLet their own bones fill their cauldron for once!", objectives = "" }
WordHunterWoW_QuestEN[37319] = { title = "Jewelcrafting Special Order:  Wedding Bands", description = "We've been asked to craft a pair of wedding bands. The clients requested that they be made by you.", objectives = "" }
WordHunterWoW_QuestEN[37320] = { title = "Jewelcrafting Special Order:  A Fine Choker", description = "We have a request for a fine necklace. The client wants to give it to an old enemy, to end the conflict. She didn't specify a design, but I think I heard her mumbling under her breath about a choker. \n\nOh, and she asks that the chain be \"extra sturdy\".", objectives = "" }
WordHunterWoW_QuestEN[37321] = { title = "Jewelcrafting Special Order:  A Yellow Brighter Than Gold", description = "We've been commissioned to make a gold bracelet, set with a taladite crystal \"even brighter than gold\". I can handle the metal work, but the crystal isn't something I can do.", objectives = "" }
WordHunterWoW_QuestEN[37322] = { title = "The Prophet's Final Message", description = "This unassuming iridescent crystal contains some of the final thoughts of Great Prophet Velen, created sometime in the hours before he confronted Ner'zhul.\n\nDeliver the crystal to Prophet Velen's Memorial beneath the Coliseum of Light near Karabor to hear his final message.", objectives = "" }
WordHunterWoW_QuestEN[37323] = { title = "Jewelcrafting Special Order:  Blue the Shade of Sky and Sea", description = "The client wants a pair of silver earrings, set with blue crystals to match her eyes. The metal work is simple enough, but I don't know how to create such a shade of taladite.", objectives = "" }
WordHunterWoW_QuestEN[37324] = { title = "Out of Stock: Blackrock Ore", description = "Our latest bracelet design is selling like mad, but we are completely out of the blackrock to make them.", objectives = "" }
WordHunterWoW_QuestEN[37325] = { title = "Out of Stock: True Iron Ore", description = "It seems our little boutique is gaining a reputation.  We use true iron in all our designs, and guess what: we're out!", objectives = "" }
WordHunterWoW_QuestEN[37326] = { title = "Befriending the Locals", description = "We need allies desperately if we want a chance at surviving until tomorrow. We've made contact with one of the outcast arakkoa, but he refused to discuss alliances without speaking to you first.\n\nHe called himself Dusk-Seer Irrizar. You should speak with him, commander.\n\nYou can find him just southwest of Veil Terokk.", objectives = "" }
WordHunterWoW_QuestEN[37327] = { title = "Befriending the Locals", description = "Commander, I believe it best for the safety of this outpost if we secure an ally. We've made contact with one of the outcast arakkoa, but he refused to make any promises of alliance without speaking to you first.\n\nHe called himself Dusk-Seer Irrizar. Could you go speak with him, commander?\n\nYou can find him just southwest of Veil Terokk.", objectives = "" }
WordHunterWoW_QuestEN[37328] = { title = "Not Here, Not Now", description = "I will travel to your people to make arrangements soon.\n\nFor now, begone. Leave me in peace.", objectives = "" }
WordHunterWoW_QuestEN[37329] = { title = "Not Here, Not Now", description = "I will travel to your people to make arrangements soon.\n\nFor now, begone. Leave me in peace.", objectives = "" }
WordHunterWoW_QuestEN[37330] = { title = "Not Here, Not Now", description = "I will travel to your people to make arrangements soon.\n\nFor now, begone. Leave me in peace.", objectives = "" }
WordHunterWoW_QuestEN[37331] = { title = "Not Here, Not Now", description = "I will travel to your people to make arrangements soon.\n\nFor now, begone. Leave me in peace.", objectives = "" }
WordHunterWoW_QuestEN[37332] = { title = "Fungal Bundle", description = "The umbraspore giant you killed seemed immune to the volatile spores in the area. Perhaps the odd growths you found all over its body contribute to its immunity. You grab a big, disgusting fungal lump in order to give it to the rangari for study.", objectives = "" }
WordHunterWoW_QuestEN[37416] = { title = "Feast of the Spires", description = "Boss-mon, I prepared a great feast for you right over dere. You should be havin' a bite or two before you be goin' out for da day.\n\nTrust me, you will feel much betta if you do!", objectives = "" }
WordHunterWoW_QuestEN[37417] = { title = "Feast of the Spires", description = "Commander, I prepared a great feast for ye right over there. You should be have a bite o' two before you be go out fer the day.\n\nTrust me, it's good fer ya!", objectives = "" }
WordHunterWoW_QuestEN[37418] = { title = "Fully Armed and Operational", description = "Commander! Great news! Now that the workshop is fully armed and operational, we can start cranking out siege weapons just as soon as we have the resources.\n\nThe Overcharged Demolisher is the pinnacle of goblin engineering, if I do say so myself. It's more powerful than your average demolisher, and you can use it almost anywhere! The only limit is the amount of fuel we're able to pack into the chasis.\n\nAs soon as you're ready to begin production, just bring us some resources and place a work order!", objectives = "" }
WordHunterWoW_QuestEN[37420] = { title = "Fully Armed and Operational", description = "Commander! Great news! Now that the workshop is fully armed and operational, we can start cranking out siege weapons just as soon as we have the resources.\n\nThe Overcharged Siege Engine is the pinnacle of gnomish  engineering, if I do say so myself. It's more powerful than your average siege engine and you can use it almost anywhere! The only limit is the amount of fuel we're able to pack into the chasis.\n\nAs soon as you're ready to begin production, just bring us some resources and place a work order!", objectives = "" }
WordHunterWoW_QuestEN[37433] = { title = "Proving Grounds", description = "Greetings commander.\n\nWord of your exploits has made its way back to Trial Master Rotun, and he has humbly requested to see your prowess in person. Fighting in his proving grounds would be an excellent way to spread your reputation to the farthest reaches of the Alliance, and beyond.\n\nIf you're interested in proving yourself, talk to me to enter Trial Master Rotun's Proving Grounds.", objectives = "" }
WordHunterWoW_QuestEN[37434] = { title = "Proving Grounds", description = "Hail commander.\n\nWord of your exploits has made its way back to Trial Master Rotun, and he has requested to see your prowess in person. Fighting in his proving grounds would be an excellent way to spread your reputation to the farthest reaches of the Horde, and beyond.\n\nIf you're interested in proving yourself, talk to me to enter Trial Master Rotun's Proving Grounds.", objectives = "" }
WordHunterWoW_QuestEN[37439] = { title = "Thirst Unending", description = "If there is only one lesson you deign to remember from your time on Sunstrider Isle, let it be this - control your thirst for magic.  It is a thirst unending, {name} - what you absorb must be controlled and released via Arcane Torrent.  Failure is to become one of the Wretched... hopelessly addicted and insane.\n\nSeek out a mana wyrm and unleash your Arcane Torrent upon it.  Learn to master your power. When you have sufficiently released an Arcane Torrent, return to me.", objectives = "" }
WordHunterWoW_QuestEN[37440] = { title = "A Fistful of Slivers", description = "It's a shame that we've lost control of many of the creatures here on the island.  This was once a tranquil place of study and research.  Now it's all we can do to keep from being attacked by our own creations!\n\nI'm going to offer you a chance to receive a magical boon in exchange for some collecting work on your part.  Bring me a stack of arcane slivers that are found on the mana-using creatures of Sunstrider Isle, and I will cast a spell on you that should aid your adventures on the isle.", objectives = "" }
WordHunterWoW_QuestEN[37442] = { title = "The Shrine of Dath'Remar", description = "Day after day I stand here, watching, waiting.  I've been accused of dwelling too much on our past, while my eyes look to the horizon.  But it is my firm belief that each visitor to this island should honor those who have sacrificed all so that they may continue to do so.\n\nDath'Remar Sunstrider was our first king.  He led us here from Kalimdor through the Maelstrom.\n\nSeek out his shrine to the west and do not return to me until you have read the plaque upon it in his honor.", objectives = "" }
WordHunterWoW_QuestEN[37443] = { title = "Solanian's Belongings", description = "With all the chaos happening here at the Sunspire, I haven't had a chance to collect my belongings I've left outside at various places on the isle.  I must maintain my vigil over the Sunwell here, so I'll ask you to collect them in my stead.\n\nI need my scrying orb, my scroll of Scourge magic, and my journal.  Use this satchel for some extra space, as my things are rather bulky.  Return them to me and I'll give you a little something - you know, for the effort; you can keep the satchel as well!", objectives = "" }
WordHunterWoW_QuestEN[37444] = { title = "Inoculation", description = "Zhanaa needs our help to salvage parts from the Exodar.  Taerix prepared an inoculum that can be given to the Nestlewood owlkin that live in the area of a lot of the salvage.\n\nJust get close to the unaffected ones and use the crystal on them.  Unfortunately, you'll have to kill the others.  You'll find the owlkin at Nestlewood Thicket and Nestlewood Hills to the southeast.", objectives = "" }
WordHunterWoW_QuestEN[37445] = { title = "Spare Parts", description = "We managed to recover a damaged holographic emitter from the crash. If we repair it, we'll have a chance to find other survivors outside of Ammen Vale.\n\nThere were devices from the ship that could be salvaged for spare parts in the area, but the local owlkin carried them off before we could get to them. \n\n{name}, you must go south to Nestlewood Thicket and Hills to find the spare parts.", objectives = "" }
WordHunterWoW_QuestEN[37446] = { title = "Lazy Peons", description = "Cursed peons! They work hard gathering lumber from the trees of the valley, but they're always taking naps! I need someone to help keep the peons in line.\n\nYou look like the right {race} for my task. Here, you take this blackjack and use it on any lazy peons you find sleeping on the job. A good smack will get them right back to work! Return the blackjack when you're done.\n\nLook for them underneath the trees in the valley. Lousy slacking peons...", objectives = "" }
WordHunterWoW_QuestEN[37447] = { title = "The Blood of Demons", description = "The time has come to make contact with the Master's soul. It is somewhere in the endless expanse of the Twisting Nether. Luckily, so is Mardum.\n\nSuch a thing is not unheard of, but it will be exceedingly difficult, even here. In addition to what the matron mother had us gather, we need a great deal of demon blood.\n\nLike, a lot of it!", objectives = "" }
WordHunterWoW_QuestEN[37448] = { title = "A Simple Plan", description = "Like many dreadlords, Detheroc cannot help but gloat. He was careless and I overheard many of his plans while I was held captive.\n\nWith your leave, I would like to underscore the gravity of the situation in Stormwind. The fate of Azeroth hangs in the balance.\n\nBut for all of that, I have a simple plan: get 'em.", objectives = "" }
WordHunterWoW_QuestEN[37449] = { title = "Dark Revelations", description = "I'm not going to let Cordana Felsong get away with this. There is no way in hell I am going to let that warden witch turn my people.\n\nAs for Nightglaive... I will NOT suffer a traitor to live!\n\nAre you with me, {name}?", objectives = "" }
WordHunterWoW_QuestEN[37450] = { title = "Saving Stellagosa", description = "During the fighting, of all things, I saw a blue drake swoop in and attack the demons. I couldn't believe my eyes. I'd heard that the Blue Dragonflight had gone extinct.\n\nThe Legion managed to bring the drake down, but not until after she'd killed a score of them. She was magnificent. Last I saw, they were dragging her in the direction of the southern camp.\n\nWe should see if she's still alive. A dragon could prove a powerful ally.", objectives = "" }
WordHunterWoW_QuestEN[37452] = { title = "Sealing Fate: Heap of Apexis Crystals", description = "Twice the cost of the last, but maybe that's worth the price. Or, perhaps a different currency would be more efficient for you?  I leave the choice up to you.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I may have others.", objectives = "" }
WordHunterWoW_QuestEN[37453] = { title = "Sealing Fate: Mountain of Apexis Crystals", description = "Four times the cost of the first, but only one seal.  Remember, I still offer more efficient options, but I never refuse someone who is insistent on paying me more. I leave you the choice.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I may have others.", objectives = "" }
WordHunterWoW_QuestEN[37454] = { title = "Sealing Fate: Piles of Gold", description = "Twice the cost of the last, but maybe that's worth the price. Or, perhaps a different currency would be more efficient for you?  I leave the choice up to you.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I may have others.", objectives = "" }
WordHunterWoW_QuestEN[37455] = { title = "Sealing Fate: Immense Fortune of Gold", description = "Four times the cost of the first, but only one seal.  Remember, I still offer more efficient options, but I never refuse someone who is insistent on paying me more. I leave you the choice.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I may have others.", objectives = "" }
WordHunterWoW_QuestEN[37456] = { title = "Sealing Fate: Stockpiled Garrison Resources", description = "Twice the cost of the last, but maybe that's worth the price. Or, perhaps a different currency would be more efficient for you?  I leave the choice up to you.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I may have others.", objectives = "" }
WordHunterWoW_QuestEN[37457] = { title = "Sealing Fate: Tremendous Garrison Resources", description = "Four times the cost of the first, but only one seal.  Remember, I still offer more efficient options, but I never refuse someone who is insistent on paying me more. I leave you the choice.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I may have others.", objectives = "" }
WordHunterWoW_QuestEN[37458] = { title = "Sealing Fate: Extended Honor", description = "Twice the cost of the last, but maybe that's worth the price. Or, perhaps a different currency would be more efficient for you?  I leave the choice up to you.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I may have others.", objectives = "" }
WordHunterWoW_QuestEN[37459] = { title = "Sealing Fate: Monumental Honor", description = "Four times the cost of the first, but only one seal.  Remember, I still offer more efficient options, but I never refuse someone who is insistent on paying me more. I leave you the choice.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I may have others.", objectives = "" }
WordHunterWoW_QuestEN[37467] = { title = "The Walk of Shame", description = "The echoes of Nar'thalas still haunt me, and I cannot bear the pain of this accursed town any longer. I may still be able to get you closer to the Tidestone, however.\n\n<Farondis' eyes narrow in newfound determination.>\n\nWe will need to skirt around the edge of town. Follow me.", objectives = "" }
WordHunterWoW_QuestEN[37468] = { title = "Into the Academy", description = "The sunken structure on the other side of this bridge was once called Nar'thalas Academy: the center of magical studies in all of Azeroth. You should have seen her in her full splendor.\n\nThe Tidestone should be locked up within. I dare not enter, but you - my champion - you go with my blessing.", objectives = "" }
WordHunterWoW_QuestEN[37469] = { title = "The Tidestone: Shattered", description = "I suppose you can go in, then.\n\nThe shattered pieces of the Tidestone of Golganneth are contained within the academy's eastern wing. Even as curator, I cannot attest to their condition, as I have not been in to inspect them in many millennia.\n\nOh, young {name}? Please do not touch anything.", objectives = "" }
WordHunterWoW_QuestEN[37470] = { title = "The Head of the Snake", description = "Those naga have the Tidestone shards, {name}. They will soon be dragging them into their watery holes, away from our reach.\n\nIt would be wise to take out their leaders before that happens.", objectives = "" }
WordHunterWoW_QuestEN[37474] = { title = "Basics First", description = "Great spirit, {name}, but you have to learn the basics of pet battles first.  Visit Audrey Burnhep in Stormwind City, and she'll get you started.", objectives = "" }
WordHunterWoW_QuestEN[37479] = { title = "Bonus Objective: Kill Alliance Leaders", description = "", objectives = "" }
WordHunterWoW_QuestEN[37480] = { title = "Bonus Objective: Kill Alliance Leaders", description = "", objectives = "" }
WordHunterWoW_QuestEN[37481] = { title = "Bonus Objective: Kill Horde Leaders", description = "", objectives = "" }
WordHunterWoW_QuestEN[37482] = { title = "Bonus Objective: Kill Horde Leaders", description = "", objectives = "" }
WordHunterWoW_QuestEN[37486] = { title = "Nar'thalas Still Suffers", description = "They have not forgiven me. I cannot blame them.\n\nPast crimes aside, I am still their prince. Even in death, I will do what I can to protect my people.\n\n{name}. Act as my champion. Find and defeat the creature that leads this naga attack against the people of Nar'thalas. After all these years, you - a {race} {class}, of all things - may be the instrument of my redemption.", objectives = "" }
WordHunterWoW_QuestEN[37492] = { title = "A Rather Long Walk", description = "I'm concerned for Elder Aldryth. He went out for a walk about ten thousand years ago, and he has not returned.\n\nWith these naga attacking, I fear he may be in danger!\n\nIf you dare venture out into the fray, do look out for our court elder.", objectives = "" }
WordHunterWoW_QuestEN[37494] = { title = "Under Cover of Darkness", description = "We are off to Stormwind. Tethys will sneak us by water beneath the old barracks under cover of darkness tonight.\n\nThe rest will be up to you, Mathias, and myself. We will have to stealth through Stormwind and confront Detheroc at SI:7.\n\nAre you ready to do this, {name}?", objectives = "" }
WordHunterWoW_QuestEN[37496] = { title = "Infiltrating Shipwreck Arena", description = "The giants at Shipwreck Arena are very fond of smashing ships that sail too close to shore. They take the sailors prisoner and use them for their own amusement.\n\nI suppose it will be easy for you to infiltrate the place. It's breaking out that will be the difficult part.", objectives = "" }
WordHunterWoW_QuestEN[37497] = { title = "Trailing the Tidestone", description = "Your quest for the Tidestone... it intrigues me. More than that, it suits my needs quite well. I have been in need of a champion for a very, very long time.\n\nIt is decided, then. I shall join you.\n\nWe will have to head east, through Nar'thalas.\n\nShall we depart?", objectives = "" }
WordHunterWoW_QuestEN[37507] = { title = "Boss Whalebelly's in Charge", description = "Great, let's get started! If we're going to break everyone out of here, you need to pose as a pit fighter like the rest of us. They won't just let you run around anywhere you want in here.\n\nFirst thing you need to do is present yourself to Boss Whalebelly. The giants may run this place, but as far as posing as one of us, Whalebelly's in charge.\n\nHe's speaking with his goons just to the south.", objectives = "" }
WordHunterWoW_QuestEN[37510] = { title = "Sternfathom's Champion", description = "Since you defeated Ooker Dooker, there's a pit fighter spot open on Sternfathom's team. You should go establish yourself as his champion. That way, the giants won't think twice about why a stranger is suddenly coming and going as he pleases.\n\nMeanwhile, I'll start to sow some chaos so that we can strike at Prince Oceanus.", objectives = "" }
WordHunterWoW_QuestEN[37511] = { title = "Dizzy Sparkshift", description = "I'm in a pretty good spot as far as artifacts go.\n\nWe have a couple other society members out in the field. I'd go look for them, but it seems like a bad idea from a health perspective.\n\nYou don't seem to have a problem with pain, think you could find Dizzy?", objectives = "" }
WordHunterWoW_QuestEN[37516] = { title = "News for Nixxie", description = "Nixxie is probably worried sick about the potential loss of profits from this surveying operation.\n\nIf you see her can you let her know we will be back soonish?", objectives = "" }
WordHunterWoW_QuestEN[37517] = { title = "News for Nixxie", description = "Nixxie is probably worried sick about the potential loss of profits from this surveying operation.\n\nIf you see her can you let her know we will be back soonish?", objectives = "" }
WordHunterWoW_QuestEN[37518] = { title = "The Haunted Halls", description = "Now, what was it you wanted? You're here to see the Tidestone of Golganneth? Hah! Ho ho ha ha haa!\n\nHooo my.\n\nNo, only the academy's headmistress has the keys to that chamber, and she hasn't opened the door in... oh, I'd say about ten thousand years.\n\nYou'd best be off to class, now. Go on, then! Into the west wing with you!", objectives = "" }
WordHunterWoW_QuestEN[37523] = { title = "Assault on the Gorian Proving Grounds", description = "The ogres at the Gorian Proving Grounds are rousing champions to turn against our forces in Nagrand.\n\nA decisive assault on their training grounds should prevent them from mustering the forces they need to stand against us, and will help remind them that we are not an enemy they want to make.", objectives = "" }
WordHunterWoW_QuestEN[37524] = { title = "Assault on the Gorian Proving Grounds", description = "The ogres at the Gorian Proving Grounds be rousin' champions to turn against our forces in Nagrand.\n\nA decisive assault on their training grounds should prevent dem from musterin' the forces dey be needin' to stand against us, and will help remind them that we are not an enemy they want to be makin'.", objectives = "" }
WordHunterWoW_QuestEN[37528] = { title = "Let Sleeping Giants Lie", description = "We're going to need a diversion to get close to Prince Oceanus. Are you thinking what I'm thinking?\n\nSee Sleepy Dhow over there? He's guarding all of the weapons the giants take from our shipwrecks. We can use those weapons to arm the rest of the pit fighters that are held in the caves.\n\nAll you have to do is get past that giant without waking him.", objectives = "" }
WordHunterWoW_QuestEN[37530] = { title = "Save Yourself", description = "Of course I couldn't sit back and let them just cart you away.\n\nI will explain everything.", objectives = "" }
WordHunterWoW_QuestEN[37536] = { title = "Morale Booster", description = "Things may look good from where you're standing, but, we're losing. However, do not fret, my little {race} friend. You can help.\n\nListen closely. Ooka Dooker, Ooker's sister, is back over yonder in the champions' cave making her world famous Fighter Chow. It'll do the trick and boost our team's morale.\n\nAll you have to do is to convince her to hand it over.", objectives = "" }
WordHunterWoW_QuestEN[37538] = { title = "Round 1, Fight!", description = "All of my gladiators are out of commission!\n\nIt's down to you, {name}. Bilgerudder's going to pit his three champions against you.", objectives = "" }
WordHunterWoW_QuestEN[37542] = { title = "No Time for Tryouts", description = "We don't have time for you to go through a lengthy set of tryouts. But, fighting in the arena is our best chance at getting you in good with the giants.\n\nThat kind-hearted giant over there that's losing against Bilgerudder is Sternfathom. If you were to defeat his hozen champion, you'd make yourself a spot on his team.\n\nLooks like Ooker Dooker's taking a rest between bouts. Now's the time to deliver a good ol' monkey beatdown.", objectives = "" }
WordHunterWoW_QuestEN[37563] = { title = "The Frostwolves Stand Ready", description = "Though we have lost much this day, the Frostwolves stand ready to uphold our pact with your people.\n\nTo honor this agreement, some of my clan have asked to join your ranks and fight alongside your forces.\n\nOur numbers are strained so I ask that you chose only one.\n\nSpeak with me when you have made your decision.", objectives = "" }
WordHunterWoW_QuestEN[37565] = { title = "The Right Weapon for the Job", description = "<You and Okuna were going to arm the captives in here. The idea was to free them and cause as much chaos as possible. It's the only sure way to be able to get close to the prince.\n\nYou still have the weapons. You're just going to have to be careful sneaking around the giants.>", objectives = "" }
WordHunterWoW_QuestEN[37566] = { title = "The Prince is Going Down", description = "{name}! I knew you'd come.\n\nQuick, let me out of here and we'll take this giant down.", objectives = "" }
WordHunterWoW_QuestEN[37568] = { title = "Your First Alchemy Work Order", description = "Now that the alchemy lab is complete, we can start producing alchemical catalysts for you. When you have the ingredients, please speak with my assistant to start the first work order.", objectives = "" }
WordHunterWoW_QuestEN[37569] = { title = "Your First Blacksmithing Work Order", description = "Now that the forge is complete, we can start producing truesteel ingots for you. When you have the ingredients, please speak with my assistant to start the first work order.", objectives = "" }
WordHunterWoW_QuestEN[37570] = { title = "Your First Enchanting Work Order", description = "Now that the enchanter's study is complete, we can start producing draenic dust for you. When you have the ingredients, please speak with my assistant to start the first work order.", objectives = "" }
WordHunterWoW_QuestEN[37571] = { title = "Your First Engineering Work Order", description = "Now that the engineering works is complete, we can start producing gearspring parts for you. When you have the ingredients, please speak with my assistant to start the first work order.", objectives = "" }
WordHunterWoW_QuestEN[37572] = { title = "Your First Inscription Work Order", description = "Now that the scribe's quarters are complete, we can start producing war paints for you. When you have the ingredients, please speak with my assistant to start the first work order.", objectives = "" }
WordHunterWoW_QuestEN[37573] = { title = "Your First Jewelcrafting Work Order", description = "Now that the gem boutique is complete, we can start producing taladite crystals for you. When you have the ingredients, please speak with my assistant to start the first work order.", objectives = "" }
WordHunterWoW_QuestEN[37574] = { title = "Your First Leatherworking Work Order", description = "Now that the tannery is complete, we can start producing burnished leather for you. When you have the ingredients, please speak with my assistant to start the first work order.", objectives = "" }
WordHunterWoW_QuestEN[37575] = { title = "Your First Tailoring Work Order", description = "Now that the tailoring emporium is complete, we can start producing hexweave cloth for you. When you have the ingredients, please speak with my assistant to start the first work order.", objectives = "" }
WordHunterWoW_QuestEN[37584] = { title = "Your Second Alchemy Work Order", description = "Place another work order with my assistant. Once it is complete, we will leave it out here for you to collect.", objectives = "" }
WordHunterWoW_QuestEN[37587] = { title = "Your Second Blacksmithing Work Order", description = "Place another work order with my assistant. Once it is complete, we will leave it out here for you to collect.", objectives = "" }
WordHunterWoW_QuestEN[37589] = { title = "Your Second Enchanting Work Order", description = "Place another work order with my assistant. Once it is complete, we will leave it out here for you to collect.", objectives = "" }
WordHunterWoW_QuestEN[37590] = { title = "Your Second Engineering Work Order", description = "Place another work order with my assistant. Once it is complete, we will leave it out here for you to collect.", objectives = "" }
WordHunterWoW_QuestEN[37591] = { title = "Your Second Inscription Work Order", description = "Place another work order with my assistant. Once it is complete, we will leave it out here for you to collect.", objectives = "" }
WordHunterWoW_QuestEN[37592] = { title = "Your Second Jewelcrafting Work Order", description = "Place another work order with my assistant. Once it is complete, we will leave it out here for you to collect.", objectives = "" }
WordHunterWoW_QuestEN[37593] = { title = "Your Second Leatherworking Work Order", description = "Place another work order with my assistant. Once it is complete, we will leave it out here for you to collect.", objectives = "" }
WordHunterWoW_QuestEN[37594] = { title = "Your Second Tailoring Work Order", description = "Place another work order with my assistant. Once it is complete, we will leave it out here for you to collect.", objectives = "" }
WordHunterWoW_QuestEN[37644] = { title = "Mastering the Menagerie", description = "You know the drill.  Defeat the pets in the garrison, and I might have something for you.", objectives = "" }
WordHunterWoW_QuestEN[37645] = { title = "Mastering the Menagerie", description = "You know the drill.  Defeat the pets in the garrison, and I might have something for you.", objectives = "" }
WordHunterWoW_QuestEN[37648] = { title = "Short-Supply Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[37653] = { title = "Demon Souls", description = "I need to extract information about the Burning Legion from these foul creatures. But living, the demons are almost impossible to break.\n\nHowever, like you, I wield a powerful artifact -- the Scythe of Souls.\n\nTake one of my soul gems. If you place it next to a demon's corpse, it will rip the 'soul' out. Then, we will see if the scythe can get them to talk.", objectives = "" }
WordHunterWoW_QuestEN[37654] = { title = "Maritime Law", description = "Good sir, a moment of your time. My fellow salvors and I could not help but notice yon ship that ran aground in the storm last night.\n\nA pity about its crew.\n\n<Mr. Shackles makes empathetic gestures.>\n\nStill, the law's the law. The maritime code is quite clear on the matter. If you find yourself out that way, would you mind terribly checking in on my acquisitions scout, Looper? I would have expected him back for tea some time ago.", objectives = "" }
WordHunterWoW_QuestEN[37656] = { title = "Fel Machinations", description = "My force wiped out the demons' forward base here. But, an imp mother and her brood took the rest of my demon hunters hostage, including Cyana Nightglaive.\n\nWe need to free the Illidari and destroy the Burning Legion.", objectives = "" }
WordHunterWoW_QuestEN[37657] = { title = "Making the World Safe for Profit", description = "Might I ask a small favor, my friend? These creatures in the tide pools to the east are starting to frighten me. Our efforts to trade with them have been rebuffed at every turn with aggression. This is not good; neither for running a business, nor for profit.\n\nSadly, I must admit the time for talk has come to an end.\n\nMight you be willing to serve as my representative in dealing with the denizens of Mak'rura and their \"queen\"?\n\nI can assure you that your efforts will be rewarded commensurately.", objectives = "" }
WordHunterWoW_QuestEN[37658] = { title = "Reignite the Wards", description = "The demons are weakening my defenses. They must be far more powerful than what we've faced before.\n\nWill you help me to reignite the wards to keep the Legion from overrunning our position here?", objectives = "" }
WordHunterWoW_QuestEN[37659] = { title = "The Captain's Foot Locker", description = "I don't care what you do, mate. But, if you get caught, you didn't see me.\n\nI wasn't here.", objectives = "" }
WordHunterWoW_QuestEN[37660] = { title = "The Scythe of Souls", description = "Let's head to the other side of the stand. We will release the demon souls one by one and get the answers that we seek concerning Lord Illidan.\n\nThe Scythe of Souls will ensure that we do.", objectives = "" }
WordHunterWoW_QuestEN[37666] = { title = "Picking a Fight", description = "They're coming, {name}!\n\nI will get to work unlocking these fel-magic chains from the cage.\n\nYou keep the Legion at bay.", objectives = "" }
WordHunterWoW_QuestEN[37669] = { title = "Building for Professions", description = "I see that you have acquired the blueprints for a profession building! Use the Architect Table to build in a small plot.", objectives = "" }
WordHunterWoW_QuestEN[37678] = { title = "Hit the Books", description = "<The librarian speaks in shushed tones.>\n\nOne problem with maintaining such a large arcane library is that the books often pick up an errant enchantment and start darting about on their own. These overmagicked books need to be destroyed before they cause any further damage.\n\nIf you encounter any of these exasperating essays, please put them down. Quietly.", objectives = "" }
WordHunterWoW_QuestEN[37687] = { title = "Garrison Campaign: In the Shadows", description = "I need your help. Iskar has gone missing. I have reason to believe he has followed the remnants of the Sethekk who have been gathering here in Tanaan. I've been investigating and... what was that?\n\n<Reshad's voice drops to a whisper>\n\nThere is movement in the shadows, we are being watched!\n\nTake these vials, they form a gas with a terrible smell when the liquid comes in contact with the air. Smells terrible, they won't be able to resist it. Use them to drive our watchers out of hiding.", objectives = "" }
WordHunterWoW_QuestEN[37688] = { title = "Garrison Campaign: In the Shadows", description = "I need your help. Iskar has gone missing. I have reason to believe he has followed the remnants of the Sethekk who have been gathering here in Tanaan. I've been investigating and... what was that?\n\n<Reshad's voice drops to a whisper>\n\nThere is movement in the shadows, we are being watched!\n\nTake these vials, they form a gas with a terrible smell when the liquid comes in contact with the air. Smells terrible, they won't be able to resist it. Use them to drive our watchers out of hiding.", objectives = "" }
WordHunterWoW_QuestEN[37689] = { title = "The Imposter", description = "Detheroc has SI:7's finest snipers on all of the rooftops. We can't mount up and we can't fly. There are grapple points above so that we can move up the cliff. \n\nWe've also setup hay bales to hide in along the likely routes to SI:7. We just need to stealth in and kill Detheroc.\n\nOnce we get up there, we'll separate to increase the chances of at least one of us making it through the city.\n\nGood luck, {name}.", objectives = "" }
WordHunterWoW_QuestEN[37690] = { title = "Those Who Remember", description = "The ghostly elves, to the south, once had the Pillar of Creation known as the Tidestone of Golganneth.\n\nTheir great city of Nar'thalas was destroyed an eon ago. The city's ruler, Prince Farondis, fell with the city. You small ones die so easily.\n\nIf anyone knows where the fragments rest, it will be the ghost of the prince. Seek out his people.", objectives = "" }
WordHunterWoW_QuestEN[37727] = { title = "The Magister of Mixology", description = "As you must know, I'm a connoisseur of drinks... specifically, arcane-infused spirits. Cocktail mixing is alchemy, and as everyone knows, alchemy is magic.\n\nMy latest drink must be more exotic than anything I've conjured before. I already have most of what I need. But there are a couple of items left on the list.\n\nNotice the herons down in the lagoon? As with many of the creatures on Azsuna, the magic coursing through the island permeates them.\n\nTheir eggs will do nicely.", objectives = "" }
WordHunterWoW_QuestEN[37728] = { title = "Presentation is Everything", description = "The eggs will provide the 'oomph' to my drink's character. But there's another element, and this must not be underestimated!\n\nPresentation.\n\nNow, you could go with your standard olive skewered on a toothpick. Maybe a carrot stalk stuck slapdash out of a glass.\n\nBut then, you wouldn't be me.\n\nNo, my friend. What MY drink needs to sell it visually comes from a one-of-a-kind creature. I'm only going to serve it once and so my drink deserves something unique.\n\nThe eyes of Gangamesh are what I need.", objectives = "" }
WordHunterWoW_QuestEN[37729] = { title = "Pop Quiz: Advanced Rune Drawing", description = "Still aching to get into the headmistress' study, eh? I suppose I can let you in... as long as you prove that you've been studying.\n\nProper rune formation is essential when it comes to spellcasting. If you can draw a rune, you can cast a spell.\n\nI will provide outlines for you. You can simply use your feet to trace the runes.", objectives = "" }
WordHunterWoW_QuestEN[37730] = { title = "The Headmistress' Keys", description = "I have a suspicion you are avoiding your studies - but I can see you're anxious to see the Headmistress.\n\nVery well! Headmistress Azuremoon can be found up ahead, though I doubt she will enjoy being interrupted.", objectives = "" }
WordHunterWoW_QuestEN[37733] = { title = "Prince Farondis", description = "I'm glad to see that my doubts in you were unfounded.\n\nYou seek Prince Farondis? Follow me. I will show you to the prince's hall.", objectives = "" }
WordHunterWoW_QuestEN[37736] = { title = "Dressing With Class", description = "Now stop right there. Look at you! You look like you just walked in off of the street. Where are your robes and hat?\n\nAnd don't tell me you've entered the academy without your wand and spellbook.\n\nFreshmen.\n\nPut yourself together, and maybe then I will consider letting you enter the academy.", objectives = "" }
WordHunterWoW_QuestEN[37750] = { title = "Professions Active", description = "", objectives = "" }
WordHunterWoW_QuestEN[37751] = { title = "Bounties Active", description = "", objectives = "" }
WordHunterWoW_QuestEN[37752] = { title = "Pet Battles Active", description = "", objectives = "" }
WordHunterWoW_QuestEN[37753] = { title = "Relic Hunter Active", description = "", objectives = "" }
WordHunterWoW_QuestEN[37754] = { title = "Dungeon Active", description = "", objectives = "" }
WordHunterWoW_QuestEN[37756] = { title = "Walled City: Brackenspore", description = "The Iron Horde is just one of the threats we must deal with on Draenor. We must also clean up the chaos they are leaving in their wake.\n\nBrackenspore, ancient walker of the deep, was drawn from the waters near Highmaul by the presence of the Iron Horde. He spreads his fungal growth in his wake and will eradicate all of us if left unchecked.\n\nTravel to Highmaul and defeat Brackenspore.", objectives = "" }
WordHunterWoW_QuestEN[37757] = { title = "Arcane Sanctum: Ko'ragh", description = "Forget all you know of the ogres on Azeroth, {name}. On Draenor they commanded a once-mighty civilization. Even now they threaten to reclaim their former glory.\n\nHighmaul excavations in Nagrand unearthed a mysterious relic. The only ogre to survive direct exposure to this relic was Ko'ragh; he was left with a near-complete immunity to all magic.\n\nKo'ragh must be killed before the ogres learn to replicate his unique powers. Travel to Highmaul and defeat Ko'ragh!", objectives = "" }
WordHunterWoW_QuestEN[37758] = { title = "Imperator's Rise: Imperator Mar'gok", description = "The conditions are ripe for a decisive attack against the Highmaul, commander. Will you engage?\n\nDescended from a long line of sorcerers, Imperator Mar'gok is the grand Imperator of Highmaul. He is both cunning and brutal, and allied himself with the Iron Horde when he recognized what it would be to oppose them.\n\nTravel to Highmaul and defeat Imperator Mar'gok. Without their leader, the Ogre Empire will descend into chaos for many years.", objectives = "" }
WordHunterWoW_QuestEN[37762] = { title = "Slagworks: Heart of the Mountain", description = "Blackrock orcs fight like no other clan. They rely on arms and armor forged in the heart of their unnatural crucibles.\n\nDeep within the Foundry of the Blackrock clan is a furnace powered by a primal force known as the Heart of the Mountain. Destroy it, and deprive our foe of the arms they rely on.\n\nTravel to Blackrock Foundry and defeat the Heart of the Mountain.", objectives = "" }
WordHunterWoW_QuestEN[37763] = { title = "The Black Forge: Kromog", description = "Commander. Frostwolf scouts report that blackrock miners dug up a magnaron, and they've coerced the beast into helping them to create their infernal machines. They call it \"Kromog.\"\n\nWe must destroy it, {name}. Travel to Blackrock Foundry and defeat Kromog.", objectives = "" }
WordHunterWoW_QuestEN[37764] = { title = "Iron Assembly: Admiral Gar'an", description = "Our forces are making progress on land, but victory at sea still eludes us. We must take out the Iron Horde leadership while they are in harbor.\n\nGar'an, Admiral of the Iron Horde fleet and first of the so-called Iron Maidens, is tactically brilliant. She, along with her lieutenants, Marak, and Sorka, have crushed all who have been sent to oppose them.\n\nTravel to Blackrock Foundry and defeat Admiral Gar'an.", objectives = "" }
WordHunterWoW_QuestEN[37765] = { title = "Blackhand's Crucible: Blackhand", description = "Grommash Hellscream relied on the strength of his Warlords to keep the Iron Horde under his control. It is time to strike a decisive blow.\n\nBlackhand, Warlord of the Blackrock clan, is a dauntless warrior and ruthless tyrant. He is second only to Grommash within the Iron Horde and oversees operations in the Foundry from atop its Crucible.\n\nTravel to the Blackrock Foundry and defeat Blackhand.", objectives = "" }
WordHunterWoW_QuestEN[37766] = { title = "Walled City: Brackenspore", description = "If it ain't one threat, it's another - I swear this light-forsaken world would try to eat us alive even without no Horde to fight.\n\nBrackenspore, ancient walker of the deep, was drawn from the waters near Highmaul by the presence of the Iron Horde. That thing is already spreading like a disease, {name}. Ye got to put it down!\n\nTravel to Highmaul and defeat Brackenspore before he gets too powerful to stop.", objectives = "" }
WordHunterWoW_QuestEN[37767] = { title = "Arcane Sanctum: Ko'ragh", description = "Ye know the name \"Ko'ragh?\" One of them Highmaul ogres. They dug up a relic some time ago that killed everyone it touched but for Ko'ragh... givin' him a near-complete immunity to all magic.\n\nOgres ain't meant to have that kind of power! Travel to Highmaul and defeat Ko'ragh, before they learn to use him against us.", objectives = "" }
WordHunterWoW_QuestEN[37768] = { title = "Imperator's Rise: Imperator Mar'gok", description = "I never thought much of them ogres, not until I saw a Highmaul legion on the march. Like a wall o' armored muscle, backed by the magics o' the emperor's best sorcerers. Never underestimate an ogre.\n\nImperator Mar'gok is the grand Imperator of Highmaul. Aye, he's a cunning one - allied himself with the Iron Horde, he did. If we're to break up the party, we'd best start at the top.\n\nTravel to Highmaul and defeat Imperator Mar'gok!", objectives = "" }
WordHunterWoW_QuestEN[37769] = { title = "Slagworks: Heart of the Mountain", description = "Blackrock warriors use weapons forged in cursed fire by the breath of a creature o' pure flame: The Heart o' the Mountain. Let's disarm 'em, boy! Destroy that infernal creature, and the Blackrock won't have enough heat to fuel their Blast Furnace.\n\nTravel to Blackrock Foundry and defeat the Heart o' the Mountain.", objectives = "" }
WordHunterWoW_QuestEN[37770] = { title = "The Black Forge: Kromog", description = "Yer garrison scouts report that blackrock miners dug up a magnaron, and that the filthy beast has begun helpin' those brutes churn out their infernal machines. They call it \"Kromog.\"\n\nTravel to Blackrock Foundry and slay that fiend!", objectives = "" }
WordHunterWoW_QuestEN[37771] = { title = "Iron Assembly: Admiral Gar'an", description = "\"If ye want to topple a wall, start with the foundation.\" It's an old Dwarf saying. If we take out the Iron Horde's leadership, the whole thing tumbles.\n\nGar'an is the Admiral o' the Iron Horde fleet and first of the so-called \"Iron Maidens.\" She, along with her lieutenants, Marak, and Sorka, have dominated the seas of Draenor.\n\nNo more, {name}. Travel to Blackrock Foundry and defeat Admiral Gar'an.", objectives = "" }
WordHunterWoW_QuestEN[37772] = { title = "Blackhand's Crucible: Blackhand", description = "Ol' Grommash cannot rule the Iron Horde without his Warlords keeping the clans in line. Let's deal 'em a blow that they can't recover from! Blackhand, Warlord of the Blackrock clan, is a dauntless warrior and ruthless tyrant. He's second only to Grommash within the Iron Horde and oversees operations in the Foundry from atop its Crucible.\n\nTravel to the Blackrock Foundry and defeat Blackhand.", objectives = "" }
WordHunterWoW_QuestEN[37773] = { title = "Death to Amethon!", description = "Foreman Eksos down in your Talador outpost figures he has the answer for why there's been so much seismic activity recently.\n\nSee, there's this giant, ah... earth fury, I think they're called, and it's covered in these powerful crystals in a cave up above Kuuro's Claim. The crystals hum real loud and we think it's driving the fury crazy!\n\nProblem is, nobody's got the firepower to take the thing down so we can examine a sample. Think you could lend us a hand, commander?", objectives = "" }
WordHunterWoW_QuestEN[37774] = { title = "Death to Gor'thul!", description = "Saberon spirit army. I ain't pullin' your leg, commander, that's what we've got coming for us if we don't act fast.\n\nThe Shattered Hand shaman Gor'thul was spotted down in Spires of Arak in the Bloodmane Pridelands right about the same time we started hearing reports of saberon spirits raiding our supply caravans.\n\nI don't want to take any chances, commander. I think you should personally head down there and put a stop to this before it starts.", objectives = "" }
WordHunterWoW_QuestEN[37775] = { title = "Death to Nullifier Darkoor!", description = "You ever heard of the Ring of Blood, commander?\n\nIt's pretty simple. Big ogre named Mogor loves watching people fight for their lives against savage beasts. Ambitious goblin called Gurgthock arranges the fights and rakes in the profits.\n\nAnwyays, Gurgthock and I are long time buddies and he's arranged a special exhibition match just for you! Pretty sweet, right? Just whisper into his ear \"I seek the seeker.\"", objectives = "" }
WordHunterWoW_QuestEN[37776] = { title = "Death to Undertow!", description = "Good day to ya, commander!\n\nI have bad news.\n\nWe've been contracting out some spy work to the local fisherman - we pay 'em some coin, they take their boats out north of Umbrafen and see what the Iron Horde's up to. Win-win, right?\n\nWell, it turns out... no. Every boat that goes out never comes back. Apparently this giant water elemental, Undertow I think it was, is murdering the snot out of everyone that passes through.\n\nAny chance you could clear it out for us, commander?", objectives = "" }
WordHunterWoW_QuestEN[37777] = { title = "Death to Tremor!", description = "Your outpost in Gorgrond has a serious saberon problem, commander, and we can't really afford to keep sending more troops to help 'em out. So I have an idea.\n\nThere's an enormous worm beast on the west coast of Gorgrond called Tremor, better known as the devourer of lobstroks. If you took that thing down and brought the, well, pile of partially digested lobstrok meat back here, we can cook it here, ship it back there, use it to calm the saberon for a good long time!", objectives = "" }
WordHunterWoW_QuestEN[37778] = { title = "Death to Hivelord Ik'rix!", description = "We've got a radical new idea to try using ice ravager carapaces in our tempering process for armor and weapons. It's the sort of trailblazing work we strive for, commander!\n\nOnly problem is, ravagers apparently aren't keen on our guys and gals taking their carapaces off of them. There's this particular ravager at the Southwind Cliffs in Frostfire Ridge called Hivelord Ik'rix - if you could take him down we wouldn't need more for weeks!", objectives = "" }
WordHunterWoW_QuestEN[37780] = { title = "Auchindoun", description = "Commander, Gul'dan's favored agent Teron'gor has infiltrated Auchindoun in Talador and has already taken to devouring the countless souls within. We must not let this nefarious warlock gain any further strength.\n\nEnter the holy mausoleum of Auchindoun and rout Teron'gor and the rest of the Shadow Council before more damage is done.", objectives = "" }
WordHunterWoW_QuestEN[37781] = { title = "Bloodmaul Slag Mines", description = "The Bloodmaul ogres are brutal slavers, commander. Innocents from across Draenor are dragged deep into the volcanic slag mines in Frostfire Ridge to dredge up cart after cart of gems and ore, never to return.\n\nWe suspect that they have turned their focus to unearthing an ancient relic of immense power for their sorcerer-king.\n\nThe ogre Gug'rokk rules over the slag mines with an iron fist. Take him down and the mines will fall as well.", objectives = "" }
WordHunterWoW_QuestEN[37782] = { title = "Grimrail Depot", description = "We must move quickly, commander. As we speak the Grimrail is preparing to depart Grimrail Depot to deliver a massive battalion of troops to Shattrath. Rumor has it that they have outfitted the train with a weapon strong enough to shatter the shield protecting the inner city.\n\nSkylord Tovra has taken to guarding the train on its journey to Talador. You must stop Tovra and the Grimrail before it reaches Shattrath!", objectives = "" }
WordHunterWoW_QuestEN[37783] = { title = "Iron Docks", description = "The Iron Docks is one of the Iron Horde's greatest assets in this war. Our scouts have reported that the docks are alight with activity, indicating imminent attack.\n\nSkulloc, son of Gruul, was seen leaving the Blackrock Foundry, armed to the teeth with powerful cannons, and has been loaded onto their mightiest warship. It does not matter where they intend to strike, commander - you must sack the Iron Docks and defeat Skulloc before they ever leave.", objectives = "" }
WordHunterWoW_QuestEN[37784] = { title = "Shadowmoon Burial Grounds", description = "Ner'zhul was once a noble orc - he was the wise chieftain and elder shaman of the Shadowmoon clan. In his desperate bid to join the Iron Horde he has spat on all he once stood for and twisted his ancestors' spirits to tap into dark, forbidden power... all to please Hellscream.\n\nThe Shadowmoon has fallen, commander. Enter their ancestral burial grounds and put an end to Ner'zhul's madness before he pulls all of Draenor into the engulfing maw of the void.", objectives = "" }
WordHunterWoW_QuestEN[37785] = { title = "Skyreach", description = "High Sage Viryx has finished a devastating crystal superweapon atop the highest point in Skyreach in Spires of Arak. She intends to eradicate the 'lesser races' in the name of their god Rukhmar.\n\nThe arakkoa outcasts were nearly wiped out in mere seconds by the weapon. You must stop Viryx before she turns her sights to your garrison, commander.", objectives = "" }
WordHunterWoW_QuestEN[37786] = { title = "The Everbloom", description = "The Kirin Tor created an outpost in Gorgrond with a portal to Stormwind to facilitate quick reinforcements in the assault on the Blackrock Foundry. In their infinite wisdom they built it in the heart of the Everbloom, home to the botani and the mightiest of the genesaur - Yalnu.\n\nThe outpost has already been overrun and it is only a matter of time before the overgrowth spreads to Stormwind... and with it the whole of Azeroth.", objectives = "" }
WordHunterWoW_QuestEN[37787] = { title = "Upper Blackrock Spire", description = "Hellscream's Ironmarch vanguard managed to reach Blackrock Mountain and has allied with Warlord Zaela of the Dragonmaw clan. Even now the Iron Horde readies to invade Azeroth while Zaela prepares a doomsday weapon in the heart of the mountain to ensure nothing stands in their way.\n\nYou must put a stop to Zaela once and for all, commander. She has been a thorn in our side for too long.", objectives = "" }
WordHunterWoW_QuestEN[37788] = { title = "Treasure Contract: Gutrek's Cleaver", description = "In Nagrand, the ogres tell of an ancient weapon called Gutrek's cleaver. I would very much like to study it.\n\nA goblin treasure hunter by the name of Val Goldspade discovered the whereabouts of the weapon. Unfortunately, this goblin has gone missing somewhere in the Broken Precipice - probably after a run-in with the locals.", objectives = "" }
WordHunterWoW_QuestEN[37789] = { title = "Upper Blackrock Spire", description = "Hellscream's Ironmarch vanguard managed to reach Blackrock Mountain and has allied with Warlord Zaela o' the Dragonmaw clan. Even now the Iron Horde readies to invade Azeroth while Zaela prepares a doomsday weapon in the heart o' the mountain to ensure nothing stands in their way.\n\nYou must put a stop to Zaela once and for all, commander. She's been a thorn in our side for too long.", objectives = "" }
WordHunterWoW_QuestEN[37790] = { title = "The Everbloom", description = "The Kirin Tor created an outpost in Gorgrond with a portal to Stormwind to facilitate quick reinforcements in the assault on the Blackrock Foundry. Unfortunately they built it in the heart o' the Everbloom, home to the botani and the mightiest o' the genesaur - Yalnu.\n\nThe outpost has already been overrun and it is only a matter o' time before the overgrowth spreads to Stormwind... and with it the whole of Azeroth.", objectives = "" }
WordHunterWoW_QuestEN[37791] = { title = "Skyreach", description = "High Sage Viryx has finished a devastatin' crystal superweapon atop the highest point in Skyreach in Spires of Arak. She intends to eradicate the 'lesser races' in the name of their god Rukhmar.\n\nThe arakkoa outcasts were nearly wiped out in mere seconds by the weapon. You must stop Viryx before she turns her sights to your garrison!", objectives = "" }
WordHunterWoW_QuestEN[37792] = { title = "Shadowmoon Burial Grounds", description = "Ner'zhul wasn't always evil - once he was the wise chieftain and elder shaman o' the Shadowmoon clan. In his desperate bid to join the Iron Horde he's forsaken all he once stood for and twisted his ancestors' spirits to tap into dark, forbidden power... all to please Hellscream.\n\nEnter their ancestral burial grounds and put an end to Ner'zhul's madness before he pulls all o' Draenor into the engulfing maw o' the void.", objectives = "" }
WordHunterWoW_QuestEN[37793] = { title = "Iron Docks", description = "The Iron Docks is one o' the Iron Horde's greatest assets in this war. Our scouts have reported that the docks are alight with activity, indicatin' imminent attack.\n\nSkulloc, son o' Gruul, was seen leavin' the Blackrock Foundry, armed to the teeth with powerful cannons, and has been loaded onto their mightiest warship. It doesn't matter where they intend to strike, commander - you must sack the Iron Docks and defeat Skulloc before they ever leave!", objectives = "" }
WordHunterWoW_QuestEN[37794] = { title = "Grimrail Depot", description = "We must move quickly, commander. As we speak the Grimrail is preparing to depart Grimrail Depot to deliver a massive battalion o' troops to Shattrath. Rumor has it that they have outfitted the train with a weapon strong enough to shatter the shield protectin' the inner city.\n\nSkylord Tovra has taken to guardin' the train on its journey to Talador. You must stop Tovra and the Grimrail before it reaches Shattrath!", objectives = "" }
WordHunterWoW_QuestEN[37795] = { title = "Bloodmaul Slag Mines", description = "The Bloodmaul ogres are brutal slavers, commander. Innocents from across Draenor are dragged deep into the volcanic slag mines in Frostfire Ridge to dredge up cart after cart o' gems and ore, never to return.\n\nWe suspect that they have turned their focus to unearthin' an ancient relic o' immense power for their sorcerer-king.\n\nThe ogre Gug'rokk rules over the slag mines with an iron fist. Take him down and the mines will fall as well.", objectives = "" }
WordHunterWoW_QuestEN[37796] = { title = "Auchindoun", description = "Commander, Gul'dan's favored agent Teron'gor has infiltrated Auchindoun in Talador and has already taken to devourin' the countless souls within. We mustn't let this nefarious warlock gain any further strength.\n\nEnter the holy mausoleum o' Auchindoun and rout Teron'gor and the rest o' the Shadow Council before more damage is done.", objectives = "" }
WordHunterWoW_QuestEN[37797] = { title = "Gutrek's Cleaver: The First Piece", description = "The journal points to the location of the pieces of Gutrek's Cleaver. It reads:\n\n\"The pommel was brought to the Broken Precipice, where it was to be housed in the skull of Gutrek's first kill. It looks like it was some manner of large beast that he fought in the big bone pit.\"", objectives = "" }
WordHunterWoW_QuestEN[37798] = { title = "Gutrek's Cleaver: The Second Piece", description = "The search for Gutrek's Cleaver continues. The journal reads:\n\n\"The hilt was to be buried in the marshlands, among the serpents whose poison claimed Gutrek's life. There's something here about covering it with a spiral stone, which is supposed to keep Gutrek's spirit at bay somehow.\"", objectives = "" }
WordHunterWoW_QuestEN[37799] = { title = "Gutrek's Cleaver: The Final Piece", description = "Only one piece remains. The journal reads:\n\n\"The final piece, Gutrek's blade, was to be displayed in a place of honor for all time overlooking the Ring of Blood. I don't think I've seen it there myself, but it says it's supposed to be somewhere where it has a clear view of every battle.\"", objectives = "" }
WordHunterWoW_QuestEN[37801] = { title = "Garrison Campaign: The Siege Council", description = "We've stockpiled enough supplies and our forces are finally in position to assault the Iron Horde stronghold in Tanaan.\n\nThis will be a dangerous operation that will require your personal attention, commander. Khadgar has gathered together the draenei leadership to plan a coordinated assault. Please use the map here in the town hall to plan our attack!", objectives = "" }
WordHunterWoW_QuestEN[37806] = { title = "Garrison Campaign: The Siege Council", description = "We've stockpiled enough supplies and our forces are finally in position to assault the Iron Horde stronghold in Tanaan.\n\nThis will be a dangerous operation that will require your personal attention, commander. Khadgar has gathered together the Frostwolves to plan a coordinated assault. Please use the map here in the war room to plan our attack!", objectives = "" }
WordHunterWoW_QuestEN[37807] = { title = "Return to the Iron Docks", description = "Once my guys finish looting the place, it'll be a snap to build the boats! I, uh, assumed you killed ALL the Iron Horde guys there. You did right?\n\nHey, maybe you should go visit the boys just in case they ran into trouble, eh? I got ride right here.", objectives = "" }
WordHunterWoW_QuestEN[37808] = { title = "Clearing the Docks", description = "I didn't bring enough muscle to handle these guys. If you could take a bunch of 'em out that would let me establish a hold here and get to work on those boats.", objectives = "" }
WordHunterWoW_QuestEN[37809] = { title = "Useful Equipment", description = "While you are out there cleaning hou... er docks, you will probably run into some bigger supply caches. My guys are pretty observant but a little help scouting never hurts!\n\nIf you can mark these caches I will send a recovery specialist out ASAP to begin the collection!", objectives = "" }
WordHunterWoW_QuestEN[37810] = { title = "Captain Grathor", description = "You know what would really help? Taking out the leadership!\n\nThere's an orc further down the docks running this whole operation. Killing that captain will put a serious damper on their operations around here.", objectives = "" }
WordHunterWoW_QuestEN[37811] = { title = "Gutrek's Cleaver: The Spirit Forge", description = "With the pieces recovered, all that is left is to reforge Gutrek's Cleaver. Goldspade's journal seems to indicate that the only place to do this is the location where it was initially dismantled.\n\nThe journal mentions a \"Spirit Forge\" used to dismantle the blade, and that it may be located somewhere in the nearby gorge. Find the forge and use it to combine the pieces you've gathered.", objectives = "" }
WordHunterWoW_QuestEN[37813] = { title = "Death to Amethon!", description = "Foreman Grobash in da Talador outpost figures he knows why der's been so much seismic activity recently.\n\nDer be an earth fury called Amethon that be covered in powerful crystals in a cave up above Kuuro's Claim. Da crystals' hummin' be drivin' da fury crazy!\n\nWe want a sample to see if we can figure out why da crystals are so powerful. I wouldn't be askin' ya if I thought anybody else could do it, commander.", objectives = "" }
WordHunterWoW_QuestEN[37814] = { title = "Death to Gor'thul!", description = "We been hearin' 'bout some real, real bad voodoo in Spires of Arak, commander.\n\nDa Shattered Hand shaman Gor'thul be seen sneakin' about da spires the same time we be hearin' of saberon spirits attackin' our supply caravans and our arakkoa allies.\n\nI think it best if we take no chances. You should deal with da shaman personally before dis matter gets out of hand.", objectives = "" }
WordHunterWoW_QuestEN[37815] = { title = "Death to Nullifier Darkoor!", description = "Da goblin Gurgthock be requestin' your presence at the Ring of Blood in Nagrand, boss-mon.\n\nIt seems that Mogor, da lord of da ring, be holdin' an exhibition match der and he want you to fight his newest acquisition.\n\nI think it be safe, commander. I heard of dis goblin's work before. If you be ready, whisper to him \"I seek da seeker.\"", objectives = "" }
WordHunterWoW_QuestEN[37816] = { title = "Death to Undertow!", description = "We be havin' a problem, commander.\n\nWe been sendin' some small boats into the Tanaan Channel north of da Umbrafen in Shadowmoon ta spy on da Alliance base der as well as da Iron Horde in Tanaan Jungle.\n\nDa problem is dat every boat we send out come back in pieces, if it come back at all. We think a water elemental called Undertow is da culprit.\n\nI know you be busy, but destroyin' that creature would be very helpful to our efforts.", objectives = "" }
WordHunterWoW_QuestEN[37817] = { title = "Death to Tremor!", description = "Da Gorgrond outpost be havin' troubles with saberon, and we can't afford ta throw troops at the problem any longer. Don't worry, I be havin' an idea.\n\nThere be an enormous worm beast on the west coast of Gorgrond called Tremor, da devourer of lobstroks. If you killed da beast and brought da pile of lobstrok meat back here, we can cook it 'ere, send it to da outpost, and use it to calm da saberon for good!", objectives = "" }
WordHunterWoW_QuestEN[37818] = { title = "Death to Hivelord Ik'rix!", description = "We been tryin' out a new way to temper weapons with ice ravager carapaces. Der icy hides are perfect for da process.\n\nHivelord Ik'rix in da Southwind Cliffs nearby is rumored to be da largest ravager we ever seen - if you could bring its carapace back, we'd be able to make all sorts of things!", objectives = "" }
WordHunterWoW_QuestEN[37819] = { title = "Welcome to the Darkmoon Races", description = "So this is your first race, eh? Don't worry - it's easier than it looks. Let me break it down for you...\n\nRun through that big  banner there. That starts everything. Then, follow the smaller banners until you see a big, blue Post. Hit that, then return here.\n\nYou're scored on your time, so finish as fast as you can! And watch out for those electrified tripwires. They'll slow you down if you run through them. Good luck!", objectives = "" }
WordHunterWoW_QuestEN[37834] = { title = "Orb of Dominion", description = "Gul'dan and his Shadow Council have their hooks embedded deep into Garona's soul. We've tried traditional magical methods and they haven't helped her. It's time to get unorthodox.\n\n<Khadgar cracks his knuckles, his eyes flashing with a disturbing eagerness.>\n\nI've just learned of a Shadow Council holdout hidden beneath the Draenei city of Elodor. They are using an Orb of Dominion to brainwash spies. Quickly! Assault the cave and recover the orb for me. We will turn this dark magic to our advantage.", objectives = "" }
WordHunterWoW_QuestEN[37835] = { title = "The Shadow War", description = "The Shadow Council are more entrenched than you expected. A large contingent seems focused on infiltrating the draenei Exarch Council in the town above.\n\nKhadgar certainly wouldn't complain if you did a little... \"housecleaning.\"", objectives = "" }
WordHunterWoW_QuestEN[37836] = { title = "Breaking Badness", description = "It is time to liberate Garona. I know what to do... I think. I'd like you to stay close in case anything goes wrong.\n\nSpeak with me when you are ready to begin.", objectives = "" }
WordHunterWoW_QuestEN[37837] = { title = "An Inside Job", description = "If Garona's intelligence is correct, Gul'dan will be inside this Iron Horde compound. With Garona's help, slip inside, gather any info you find, and learn what Gul'dan intends to do.\n\nThe guards are on high alert. Garona can \"liquidate\" individual guards for you, but she must not be seen! You will have to choose your targets carefully and pick your way through the bastion undetected. Don't let anyone sound the alarm.\n\nIf things get too hot, I'll teleport you to safety. At least... I'll try.", objectives = "" }
WordHunterWoW_QuestEN[37838] = { title = "My Garona", description = "", objectives = "" }
WordHunterWoW_QuestEN[37839] = { title = "Light Be With You", description = "You've done everything I've asked, {name}. I believe we can apply one final enchantment to your ring. But... we must be cautious. Last time I augmented your ring I killed you. (Sorry.) It will take a divine act to empower you further.\n\nFortunately, you've made some powerful allies during your time here. Travel to the Temple of Karabor, where Yrel is waiting for you. With the blessing of a Naaru your ring will become as powerful and unique as - well, as you yourself. Go to Karabor. You've earned it.", objectives = "" }
WordHunterWoW_QuestEN[37840] = { title = "Draenor's Blessing", description = "You've done everything I've asked, {name}. I believe we can apply one final enchantment to your ring. But... we must be cautious. Last time I augmented your ring I killed you. (Sorry.) It will take an act of ancient magic to empower you further.\n\nFortunately, you've made some powerful allies during your time here. Seek out Farseer Drek'Thar at the Throne of Elements in Nagrand. There you can receive the blessing of the elements and safely unlock your ring's final form. Go, hero! Claim your reward!", objectives = "" }
WordHunterWoW_QuestEN[37841] = { title = "The Final Assault", description = "Our campaign in Draenor has taken an unexpected turn. With Gul'dan assuming power over the Iron Horde, history is poised to repeat itself - our world is in more peril than ever.\n\nIt's time to bring the full might of your garrison to bear against Tanaan Jungle. Build a shipyard for your garrison! I will meet you at your new shipyard and we will discuss our next move from there.", objectives = "" }
WordHunterWoW_QuestEN[37847] = { title = "Arcanock", description = "I know who we need to find.\n\nArcanock!\n\nHe was entombed eons ago by Senegos. But now with the old one growing weak, this creature has somehow freed itself of its bonds.\n\nHis magic is what is preventing any dragons from entering the wood.\n\nMortal, look for a cave to lead you into the main tributaries of the ley line. Enter the Deep Nexus and slay Arcanock!", objectives = "" }
WordHunterWoW_QuestEN[37848] = { title = "Treasure Contract: Amulet of Rukhmar", description = "It seems the Adherents of Rukhmar have stumbled upon some information leading to an ancient amulet, said to possess the power of their god and bestow it upon the wearer. We should make sure they don't find it.\n\nHead to Skettis and find what they have learned. Hopefully we can find it before they get to it.", objectives = "" }
WordHunterWoW_QuestEN[37849] = { title = "Amulet of Rukhmar: The First Key", description = "The Arakkoa research points to three \"keys\" that need to be activated in order to use the Apexis device. The first is located in Skettis. The text mentioning it reads:\n\n\"The first key is kept in the high reaches of upper Skettis. It lay where the dead can protect it from the talons of the unwanted.\"", objectives = "" }
WordHunterWoW_QuestEN[37850] = { title = "Amulet of Rukhmar: The Second Key", description = "The first point has been activated and two more remain. The second location is hinted at in the old outcast writing:\n\n\"Beneath the third fall of the great Skettis river lay the second key. May the ever-rushing waters sweep away those that might seek it.\"", objectives = "" }
WordHunterWoW_QuestEN[37851] = { title = "Amulet of Rukhmar: The Final Key", description = "One last key is required to access the Apexis device. The writings pertaining to its location read:\n\n\"The final key has been housed deep within the fungal caves where the river makes its final drop. Though the pale orcs that dwell there may be vile, they should prove a worthy deterrent.\"", objectives = "" }
WordHunterWoW_QuestEN[37852] = { title = "Amulet of Rukhmar: The Apexis Device", description = "Now that the keys have been activated, the Apexis device that leads to the amulet should be accessible. \n\nThe Arakkoa research states that it is likely located in Lost Veil Anzu, within the \"shrine to the raven god.\"", objectives = "" }
WordHunterWoW_QuestEN[37853] = { title = "The Death of the Eldest", description = "I will do what I can to stabilize him, but I will need your help.\n\nThe small amount of energy he has left is coming from the mana pool he rests in.\n\nFollow the whelplings' lead. Dropping ley crystals into the pool gives him a bit of energy - buying him a few more breaths.\n\nThey seem to be getting the crystals from inside that cave to the north.", objectives = "" }
WordHunterWoW_QuestEN[37855] = { title = "The Last of the Last", description = "We need help.\n\nSince the fall of Deathwing, we dragons have lost nearly all of our power. To make matters worse, we can no longer bear eggs.\n\nMy whelplings are the last of the last.\n\nI need you, champion. Help defend my whelplands, and I swear to you, the blues will be at your side when you need them.", objectives = "" }
WordHunterWoW_QuestEN[37856] = { title = "The Withered", description = "The withered are the worst kind of pest. They capture our whelplings, knock them unconscious, and then drink whatever mana they can from the helpless babes.\n\nNormally our drakes and keepers would fend them off. Today, it looks like we may need your help.", objectives = "" }
WordHunterWoW_QuestEN[37857] = { title = "Runas Knows the Way", description = "I wish to make it up to you for whatever I did that made you want to kill me.\n\nHmm... your dragon complains about being weak. I know why. Runas can fix it, my friend.\n\nOne of my kind, Ael'Yith, pulls ley energy from the very ground of Azsuna. I can take you to the location of his mana siphons.\n\nIt's not too late to undo the harm the others have done. You've done well to trust me.", objectives = "" }
WordHunterWoW_QuestEN[37858] = { title = "Stellagosa", description = "Something is wrong, {name}.\n\nI sent Stellagosa to assist you, but I can no longer sense her.\n\nPlease, go out there and find out what's happened to my granddaughter.", objectives = "" }
WordHunterWoW_QuestEN[37859] = { title = "The Consumed", description = "<The whelpling is alive, but unconscious. One of the withered must have already drained it of mana.>\n\n<You've already learned that exposed ley crystals contain a small amount of magical energy. Perhaps you can use one to revive some of the whelps.>", objectives = "" }
WordHunterWoW_QuestEN[37860] = { title = "You Scratch My Back...", description = "Much better. I knew I could count on you, my friend. Allow me to return the favor.\n\nI know how you can destroy the large mana collector pylons. We shall save your dragon yet!\n\nThe pylons only work against ground targets, yet they're defenseless from above. Send your whelplings at them, my friend. The whelplings can fly where we cannot.\n\nTrust me.", objectives = "" }
WordHunterWoW_QuestEN[37861] = { title = "The Nightborne Prince", description = "<Senegos is focused.>\n\nI sense it now. In the ruined building, to the east. One of these cretins must have tapped deep into the ley line.\n\nI suspect he will be heavily defended, {name}. Once again, the well-being of my brood is in your hands.", objectives = "" }
WordHunterWoW_QuestEN[37862] = { title = "Still Alive", description = "Wait, what was it that I heard? Was it... \"feast on the dragons\"? We must check on grandfather, right away!\n\nLet me know when you're ready to depart.", objectives = "" }
WordHunterWoW_QuestEN[37863] = { title = "Boats Building", description = "I think we got it from here boss! You can head back to Gazlowe and tell him we are building boats!", objectives = "" }
WordHunterWoW_QuestEN[37881] = { title = "Treasure Contract: Explosive Discoveries", description = "In Shadowmoon Valley there is a cave said to possess an ancient tome that may contain secrets that can help our cause against the Iron Horde. The cave, however, is protected by an ancient barrier composed of arcane energy.\n\nThere is a goblin in Darktide Roost, said to know how to take down any barrier. Persuade him to give up his secrets and bring back the book.", objectives = "" }
WordHunterWoW_QuestEN[37882] = { title = "Dark Grimoire: The First Ingredient", description = "You will need three ingredients to make Megacharge's special \"Arcane Bunker Buster,\" which should be able to take down the barrier. The first ingredient, some precision blasting powder, should be available nearby. The book reads:\n\n\"To make one, you'll first need to acquire some high grade, precision blasting powder. Here in Blackfuse Company, it's pretty easy to come by, since they use it for all of the cannons.\"", objectives = "" }
WordHunterWoW_QuestEN[37883] = { title = "Dark Grimoire: The Second Ingredient", description = "With the blasting powder acquired, you now must find a suitable detonator. A note attached to the entry in the cookbook hints to where one might be found:\n\n\"Reminder: Order more high-voltage detonators. The last shipment was lost off of the Shadowmoon coast near the demon-inhabited cliffs. Maybe we should send a diving team to salvage.\"", objectives = "" }
WordHunterWoW_QuestEN[37884] = { title = "Dark Grimoire: The Final Ingredient", description = "The final ingredient to create Megacharge's bomb is a sizable quantity of demon's blood. \n\nUnfortunately, that's not something they're likely to give up easily...", objectives = "" }
WordHunterWoW_QuestEN[37885] = { title = "Dark Grimoire: Breaching the Barrier", description = "The components have been gathered and the \"Arcane Bunker Buster\" is assembled. Hopefully, this should pack enough punch to take out the barrier.\n\nThere's only one way to find out...", objectives = "" }
WordHunterWoW_QuestEN[37889] = { title = "The Invasion of Tanaan", description = "It is done! By your command we have built our first ship and can run our naval operations from here.\n\nNow that we have our transport, we can let Durotan and that Archmage of yours know that we are ready to kick off an invasion of Tanaan. Speak with them at the docks to embark.", objectives = "" }
WordHunterWoW_QuestEN[37890] = { title = "Obstacle Course", description = "It is strange that these docks were abandoned by the Iron Horde, but up ahead our scouts report trouble.\n\nA set of Bleeding Hollow scavengers is busy looting the abandoned buildings to the northwest.\n\nFurther down the road orc cultists are doing... something... near the Dark Portal.\n\nWe should try to recover any orders or information as to what is going on here, then meet with our scouts further in...", objectives = "" }
WordHunterWoW_QuestEN[37891] = { title = "Assault on Ironhold Harbor", description = "The Iron Horde continue to bring in reinforcements from all over Draenor to reinforce their position at Hellfire Citadel. If we don't cut off the flow of supplies then we risk losing control of our plans in Tanaan.\n\nA strategic attack to the supply lines at Ironhold Harbor is just the thing to keep the Iron Horde on the defensive and maintain our momentum.", objectives = "" }
WordHunterWoW_QuestEN[37910] = { title = "The Real Race", description = "Ok, Darkmoon Racer, let's see what you got!\n\nThe real race has four legs: get to the blue post, then green, then red, then back here. \n\nYour time matters, so do it fast!", objectives = "" }
WordHunterWoW_QuestEN[37911] = { title = "The Real Big Race", description = "Here's the big one! Good luck out there!\n\nThis race has four legs: get to the purple post, then green, then red, then back here. \n\nYour time matters, so do it fast!", objectives = "" }
WordHunterWoW_QuestEN[37914] = { title = "Treasure Contract: The Thunderlord Sage", description = "In Frostfire Ridge, a Thunderlord sage by the name of Argoram seems to have uncovered the whereabouts of a storied weapon, known to the orcs as Gronnsbane. \n\nHe was last spotted headed into Magnarok. Find him and see if he can lead you to this relic.", objectives = "" }
WordHunterWoW_QuestEN[37916] = { title = "Gronnsbane: The Broken Spear", description = "Looking through Argoram's journal, it becomes apparent that claiming this relic will be far more complicated than simply finding the pieces of the spear.\n\nHowever, that would be the best place to start...", objectives = "" }
WordHunterWoW_QuestEN[37917] = { title = "Gronnsbane: The Blessing of Fire", description = "The weapon has been assembled, but it lacks the power that made it a legend. In order to restore it, you must receive three blessings: one of fire, one of frost, and one of beasts.\n\nThe first blessing mentioned in the journal is that of fire. The journal reads:\n\n\"He describes an ancient monolith, perched upon the edge of a precipice extending from the cliff where the searing magma falls into the sea.  I believe the location he speaks of is just overlooking Tor'goroth's Tooth.\"", objectives = "" }
WordHunterWoW_QuestEN[37918] = { title = "Gronnsbane: The Blessing of Frost", description = "The weapon has been imbued with the Blessing of Fire, drawing power from the Molten Shamanstone. The Frozen Shamanstone should impart the next blessing. Argoram mentions its location in his journal:\n\n\"As I was maneuvering away from the great boulders hurled at me by the ogron brutes, I glanced what looked like another monolith atop the tallest of the snow-capped towers in Bloodmaul. Perhaps this is the Frozen Shamanstone, which is thought to grant the Blessing of Frost\"", objectives = "" }
WordHunterWoW_QuestEN[37919] = { title = "Gronnsbane: The Blessing of Beasts", description = "Gronnsbane now pulses with energies of fire and frost. All that remains to restore the full power of the weapon is to receive the Blessing of the Beast. Argoram believed this could be accomplished by bloodying the weapon against one of the ancient black rylaks of Stonefury Cliffs. His journal reads:\n\n\"High in the Stonefury Cliffs, I have seen an altar where the ogres have left offerings to these ancient beasts. Perhaps I could use it to lure one of them\"", objectives = "" }
WordHunterWoW_QuestEN[37920] = { title = "Return to the Iron Docks", description = "Oh the things I could build on those docks. The draenei have offered their support as we reclaim some war materials.\n\nOf course, you did clear out all the Iron Horde from there, commander? Maybe we should go see how the effort is going, eh?", objectives = "" }
WordHunterWoW_QuestEN[37924] = { title = "Maritime Salvage", description = "It would go a bit faster if you could mark any bigger piles of resources you see while you are clearing those guys out.\n\nJust drop this flag down and someone will be along directly!", objectives = "" }
WordHunterWoW_QuestEN[37925] = { title = "Foreman Bruntza", description = "Okay, scouts say that there's a big orc named Bruntza out there directly efforts.\n\nKilling her would go a long way to sending the Iron Horde back home.", objectives = "" }
WordHunterWoW_QuestEN[37926] = { title = "Boats Building", description = "That should do it. We'll have transport built in no time. Why don't you go fill in people back at the garrison?", objectives = "" }
WordHunterWoW_QuestEN[37934] = { title = "In, Through, and Beyond!", description = "A few of us snuck through before we was spotted, den de cannons started up. De small ones are no trouble, but de big one... we gonna need to take it out if we wanna get anyting through.", objectives = "" }
WordHunterWoW_QuestEN[37935] = { title = "The Assault Base", description = "Nearby be a good place. Not too close to da enemy, but close enough for us to take some pressure off da boys in the west. Follow me.", objectives = "" }
WordHunterWoW_QuestEN[37940] = { title = "Assault on Ironhold Harbor", description = "The Iron Horde continues to bring in reinforcements from all over Draenor to reinforce their position at Hellfire Citadel. If we don't cut off the flow of supplies then we risk losing control of our plans in Tanaan.\n\nA strategic attack to the supply lines at Ironhold Harbor is just the thing to keep the Iron Horde on the defensive and maintain our momentum.", objectives = "" }
WordHunterWoW_QuestEN[37941] = { title = "Treasure Contract: The Infected Orc", description = "In Gorgrond, the Laughing Skull clan has a legend of one called Skulltaker. His mask, known only as the Silent Skull, is legendary among the clan, and could help us learn more about them.\n\nUntil recently, he was thought to have vanished. Now it appears he has shown his face, so to speak, in Everbloom Wilds. The last orc to have seen him fell to the botani there, but may still have some clues on how you can find Skulltaker and recover the mask.\n\nIf the botani have him, he may not be cooperative.", objectives = "" }
WordHunterWoW_QuestEN[37942] = { title = "The Silent Skull: The First Reagent", description = "Grinning Tolg was in the process of brewing an elixir that would allow him to communicate with the ravagers, whom the Skulltaker relies on to remain hidden.\n\nThe first ingredient, the leaves of the Shadethistle plant, can be found nearby. The journal reads:\n\n\"It rests in the shadows of the harsh Gorgrond sun. I saw some under standing stones near the black iron walls.\"", objectives = "" }
WordHunterWoW_QuestEN[37943] = { title = "The Silent Skull: The Second Reagent", description = "The second ingredient to the elixir is a vine from the Bonethorn plant. The journal reads:\n\n\"I must find a vine of bonethorn, which grows in the bones of the ancient dead. I remember seeing the bones of a long-dead beast in the dry beds of the northern wilds. Its sun-parched skull would make a pleasant home for such a plant.\"", objectives = "" }
WordHunterWoW_QuestEN[37944] = { title = "The Silent Skull: The Third Reagent", description = "The final component of the elixir is a handful of Steamcap mushrooms. The journal reads:\n\n\"The Crowfeeder said that they grow among the steam vents in the higher parts of the Everbloom. I have seen one such place above the northern hydra pools.\"", objectives = "" }
WordHunterWoW_QuestEN[37945] = { title = "The Silent Skull: Taking from the Taker", description = "With the reagents found, you should seek out Grinning Tolg's camp in the nearby cave to brew the elixir. \n\nOnce the elixir is consumed, you should be able to communicate with the ravagers there. With any luck, they should be able to bring you to Skulltaker.\n\nHis mask should bring a hefty reward.", objectives = "" }
WordHunterWoW_QuestEN[37948] = { title = "Death to Nullifier Darkoor!", description = "Gurgthock stopped by from the Ring of Blood and said that Mogor wants his Blood Champion to participate in a special exhibition match. That's you, commander!\n\nJust whisper \"I seek the seeker.\" into Gurgthock's ear and he'll get things going for ya!", objectives = "" }
WordHunterWoW_QuestEN[37949] = { title = "Death to Nullifier Darkoor!", description = "Da goblin Gurgthock stopped by and be sayin' that Mogor wants his Blood Champion to fight in an exhibition match against something terrible he's dug up. Dat be you, boss.\n\nIf you be ready, whisper to Gurgthock \"I seek da seeker.\" He take care of da rest.", objectives = "" }
WordHunterWoW_QuestEN[37957] = { title = "Runas the Shamed", description = "I fell so quickly, {name}. I am not as strong as I once was. We truly do need your help.\n\nOne of these disgusting creatures ran off with several of the whelplings. I heard him called by name:\n\nRunas.\n\nI will survive. Home is not far. You still have strength, though. Slay this Runas before he does any more damage to our brood.", objectives = "" }
WordHunterWoW_QuestEN[37959] = { title = "The Hunger Returns", description = "<Runas looks antsy.>\n\nI can help you, and I very much want to help you, but I'm a bit distracted. Look at all that raw, unfiltered, mouthwatering mana...\n\n<Runas slaps his own face.>\n\nNo! NO! You must stay in control!\n\nI simply need to clear my head. Yes, that's it. A few of my depraved brethren carry small mana jewels around with them in case they need a quick burst of energy. Find a few for me? Then I will show you how to get your ley line back.", objectives = "" }
WordHunterWoW_QuestEN[37960] = { title = "Leyline Abuse", description = "These monsters are pulling mana directly out of the ground. This explains why not even my mana pools can dull my pain.\n\nI worry about my brood. Without the power of the ley lines, we are nothing. At this rate, I may not even be able to help you with your Tidestone.\n\nLook for their mana siphons, and punish the cowardly nightfallen elves that are using them.", objectives = "" }
WordHunterWoW_QuestEN[37961] = { title = "Bringing the Bass", description = "You know what would boost morale around here?\n\nBass. Beats. Music!\n\nEveryone loves a party! You go out and get me some hardware, and I'll make a system that will shatter Draenor itself.", objectives = "" }
WordHunterWoW_QuestEN[37964] = { title = "To Gul'dan!", description = "We must act quickly - Garona here tells me that Gul'dan is on the move. He is headed to the Path of Glory to meet with Grommash Hellscream.\n\nWe have to act while our intelligence is fresh! Hurry and meet us outside of Bladefury's Command in northern Talador. We won't be able to engage Gul'dan and the whole Iron Horde army on our own, but we may just learn something to use against them...", objectives = "" }
WordHunterWoW_QuestEN[37968] = { title = "Assault on the Temple of Sha'naar", description = "Up in the hills of Tanaan Jungle, the Sargerei have converted a once-sacred temple into a den of demonic summoning.\n\nWe must attack them now, before their rituals complete. The longer we delay, the stronger our enemy grows.", objectives = "" }
WordHunterWoW_QuestEN[37972] = { title = "Pet Battles Not Active", description = "", objectives = "" }
WordHunterWoW_QuestEN[37973] = { title = "Treasure Contract: The Artificer", description = "I have heard of a draenei artificer by the name of Maatun that was seeking to restore an old draenei crystal, possibly of naaru origin. He called the crystal the Dream of Argus. \n\nThe draenei went missing after seeking out help from the Shadowmoon orcs back before they allied themselves with the Iron Horde. One of your scouts recently spotted a draenei matching the description of Maatun near the entrance of the Pillars of Fate. Go there and see what you can dig up.", objectives = "" }
WordHunterWoW_QuestEN[37974] = { title = "Pet Battles Not Active", description = "", objectives = "" }
WordHunterWoW_QuestEN[37975] = { title = "Pet Battles Not Active", description = "", objectives = "" }
WordHunterWoW_QuestEN[37976] = { title = "Dream of Argus: The First Fragment", description = "In his quest to restore the Dream of Argus, Maatun enlisted the help of three orcs. These same orcs betrayed him and took the crystal shards before they could be combined. If you find these orcs, they may still have them.\n\nThe first target shouldn't be far. The journal reads:\n\n\"I was told she spent most of her time in the crystal cave to the north of the encampment. There she studied the native crystals for ways to improve their potential abilities.\"", objectives = "" }
WordHunterWoW_QuestEN[37977] = { title = "Dream of Argus: The Second Fragment", description = "The second orc that Matuun mentioned was a master runecarver and sorcerer. He should be located somewhere in the main camp. The journal reads:\n\n\"She mentioned that the orc could normally found in one of the runemaster's huts in the southern part of the camp. They could be identified by the standing stones surrounding the structure, as well as the floating runestones above.\"", objectives = "" }
WordHunterWoW_QuestEN[37978] = { title = "Dream of Argus: The Final Fragment", description = "The last orc to be found was a hermit who kept away from the bulk of the Shadowmoon orcs at the Pillars of Fate camp, but was often seen in the high hills above. The journal reads:\n\n\"It is said, however, that he can often be seen among the graves upon the high hill, overlooking the camp below.  There he would commune with the dead ancestors, whom it is said he preferred over his living brethren.\"", objectives = "" }
WordHunterWoW_QuestEN[37979] = { title = "Dream of Argus: The Crystal Reborn", description = "With the shards recovered, it is now possible to restore the Dream of Argus. You must seek out the device that Maatun mentions in his journal, which is said to be in a cave overlooking Anguish Fortress.", objectives = "" }
WordHunterWoW_QuestEN[37981] = { title = "The World Famous Ring of Blood!", description = "Dear Unadulterated Badass,\n\nIf you're reading this, you're exactly the sort of tough-as-nails champ in the making we need down at the Ring of Blood in Nagrand.\n\nYou and two friends are cordially invited to fight for your lives against the toughest creatures this side of Gorgrond. It's positively brutal - and the crowd loves it!\n\nCome talk to me to start your first fight - beat four of the fiercest creatures I've got and you'll get a shot at the champ himself!\n\n-Gurgthock", objectives = "" }
WordHunterWoW_QuestEN[37991] = { title = "Agapanthus", description = "<This whelpling is trying to get your attention. She locks eyes with you, then quickly flicks her head toward the northeast.>", objectives = "" }
WordHunterWoW_QuestEN[37992] = { title = "Gutrek's Cleaver: The Spirit Forge", description = "With the pieces recovered, all that is left is to reforge Gutrek's Cleaver. Goldspade's journal seems to indicate that the only place to do this is the location where it was initially dismantled.\n\nThe journal mentions a \"Spirit Forge\" used to dismantle the blade, and that it may be located somewhere in the nearby gorge. Find the forge and use it to combine the pieces you've gathered.", objectives = "" }
WordHunterWoW_QuestEN[37993] = { title = "Amulet of Rukhmar: The Apexis Device", description = "Now that the keys have been activated, the Apexis device that leads to the amulet should be accessible. \n\nThe Arakkoa research states that it is likely located in Lost Veil Anzu, within the \"shrine to the raven god.\"", objectives = "" }
WordHunterWoW_QuestEN[37994] = { title = "Dark Grimoire: Breaching the Barrier", description = "The components have been gathered and the \"Arcane Bunker Buster\" is assembled. Hopefully, this should pack enough punch to take out the barrier.\n\nThere's only one way to find out...", objectives = "" }
WordHunterWoW_QuestEN[37995] = { title = "Gronnsbane: The Blessing of Beasts", description = "Gronnsbane now pulses with energies of fire and frost. All that remains to restore the full power of the weapon is to receive the Blessing of the Beast. Argoram believed this could be accomplished by bloodying the weapon against one of the ancient black rylaks of Stonefury Cliffs. His journal reads:\n\n\"High in the Stonefury Cliffs, I have seen an altar where the ogres have left offerings to these ancient beasts. Perhaps I could use it to lure one of them\"", objectives = "" }
WordHunterWoW_QuestEN[37996] = { title = "The Silent Skull: Taking from the Taker", description = "With the reagents found, you should seek out Grinning Tolg's camp in the nearby cave to brew the elixir. \n\nOnce the elixir is consumed, you should be able to communicate with the ravagers there. With any luck, they should be able to bring you to Skulltaker.\n\nHis mask should bring a hefty reward.", objectives = "" }
WordHunterWoW_QuestEN[37997] = { title = "Dream of Argus: The Crystal Reborn", description = "With the shards recovered, it is now possible to restore the Dream of Argus. You must seek out the device that Maatun mentions in his journal, which is said to be in a cave overlooking Anguish Fortress.", objectives = "" }
WordHunterWoW_QuestEN[38001] = { title = "Commander in the Field!", description = "We have been stopped by these new fel orcs, but we will ultimately prevail. Draka and I did manage to get a full scouting group out into the jungle to gather what else we will have to deal with.\n\nYou should seek them out, gain a full understanding of what we face here.", objectives = "" }
WordHunterWoW_QuestEN[38014] = { title = "Feasting on the Dragon", description = "You killed their leader, so they came here? Understandable. These creatures crave only one thing - magic - and they can sniff it out from leagues away.\n\nWithout a leader, they will soon wither and die. Our only recourse in the meantime is to put as many as possible down before they take these dragons with them!", objectives = "" }
WordHunterWoW_QuestEN[38015] = { title = "On the Brink", description = "This many withered threaten to wipe our brood out completely!\n\nQuickly, {name}! Crack off a ley crystal and heal any wounded drakes you can find out on the battlefield.\n\nI will do what I can to keep these whelplings safe and healthy.", objectives = "" }
WordHunterWoW_QuestEN[38017] = { title = "Razing Your Rivals", description = "Who are you but another grain of sand on an endless beach of challengers?\n\nAlthough my body may be gone, my watch over this vault has not yet ended.\n\nDare you enter before proving your might to me?", objectives = "" }
WordHunterWoW_QuestEN[38019] = { title = "Yotnar's Eye", description = "Who is it that stands before me?\n\nSkovald destroyed my body. Soon after a bird stole my right eye, a shiny treasure for its nests... Who am I without my eyes? How can I judge those that wish to pass without my sight? I grow weary...\n\nPerhaps you could use some stones to knock those nests out of the trees? Find my eye and we can discuss the trials in further detail.\n\n<You pick up handful of stones next to Yotnar's head.>", objectives = "" }
WordHunterWoW_QuestEN[38035] = { title = "A Royal Summons", description = "Well met, {name}. I have come on behalf of King Anduin Wrynn.\n\nMy crew is preparing for a special mission, and the king would like you to join us. Please review this official summons and, if you are satisfied, return with me to Stormwind Harbor.\n\n<Rogers hands you a sealed envelope.>", objectives = "" }
WordHunterWoW_QuestEN[38036] = { title = "Supplies From the Skies", description = "Are you feeling alright? Say 'ah.'\n\n<Mishka attempts to depress your tongue with a damp twig.>\n\nSorry... we are in desperate need of medical supplies here. The infirmary on the Skyfire was well-stocked, but it's all scattered to the winds now.\n\nAnything you can salvage from the wreck will save lives!", objectives = "" }
WordHunterWoW_QuestEN[38044] = { title = "Bleeding the Bleeding Hollow", description = "The Bleeding Hollow provide significant reinforcement to the Iron Horde in Tanaan. From their home in Zeth'Gol they relentlessly pursue our scouts, disrupt our operations, and gather more power for Gul'dan's magic.\n\nWe should consider a direct raid on Zeth'Gol to make them pull back their forces across the valley. This should give us some breathing room... for a time.", objectives = "" }
WordHunterWoW_QuestEN[38045] = { title = "Bleeding the Bleeding Hollow", description = "The Bleeding Hollow provide significant reinforcement to the Iron Horde in Tanaan. From their home in Zeth'Gol they relentlessly pursue our scouts, disrupt our operations, and gather more power for Gul'dan's magic.\n\nWe should consider a direct raid on Zeth'Gol to make them pull back their forces across the valley. This should give us some breathing room... for a time.", objectives = "" }
WordHunterWoW_QuestEN[38046] = { title = "Battle At The Iron Front", description = "General, our troops are currently engaged in a conjoined assault at the Iron Front. The fight has been raging for some time now, and casualties are high.\n\nReport to the Iron Front and lend your strength to the war effort. I have no doubt that your presence on the battlefield will inspire the soldiers to victory!", objectives = "" }
WordHunterWoW_QuestEN[38047] = { title = "Battle At The Iron Front", description = "The war against the Iron horde rages on.\n\nNot far from here at The Iron Front, our warriors are engaged in mortal combat with the enemy. They fight tenaciously and with great fury, but the losses have been severe.\n\nGo to The Iron Front and show the enemy that we will not falter in this war.\n\nShow them that we fight as wolves!", objectives = "" }
WordHunterWoW_QuestEN[38052] = { title = "Boarded!", description = "Glad to see you survived the crash. Unfortunately, so did most of the enemy's boarding party.\n\nJust the thought of those monsters setting foot on my ship makes me sick. Wipe them out, {name}. For my crew... For King Wrynn...\n\nFor the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[38053] = { title = "Assault and Battery", description = "We need to report our position to the Alliance navy ASAP!\n\nI am building a new transponder to send a distress signal, but I need a battery from the Skyfire's communications console.\n\nYou'll find the console at the top of the ship - I just hope those undead haven't put their creepy, bony fingers on it yet!", objectives = "" }
WordHunterWoW_QuestEN[38057] = { title = "The Lost Legion", description = "The heroic men and women of the 7th Legion stayed at the front of the ship to fight off storm drakes while the crew evacuated.\n\nNone of them have returned.\n\nPlease find them, {name}!", objectives = "" }
WordHunterWoW_QuestEN[38058] = { title = "Lightning Rod", description = "<Overspark's tiny hands move like lightning, affixing coils and tubes to the device before cramming it into a parachute pack.>\n\nPut this on.\n\nJust up the hill you'll find the front half of the Skyfire - and the big nest of storm drakes it crashed into! We can use the energy from those drakes to charge the transponder.\n\nYou'll have to incite them, of course, but the device should draw most of the power.\n\nThe probability of you being electrocuted is well within acceptable parameters!", objectives = "" }
WordHunterWoW_QuestEN[38059] = { title = "Pins and Needles", description = "Hngghh!\n\nNope, can't stand yet. It's all pins and needles.\n\nSmall fries like this are usually no problem for the 7th, but we weren't prepared for their electrical attacks. Before I knew it, I was trapped in some kind of static field. Couldn't move a muscle until you came along.\n\nMy comrades were carried deeper into the cave. Get 'em out before they become whelp chow!", objectives = "" }
WordHunterWoW_QuestEN[38060] = { title = "Signal Boost", description = "The Skyfire's starboard propeller came to rest on the cliffs overlooking our camp - we're gonna use it like a big antenna and push our distress signal so far that even Mekkatorque's alarm clock could pick it up!\n\nUnfortunately, it might attract some unwanted attention.\n\nWe're braced for enemy contact down here at the camp - fire up that signal and be ready to defend the antenna!", objectives = "" }
WordHunterWoW_QuestEN[38062] = { title = "Yotnar's Blessing", description = "Skovald is in league with legion. He killed my brother Rudiaus and scattered his parts.\n\nRudiaus' corpse has been reanimated... a plaything for the Skovald's minions. That was the last thing I saw before an imp stole my eye and possessed my pet Aetoz. I heard Skovald order his demons to bury the remains of Rudiaus, denying challengers access to the vault.\n\nSkovald underestimates the gods. Bring me my eye and any remains of my brother you find. Complete this task and your trials will begin.", objectives = "" }
WordHunterWoW_QuestEN[38142] = { title = "Archdruid of the Claw", description = "Near the southern edge of our forest you will find Sleeper's Barrow.\n\nThere, Archdruid Koda Steelclaw and her dedicated disciples carry out their sacred duty to observe the Emerald Dream.\n\nFind disciple Rylissa Bearsong in Steelclaw Vale and notify her of the crisis in the Grove of Cenarius.", objectives = "" }
WordHunterWoW_QuestEN[38143] = { title = "Awakening the Archdruid", description = "Now, we must focus our efforts on waking Archdruid Steelclaw.\n\nShe and our druid brethren slumber in the barrow dens to the south.\n\nWith the furbolgs quelled, we can pass safely to the entrance.\n\nGo and awaken the Archdruid. I pray to Elune that we are not too late.", objectives = "" }
WordHunterWoW_QuestEN[38144] = { title = "The Demons Below", description = "Something, someone, intended us to never awaken. I sense their presence is still here in the barrow.\n\n<Koda takes a moment to stand.>\n\nMy body is weak from deep slumber.\n\nIf you would aid us, clear our barrow of any enemies.", objectives = "" }
WordHunterWoW_QuestEN[38145] = { title = "Out of the Dream", description = "Malfurion Stormrage... A name I have not heard in centuries.\n\nHe was teacher to many of us. If he seeks my audience, I cannot refuse.\n\nI will go to the Grove of Cenarius, but first, we must awaken the rest of my clan. They slumber with no way of waking.\n\nA mysterious force of great power is at work against us.\n\nI am still too weak from my hibernation. Please, stranger, go and free them from their dreams.", objectives = "" }
WordHunterWoW_QuestEN[38146] = { title = "The Chieftain's Beads", description = "The ceremonial beads, decorated with shells and feathers, are worn by the clan's chieftain.\n\nPerhaps Elder Sookh would be interested in seeing these.", objectives = "" }
WordHunterWoW_QuestEN[38147] = { title = "Entangled Dreams", description = "I sense powerful magic emanating from deep within the barrow.\n\nWhatever is down there weaves a powerful spell, entangling us within our dreams.\n\nI am still too weak, but your skills are quite impressive, hero. I can see why Malfurion puts his trust in you.\n\nGo and eliminate the source of this magic.", objectives = "" }
WordHunterWoW_QuestEN[38148] = { title = "Return to the Grove", description = "Now that my clan is assembled, we shall return to the Grove of Cenarius.\n\nSpeak to Malfurion when you arrive. We will find out the cause of Cenarius' illness.", objectives = "" }
WordHunterWoW_QuestEN[38175] = { title = "Scrap Meltdown", description = "We've had a breakthrough in melting down the scraps you've been collecting! If you can get me a small pile of 'em, we can get your troops something a bit more useful.", objectives = "" }
WordHunterWoW_QuestEN[38188] = { title = "Scrap Meltdown", description = "We've figured out how to make those scraps in to something a bit more useful to your troops. Bring me a pile of them and I'll have our smiths process it for you.", objectives = "" }
WordHunterWoW_QuestEN[38203] = { title = "Challiane Vineyards", description = "Please, outsider, help me.\n\nMy recipe for Nightrose wine was to be the toast of Queen Azshara herself. But before I could make it, the vile vintners took it from me and locked me away.\n\nPlease, recover my recipe so that I might bring it to Lady Challiane and earn the queen's favor.", objectives = "" }
WordHunterWoW_QuestEN[38206] = { title = "Making the Rounds", description = "You must be wondering what all of this is about. Please, walk with me.\n\nI have some final preparations to make before we set sail, and I know that your presence will inspire the crew.", objectives = "" }
WordHunterWoW_QuestEN[38210] = { title = "The Ancient Trials", description = "<As the raven stares into your eyes, an odd voice fills your mind.>\n\nI know who you are, champion, and I know what you seek.\n\nCome to me, if you think yourself truly worthy.", objectives = "" }
WordHunterWoW_QuestEN[38213] = { title = "Get a Clue", description = "Aktar mentioned that in the ruins he's seen Sethekk, ogres, even demons, but no sign of Iskar.\n\nWe're going to have to go in there if we're to find any clues and I'd prefer someone strong like yourself to lead the way.\n\nWell, what do you say?", objectives = "" }
WordHunterWoW_QuestEN[38223] = { title = "Dark Ascension", description = "You skim through the pages of the tome, most of them filled with notes on the nature of shadow and illusion. On the last pages you discover a journal:\n\nI continue to search for a cure to the curse of Sethe. If Terokk was restored I would not be in this situation. Damn Reshad!\n\nI was contacted by an orc that identified himself as Gul'dan. He has a cure for the curse! I must travel to Tanaan to search for the location of this \"cipher\" of his.\n\nTake this information to Reshad.", objectives = "" }
WordHunterWoW_QuestEN[38225] = { title = "Death to the Witchmother", description = "The numberless years of my life have been dedicated to learning and perfecting the arts of healing and restoration.\n\nNothing in this world pains me more than taking a life, traveler.\n\nIt is with a heavy heart that I must commission the death of Magula, the leader of the harpies that threaten this grove.\n\nMay her death save the lives of more noble beings.", objectives = "" }
WordHunterWoW_QuestEN[38232] = { title = "Minion! Kill Them!", description = "Per your contract you will help me gather supplies for a perfectly harmless ritual.\n\nI need feathers, and horns. Lots of horns. See those shadowrunners, prowlers and heron over there in the Olivian Veil? They should have lots of both.\n\nOh! And I need olives. Lots of olives. One for each finger.\n\nMinion! Let's ride!", objectives = "" }
WordHunterWoW_QuestEN[38235] = { title = "Solid as a Rock", description = "Cenarius requires me?\n\nI shall depart as soon as I am able, but I mustn't leave while my druids are in danger. A vile harpy coven has emerged and seeks to claim my grove as their own.\n\nThese vermin inflict a petrifying disease which, given time, will destroy the infected.\n\nWhile I wish for all of my followers to be cured, it is crucial that my elder disciples survive to protect the grove in my absence.\n\nIf you would assist us, find my disciples and rouse them from this terrible state.", objectives = "" }
WordHunterWoW_QuestEN[38237] = { title = "This IS In My Contract.", description = "To perform my ritual I need to use a special cave I have prepared at Gloombound Barrow.\n\nMeet me there and I will \"give\" you your reward. Hee hee.", objectives = "" }
WordHunterWoW_QuestEN[38240] = { title = "Raid Active", description = "", objectives = "" }
WordHunterWoW_QuestEN[38241] = { title = "Unearthed Magic", description = "Commander, I've heard reports of a strange stone found in the garrison mine.  The miners aren't sure what to make of it, but I have a feeling it could be useful.\n\nWhen you next find yourself at the mine, it may be worth investigating.  And if you don't mind, I would love to see the stone for myself.", objectives = "" }
WordHunterWoW_QuestEN[38242] = { title = "Unearthed Magic", description = "Commander, da miners be findin' somethin' in our mine with strong mojo.  They don' be knowin' what ta do with it, so maybe you gonna go overe dere and check it out?\n\nIf you find it, bring it here so I can look closer at da magic.", objectives = "" }
WordHunterWoW_QuestEN[38243] = { title = "A Bit of Ore", description = "Ore has been in high demand on my trading route, and I'm trying to restock my supply.  Would you be willing to trade?", objectives = "" }
WordHunterWoW_QuestEN[38244] = { title = "More Ore", description = "Ore has been in high demand on my trading route, and I'm trying to restock my supply.  Would you be willing to trade?", objectives = "" }
WordHunterWoW_QuestEN[38246] = { title = "Totemic Call", description = "I heard the others talking earlier. I may know the cause of their fear.\n\nThey say the Chieftain has a mysterious totem. It gives him power, and fearful visions.\n\nIf you destroy the totem, the madness will end.", objectives = "" }
WordHunterWoW_QuestEN[38250] = { title = "Assault on the Ruins of Kra'nak", description = "The Shadow Council have recruited the Sethekk and other power hungry Arakkoa to their service. Our allies in the Order of the Awakened have tracked them to a ruin in the west of Tanaan where the Shadow Council is instructing them in the use of fel magic.\n\nWe must strike at them before they can master their diabolic powers.", objectives = "" }
WordHunterWoW_QuestEN[38252] = { title = "Assault on the Ruins of Kra'nak", description = "The Shadow Council have recruited the Sethekk and other power hungry Arakkoa to their service. Our allies in the Order of the Awakened have tracked them to a ruin in the west of Tanaan where the Shadow Council is instructing them in the use of fel magic.\n\nWe must strike at them before they can master their diabolic powers.", objectives = "" }
WordHunterWoW_QuestEN[38253] = { title = "Garrison Campaign: War Council", description = "Your garrison is in an uproar. King Varian Wrynn himself is visiting your fortress to discuss your invasion plan for Tanaan Jungle.\n\nThe King is ready for you inside your town hall along with his full retinue. It would be wise not to keep him waiting...", objectives = "" }
WordHunterWoW_QuestEN[38254] = { title = "Derailment", description = "Several orcs have spoken out since Gul'dan assumed control. Some were taken prisoner. Among them is an engineering prodigy: Solog Roark, \"The Iron Shipwright.\" He designed these docks as well as the great dreadnaughts of the orcish fleet. If my scouts are right, he's in that prison train as we speak... And he may be ready to defect!\n\nGather explosives and meet with Yrel at the train to the southeast!", objectives = "" }
WordHunterWoW_QuestEN[38255] = { title = "The Train Gang", description = "These rangari will surround and cover the train car. Hit the detonator to blow open the doors.\n\nI will try to talk Roark into joining our cause. He's a genius around a drydock and our best hope for building a shipyard.\n\nIf it doesn't work, we must be prepared to kill him. The last thing we need is someone rebuilding another Iron Fleet...", objectives = "" }
WordHunterWoW_QuestEN[38256] = { title = "Hook, Line, and... Sink Him!", description = "I can build you a shipyard. And not some wasteful piece of over-engineering like this place.\n\nBut I'm going to need my blueprints. My work was confiscated when Gul'dan turned this harbor over to Admiral Knar.\n\n<Roark spits.>\n\nGul'dan's green poison courses through Knar's veins. He's calling the shots from on high. We'll need to grapple up there to take him out.", objectives = "" }
WordHunterWoW_QuestEN[38257] = { title = "We Need a Shipwright", description = "The Iron Horde - or whatever Gul'dan is turning them into - has fallen back and fortified the entrance to Tanaan. A direct assault will take a heavy toll.\n\nHowever, the sea lanes are open. If we attack by both land and sea, Gul'dan's Horde will have no quarter. {name}, it's time to build a shipyard!\n\nWe'll need to source local resources. Travel to the Iron Docks, where a small Alliance reclamation force is already waiting. Gather what equipment you can, and find us a shipwright capable of building a fleet!", objectives = "" }
WordHunterWoW_QuestEN[38258] = { title = "Nothing Remains", description = "Nothing is left for me here. My old clanmates have turned into foes, and Gul'dan is desecrating what remains of my people.\n\nYou and your allies from Shattrath still have some fight left. If you pledge to depose Gul'dan, I will stand by your side. I will go to this garrison of yours and together we will build a shipyard that will rule the red seas of Draenor!\n\nLet your people know I am coming.", objectives = "" }
WordHunterWoW_QuestEN[38259] = { title = "All Hands on Deck", description = "Let's put this \"Iron Shipwright\" of yours to work, commander. If we're to pull off your plan to assault Tanaan from both land and sea, we'll need to get some docks operational as soon as possible. Work with Roark and build the Alliance a shipyard!\n\nLast I saw, Roark was northwest of the garrison, near Eventide Landing.", objectives = "" }
WordHunterWoW_QuestEN[38267] = { title = "Friends Above", description = "Iskar disappeared and now the Shadow Council is at our throats. These can't be unrelated events. We need to go to the last place he was seen, the ruins of Kra'nak.\n\nI've asked a friend to set up a camp nearby. I say we head there to continue our search.", objectives = "" }
WordHunterWoW_QuestEN[38269] = { title = "Friends Above", description = "Iskar disappeared and now the Shadow Council is at our throats. These can't be unrelated events. We need to go to the last place he was seen, the ruins of Kra'nak.\n\nI've asked a friend to set up a camp nearby. I say we head there to continue our search.", objectives = "" }
WordHunterWoW_QuestEN[38270] = { title = "Finding the Killer", description = "With this map, you have pinpointed the origin of the attacks. It is time to see who or what is behind the attacks, and if they are a possible ally.", objectives = "" }
WordHunterWoW_QuestEN[38271] = { title = "Following the Bloody Path", description = "The ones I kill... they speak of a cave. Sacred to the Bleeding Hollow. Kilrogg could be there - I am going.", objectives = "" }
WordHunterWoW_QuestEN[38272] = { title = "The Bleeding Hollow", description = "The cave pulls me. It keeps angry spirits near. Kilrogg has done magic here. You help me understand...", objectives = "" }
WordHunterWoW_QuestEN[38273] = { title = "Spirits of the Bleeding Hollow", description = "It is clear the cave is protected by powerful ghosts, ancestors of the Bleeding Hollow.\n\nWhatever is down there, it will be easier to deal with if many of the spirits were dealt with first.", objectives = "" }
WordHunterWoW_QuestEN[38274] = { title = "The Eye of Kilrogg", description = "If you wish to know what Kilrogg and his new master intend, you will need his eye. After the ritual all chieftains place their eye under the protection of the ghosts of the Bleeding Hollow in the next chamber.\n\nGo and locate the Eye of Kilrogg in the vault. The other chieftains will not stand with us, and will fight you for it.\n\nThen place it on the ritual mark nearby to get your answers.", objectives = "" }
WordHunterWoW_QuestEN[38286] = { title = "Eye of Azshara: Wrath of Azshara", description = "{name}, Warlord Parjesh ran into the magical vortex just ahead. He has returned to an island off the shore to the southeast where Queen Azshara is staging more of her forces.\n\nThe queen is beyond angry because we opposed her. Even now, she is summoning up a monstrosity known as her Wrath to exact revenge for our defiance and drown the Broken Isles.\n\nYou must defeat the Wrath of Azshara before the queen lets it loose to destroy us all!", objectives = "" }
WordHunterWoW_QuestEN[38287] = { title = "Raw Beast Hides", description = "Raw beast hide has been in high demand on my trading route, and I'm trying to restock my supply.  Would you be willing to trade?", objectives = "" }
WordHunterWoW_QuestEN[38288] = { title = "Raw Beast Hides", description = "Raw beast hide has been in high demand on my trading route, and I'm trying to restock my supply.  Would you be willing to trade?", objectives = "" }
WordHunterWoW_QuestEN[38290] = { title = "Some Dust", description = "Draenic dust has been in high demand on my trading route, and I'm trying to restock my supply.  Would you be willing to trade?", objectives = "" }
WordHunterWoW_QuestEN[38291] = { title = "Some Dust", description = "Draenic dust has been in high demand on my trading route, and I'm trying to restock my supply.  Would you be willing to trade?", objectives = "" }
WordHunterWoW_QuestEN[38293] = { title = "Sumptuous Fur", description = "Sumptuous fur has been in high demand on my trading route, and I'm trying to restock my supply.  Would you be willing to trade?", objectives = "" }
WordHunterWoW_QuestEN[38294] = { title = "Sumptuous Fur", description = "Sumptuous fur has been in high demand on my trading route, and I'm trying to restock my supply.  Would you be willing to trade?", objectives = "" }
WordHunterWoW_QuestEN[38296] = { title = "Herbs Galore", description = "Herbs have been in high demand on my trading route, and I'm trying to restock my supply.  Would you be willing to trade?", objectives = "" }
WordHunterWoW_QuestEN[38297] = { title = "Herbs Galore", description = "Herbs have been in high demand on my trading route, and I'm trying to restock my supply.  Would you be willing to trade?", objectives = "" }
WordHunterWoW_QuestEN[38299] = { title = "Critters of Draenor", description = "I love collecting pets, and I've picked up a few unusual pets here in Draenor.  What would you say to a battle?  If you can defeat my humble team, I think we'll both learn a few new tricks.", objectives = "" }
WordHunterWoW_QuestEN[38300] = { title = "Critters of Draenor", description = "I love collecting pets, and I've picked up a few unusual pets here in Draenor.  What would you say to a battle?  If you can defeat my humble team, I think we'll both learn a few new tricks.", objectives = "" }
WordHunterWoW_QuestEN[38307] = { title = "The Warchief Beckons", description = "Greetings, {name}. I am here on behalf of Lady Sylvanas Windrunner. I should hope you recognize the name.\n\n<Nathanos thrusts a sealed envelope into your hand.>\n\nRead it and follow me.\n\nYou can read, can't you?", objectives = "" }
WordHunterWoW_QuestEN[38308] = { title = "Eyes in the Overlook", description = "Alliance personnel from the Skyfire were spotted parachuting into Blackbeak Overlook.\n\nI was unable to confirm numbers or positions during my flyover, but I did see parachutes tangled in treetops and a LOT of ravenbears on the ground.\n\nIf anyone is up there, they must be laying low and keeping an eye on us.\n\nI have posted a rider at the top of the overlook to keep watch while I press forward into Stormheim.\n\n- Liza Cullen, Dread-Rider - 1st Wing", objectives = "" }
WordHunterWoW_QuestEN[38312] = { title = "A Grapple a Day", description = "So these trials are what will get us the Aegis, and the next one is on the top of that mountain? That may prove problematic.\n\nThe only way I see up the mountain is through that vrykul city, and the gates are shut tight. We should be able to grapple over, though. If you don't have a launcher, I managed to wrangle a spare from one of these vrykul.\n\nI'll scout ahead and see if I can find a good spot to get in.", objectives = "" }
WordHunterWoW_QuestEN[38317] = { title = "Masters of Disguise", description = "<You scan over Knockwhistle's report.>\n\n\"My chute caught a piece of shrapnel. Made a rough landing in a ravenbear nest. Luckily, a bunch of eggs broke my fall.\n\nLost sight of Illandris and Shwayder. Both are masters of disguise, and I am confident they can remain undetected.\n\nWill continue to monitor the enemy's activity. Just need to clean all the yolk off my cloaking device. Hope the mother's not around...", objectives = "" }
WordHunterWoW_QuestEN[38318] = { title = "No Wings Required", description = "Now that you've got the launcher, we should be able to infiltrate the city. It looks like there's a good spot to grapple onto on the wall just past us. There's a vantage point on top of this ridge.\n\nOnce we're in, I'll try to slip past the guards and get a look at the mountain path. I'd appreciate if you could make some distractions for me. If all goes well, I'll meet up with you in the upper city.\n\nGood luck!", objectives = "" }
WordHunterWoW_QuestEN[38322] = { title = "Return to the Grove", description = "Now that my grove is safe, I can turn my attention to the threat you speak of.\n\nTo hear of Cenarius' plight is disturbing indeed. Tell Malfurion that I shall meet him at the Grove.", objectives = "" }
WordHunterWoW_QuestEN[38323] = { title = "Return to the Grove", description = "Forgive me, {race}. Archdruid Moonclaw's fall is a terrible blow...\n\nMalfurion must be informed of what has transpired here. Inform him of Thaon's fate and of the return of Xavius.\n\nMake haste, friend. I fear this may be the greatest threat Val'sharah has ever faced.", objectives = "" }
WordHunterWoW_QuestEN[38324] = { title = "Accessories of the Cursed", description = "Wait! Before ye go rushin' off, we might want to be gettin more than just seaweed. \n\nYe see, these vrykul also be carrying bones with them - worn all over like jewelry. If ye can get yer hands on some of the bones they got lyin around, it'll add to the disguise.\n\nSo what ye waitin for?", objectives = "" }
WordHunterWoW_QuestEN[38331] = { title = "Havi's Test", description = "I could sense your power the moment you arrived in this land. You carry great purpose and a heavy task.\n\nKnow that the Aegis of Agrammar rests in the high halls of the All-Father. Only if you prove your valor, can you claim it against your foe.\n\nMany trials must you face for this, but first I must know your strength. My stew is incomplete, and my old bones couldn't carry the ingredients up the hill. \n\nYou look like you have a good arm. Will you help an old man finish his stew?", objectives = "" }
WordHunterWoW_QuestEN[38332] = { title = "The Ranger Lord", description = "Good to see you survived the wreck. Nathanos made it as well, though his face is now even uglier than before.\n\nHe took a group of rangers north to look for Sylvanas - nobody has seen her since the battle.\n\nHe asked me to send you his way if you ever woke up.", objectives = "" }
WordHunterWoW_QuestEN[38337] = { title = "Built to Scale", description = "The vrykul around here seem to use scales from these drakes to fashion their armor. \n\nIf you were able to gather enough material from the local drakes, you may be able to make something useful out of it.", objectives = "" }
WordHunterWoW_QuestEN[38339] = { title = "A Little Kelp From My Foes", description = "I'm not sure what yer doin' here, but ye have my thanks. If ye want to get any further, though, ye'll need to get past that foul dog, Guarm.\n\nI've tried meself a few times, and I think I have a plan. If we can get some of the seaweed these kvaldir wear, we might be able to trick the mutt. Guarm's mean, ye see, but not too smart.\n\nWhat do ye say? Think ye can take on a few kvaldir?", objectives = "" }
WordHunterWoW_QuestEN[38342] = { title = "Another Way", description = "Well, the bridge option is out. You still got that grapple launcher handy?\n\nIt looks like we can get across from the top of that tower over there. First thing's first, though, we'll need to deal with the big ugly sitting out front.\n\nYou take point.", objectives = "" }
WordHunterWoW_QuestEN[38347] = { title = "Stealth by Seaweed", description = "There! The disguise be complete!\n\nDon't mind the smell, there. It's probably better that we smell like the kvaldir, as well. Though I have a feeling I'll be needin a priest to get this stench out once we're gone.", objectives = "" }
WordHunterWoW_QuestEN[38351] = { title = "Portable Portals", description = "My assistants have figured out how to convert ogre waystones into useful items for our garrison. Speak with Varsha outside to start your first work order.", objectives = "" }
WordHunterWoW_QuestEN[38354] = { title = "Portable Portals", description = "My assistants have figured out how to convert ogre waystones into useful items for our garrison.  Speak with Apprentice Var'nath outside to start your first work order.", objectives = "" }
WordHunterWoW_QuestEN[38356] = { title = "Bringing the Bass", description = "It's a bit quiet around here, in between the invasions and all.\n\nYou're in luck though, Commander! I can fix that, and boost morale among your troops all at the same time.\n\nAll you need to do is bring me a few items from around Draenor, and I'll fill your garrison with music. I'll even throw in a few music rolls from my own collection to get you started!\n\nWhat do you say?", objectives = "" }
WordHunterWoW_QuestEN[38357] = { title = "Side Effects May Include Mild Undeath", description = "Exposure to this particular \"byproduct\" is quite nasty.\n\nRapid cell degeneration quickly reduces the subject to a shambling husk incapable of any reason or thought beyond a violent, throbbing hatred for the warmth of life.\n\nAs you might imagine, the local fauna have been affected by the spill. Oh, and most of the crew as well...\n\nAnyway, good luck!", objectives = "" }
WordHunterWoW_QuestEN[38358] = { title = "Pump it Up", description = "The Black Rose was a seafaring laboratory for the Royal Apothecary Society. Naturally, we had some volatile... \"byproducts\" onboard.\n\nRegrettably, one such substance was released during our skirmish with the Alliance gunship. As you can see, it is taking quite a toll on the coast.\n\nThe R.A.S. must remedy this situation before we press further inland.\n\nPlease take a containment unit and fill it with waste - for us to dispose of properly at a later time, of course.", objectives = "" }
WordHunterWoW_QuestEN[38360] = { title = "The Windrunner's Fate", description = "Finding Sylvanas is our only priority!\n\nWe will cover more ground if we split up. I will lead a team into the hills above the enemy's camp while you search the wreckage itself for any signs of the crew.\n\nOnce we've cleared the high ground, I will meet you at the far end of the beach.", objectives = "" }
WordHunterWoW_QuestEN[38361] = { title = "Wrath of the Blightcaller", description = "The Alliance dogs have bitten off more than they can chew. They have attacked the Banshee Queen, and invoked the wrath of her champion!\n\nLike my bow, my axes, and my hounds, you will be an agent of vengeance. Pile the bodies high, {class}, and know that I am doing the same. When next we meet, I expect to see blood upon your hands.", objectives = "" }
WordHunterWoW_QuestEN[38362] = { title = "A Grim Trophy", description = "It would seem Sylvanas does not wish to be followed - by us or anyone else.\n\nHer will is her own, it is not my place to question. Only to obey.\n\nIn the hills nearby, a gryphon master is preparing to take flight, no doubt to pursue our queen from the sky. My rangers are lying in wait - we need only to close our jaws around him.\n\nI will have his head when this is over.", objectives = "" }
WordHunterWoW_QuestEN[38376] = { title = "The Search for the Highlord", description = "Tirion is fading away on that infernal shore... and the Ashbringer with him! We must not waste another moment.\n\nGive the word and we'll set off. We're ready when you are.", objectives = "" }
WordHunterWoW_QuestEN[38377] = { title = "The Emerald Queen", description = "{name}, you have returned. Good.\n\nI have counseled with the other archdruids and concluded that Cenarius' condition is merely a symptom of a much greater problem. Your experiences in Moonclaw Vale make that clear.\n\nWe need help.\n\nThere is one who can bring understanding to these events. With Thaon gone, we must ask that you aid us in reaching out to the Lady of Dreams.", objectives = "" }
WordHunterWoW_QuestEN[38381] = { title = "Archdruid of Lore", description = "Elothir resides in the ancient grove Thas'talah, where he communes with nature and instructs his acolytes in the ways of healing and the preservation of lore.\n\nSeek him out and tell him that he is desperately needed here.", objectives = "" }
WordHunterWoW_QuestEN[38382] = { title = "Archdruid of the Vale", description = "Deep within our forest lies Moonclaw Vale.\n\nThere you will find a reclusive group of feral druids charged with the protection of Val'sharah from any that would seek to disrupt the balance of nature.\n\nThese druids are led by Thaon Moonclaw, the most fierce of the Archdruids.\n\nSeek him out. Let him know that Cenarius is in need of his aid.", objectives = "" }
WordHunterWoW_QuestEN[38384] = { title = "Nature's Call", description = "What vile power is this?!\n\nA curse with the strength to paralyze a demigod? Unimaginable!\n\nQuickly, {name}, you must gather the archdruids of the forest. With their help, we can summon Ysera. She will surely know what horror has overtaken my mentor.\n\nI will remain here and lend Cenarius what aid I can.\n\nReturn to Lorlathil and speak with Aranelle. She will know the archdruids' whereabouts.\n\nAnd please, friend, make haste...", objectives = "" }
WordHunterWoW_QuestEN[38399] = { title = "Fencing the Rose", description = "Looking to sell something?", objectives = "" }
WordHunterWoW_QuestEN[38405] = { title = "To Weather the Storm", description = "I've been doing some nosing around, and it looks like these vrykul are making regular trips up the mountain themselves. They've got some specialized gear for it, so while we're here we should take some.\n\nI'd recommend finding some climbing treads to keep your grip on the slopes, as well as an oiled cloak to keep the rain out. Also, it looks like they carry enchanted lodestones, which seem to keep the lightning at bay. You should probably grab one of those, too.", objectives = "" }
WordHunterWoW_QuestEN[38407] = { title = "Bottled Up", description = "<You've found a message in a bottle on the corpse. It's a request for aid from someone named Okuna Longtusk. Okuna claims that he and his fellow shipmates are being held prisoner by sea giants.\n\nMaybe if you show the note to the ghost of Lady Irisse at the Crumbled Palace, she can point you in the right direction?>", objectives = "" }
WordHunterWoW_QuestEN[38408] = { title = "New Goods", description = "New items are available from Sergeant Crowler.  I suggest you stop by and take a look at his new goods as soon as you can!", objectives = "" }
WordHunterWoW_QuestEN[38410] = { title = "Impalement Insurance", description = "I've got bad news. Those harpoon launchers up on the walls might cause us some problems. \n\nThey can't get at us down here, but once you start climbing that path, they're likely going to try to skewer you.\n\nIf you use that grapple launcher, you should be able to get on top of the walls and dismantle them. Watch out for the drakes, though!", objectives = "" }
WordHunterWoW_QuestEN[38412] = { title = "Above the Winter Moonlight", description = "You should have a good vantage from this tower to grapple over to the mountain path. I can't help you once you're across, but you should be able to take it all the way up to the top. \n\nI hope you're able to find what you need from the dragons up there. Who knows what the God-King has done to them.", objectives = "" }
WordHunterWoW_QuestEN[38413] = { title = "Wings of Liberty", description = "When the Felskorn assaulted the nest, the Thorignir fought bravely to save our brood. But their demonic allies proved too much, and many of us were captured.\n\nEven now they work to corrupt my brothers and sisters to turn them to their side. \n\nPlease, outsider, free them from this fate!", objectives = "" }
WordHunterWoW_QuestEN[38414] = { title = "Heart of a Dragon", description = "Through brute force and corruption, the God-King has taken the power you seek, but there may be hope for you and the Thorignir, {class}.\n\nWith the aid of fel powers such as I've never seen, the Felskorn are corrupting our young and seeking to enslave the Thorignir. Their leader, a demon of great power, has captured our mother and seeks to bend her to the God-King's will.\n\nFind her and free her from the demon's grasp - only then might the Thorignir regain our power and grant you aid.", objectives = "" }
WordHunterWoW_QuestEN[38415] = { title = "Garrison Campaign: Onslaught at Auchindoun", description = "Your ally, Liadrin, has sent a missive requesting aid near Auchindoun. The Sargerei have made a new assault there and breached something important. It is no coincidence this happened after Gul'dan's ascendancy. We will watch the front here, commander.", objectives = "" }
WordHunterWoW_QuestEN[38416] = { title = "Secrets of the Sargerei", description = "The Auchenai have been reporting for some time that something was... wrong... with Auchindoun. They were never able to find a reason. Suddenly the Sargerei attacked and blew open a hole into a subchamber.\n\nCorruption leaks from that hole, we need to stop it.", objectives = "" }
WordHunterWoW_QuestEN[38417] = { title = "The Sargerei Menace", description = "An attack such as this was unexpected. They have deployed heavily and it will take me some time to marshal enough forces to root them out.\n\nAny Sargerei you can slay will make retaking this area much easier commander.", objectives = "" }
WordHunterWoW_QuestEN[38421] = { title = "Garrison Campaign: Onslaught at Auchindoun", description = "The Auchenai have sent me an urgent missive - Auchindoun is in jeopardy again! The Sargerei have renewed their assault  and breached the underhalls. I sense the hand of Gul'dan is behind this.\n\nGather your things and meet me in the Court of Souls West of Auchindoun at once!", objectives = "" }
WordHunterWoW_QuestEN[38427] = { title = "New Goods", description = "New items are available from Sergeant Grimjaw.  I suggest you stop by and take a look at his new goods as soon as you can!", objectives = "" }
WordHunterWoW_QuestEN[38428] = { title = "A Fel Puppy Of My Own", description = "", objectives = "" }
WordHunterWoW_QuestEN[38435] = { title = "The Invasion of Tanaan", description = "It is done! By your command we have built our first ship and can run our naval operations from here.\n\nNow that we have our transport, we can let Yrel and Archmage Khadgar know that we are ready to kick off an invasion of Tanaan. Speak with them at the docks to embark.", objectives = "" }
WordHunterWoW_QuestEN[38436] = { title = "Obstacle Course", description = "Our landing was unopposed. Why are these docks all but abandoned?\n\nThe rangari scouts up ahead report trouble. Bleeding Hollow scavengers are looting some abandoned buildings to the northwest, and an encampment of warlock cultists lurk near the Dark Portal. Let's find out what we can and meet up with our scouts.", objectives = "" }
WordHunterWoW_QuestEN[38440] = { title = "Assault on The Fel Forge", description = "The Iron Horde is growing stronger each day as their war machines are empowered with fel magic. We have even obtained word that they are constructing a Fel Reaver!\n\nHead to the Fel Forge and destroy their forces before we are overwhelmed.", objectives = "" }
WordHunterWoW_QuestEN[38441] = { title = "Assault on The Fel Forge", description = "The Iron Horde is growing stronger each day as their war machines are empowered with fel magic. We have even obtained word that they are constructing a Fel Reaver!\n\nHead to the Fel Forge and destroy their forces before we are overwhelmed.", objectives = "" }
WordHunterWoW_QuestEN[38443] = { title = "Journey to the Repose", description = "For now, the Illidari can hold the line against the Legion. We will return later to help them drive the Legion from the upper reaches of Faronaar. You and I must concentrate on the Pillars of Creation if the Tomb of Sargeras is to be resealed.\n\nYour saving of Stellagosa is fortuitous. Surely if anyone knows where a Pillar of Creation is, it will be her grandfather, Senegos.\n\nThe Azurewing Repose is to the northeast. I will meet you there, {name}.", objectives = "" }
WordHunterWoW_QuestEN[38444] = { title = "In, Through, and Beyond!", description = "Gul'dan seems to have concentrated his defenses on this chokepoint. The guns up ahead are unlike anything we've seen before - they're empowered with fel energy.\n\nOur enemies think this pass is impregnable. Let's prove them wrong, commander! If we can break through, the terrain ahead will make an excellent stronghold. Destroy that cannon!", objectives = "" }
WordHunterWoW_QuestEN[38445] = { title = "The Assault Base", description = "While you were playing with fel fire, I've located the perfect position for an assault outpost.\n\nFollow me and we can get this base started!", objectives = "" }
WordHunterWoW_QuestEN[38446] = { title = "Commander in the Field!", description = "This battle will be won, but it will be hard fought. Our rangari did manage to get a few scouts out to the rest of the jungle though.\n\nPerhaps it is best you collect this intelligence yourself and see what this jungle holds for us all.", objectives = "" }
WordHunterWoW_QuestEN[38449] = { title = "Assault on the Temple of Sha'naar", description = "Up in the hills of Tanaan Jungle, the Sargerei have converted a once-sacred temple into a den of demonic summoning.\n\nWe must attack them now, before their rituals complete. The longer we delay, the stronger our enemy grows.", objectives = "" }
WordHunterWoW_QuestEN[38453] = { title = "Garrison Campaign: The Bane of the Bleeding Hollow", description = "Commander, now that we've had time to get scouts all over the jungle we have heard some news near Zeth'Gol.\n\nIt appears that somebody else has a vendetta against the Bleeding Hollow and has been... hunting... them. Their hunters are closing in on the assassin.\n\nYou know what they say about \"the enemy of my enemy...\" We should collect their tracking maps and try to find the killer first!", objectives = "" }
WordHunterWoW_QuestEN[38455] = { title = "Frenzied Furbolgs", description = "I would help you seek audience with the Archdruid, but we have a difficult situation on our hands.\n\nThe nearby furbolgs have gone into a frenzied rage.\n\nFor days, it has been all we can do to protect our grove from their aggression.\n\nThey have cut off our access to the barrow dens, where the Archdruid and our clan sleep in the Emerald Dream.\n\nIn order to awaken them, we must first get past the furbolg.", objectives = "" }
WordHunterWoW_QuestEN[38458] = { title = "Garrison Campaign: The Warlock", description = "Commander, you have a visitor. One of Gul'dan's warlocks just walked up to the base and surrendered. He says he has information of a terrible event that is about to occur.\n\nI suggest you speak with him immediately.", objectives = "" }
WordHunterWoW_QuestEN[38459] = { title = "The Ancient Trials", description = "<As the raven stares into your eyes, an odd voice fills your mind.>\n\nI know who you are, champion, and I know what you seek.\n\nCome to me, if you think yourself truly worthy.", objectives = "" }
WordHunterWoW_QuestEN[38460] = { title = "Let's Make A Deal", description = "Hey there!\n\nYou seem like a gullib- er... um... \"intelligent\" type.\n\nI propose a deal.\n\nI need a minion to be my muscle to help me acquire a few special... \"ingredients\" for a ritual.\n\nIn exchange, I'll give you my former master to do with whatever you demon-slaying types do with demons.\n\nIf you are interested, just sign here. In blood, please.", objectives = "" }
WordHunterWoW_QuestEN[38462] = { title = "Breaching the Barrier", description = "The ritual site is already prepared, and it is protected by a barrier... one that I created. I can destroy the barrier, but I will need three items currently in use at Forge Camp Vengeance.\n\nIf you can get those ritual items, I will meet you at the Corrupted Refuge and remove the barrier. Even if it kills me.", objectives = "" }
WordHunterWoW_QuestEN[38463] = { title = "The Cipher of Damnation", description = "Your ally and I will remove this barrier now, though it will take a greater part of our strength. What lies beyond will not be easy.\n\nGul'dan will have empowered an elemental lord with the Cipher, driving it insane. He will use it to destroy the link between the elements and Draenor. If you destroy that elemental, we could recover the Cipher.", objectives = "" }
WordHunterWoW_QuestEN[38473] = { title = "Will of the Thorignir", description = "In the summit of storms the dragons await. Born of the gods, they will test your will. \n\nThey roost above Hrydshal, where their children serve the Drekirjar. But they are no allies to man or vrykul, and so you must earn their blessing as they see fit.\n\nA friend of yours awaits in Hrydshal, no doubt searching for the answers you now possess. Go to her, and together, you will test your might against the storm!", objectives = "" }
WordHunterWoW_QuestEN[38499] = { title = "Strange New Ores", description = "You smell that, smith? Ahhhh... that there's the smell of opportunity.\n\nDalaran's taken us to some strange new shores, filled with mysterious metals. I'm tethered to my shop here, but you... you've got the freedom to explore and mine at will.\n\nBring me something interesting, and we'll see what we can make with it.", objectives = "" }
WordHunterWoW_QuestEN[38500] = { title = "Leysmithing Mastery", description = "Well, now that we have the flux we can put it to work and see how it goes. Why don't you take a crack at it this time and make some gauntlets for me. I'll observe your work... from a distance.", objectives = "" }
WordHunterWoW_QuestEN[38501] = { title = "Hatecoil Hammerwork", description = "There may be a way to jump-start our research into leystone.\n\nI've heard reports of naga camps down in Azsuna. If they've been in Azsuna for long enough, their smiths have certainly started experimenting with leystone themselves.\n\nBe on the lookout for some leystone armor on the naga... ideally something more elaborate than a bracer.", objectives = "" }
WordHunterWoW_QuestEN[38502] = { title = "The Methods of the Nightfallen", description = "I have a theory, {name}.\n\nHave you encountered the nightfallen elves of Azsuna? They descend from the Highborne, and the accomplishments of Highborne smiths are legendary.\n\nThese fallen elves do a bit of arcane tinkering, crafting sentries to patrol their camps.\n\nBring me a memory core from one of their constructs. Who knows what manner of smithlore might lie within!", objectives = "" }
WordHunterWoW_QuestEN[38505] = { title = "Engineers: Not COMPLETELY Useless", description = "Unfortunately, I have no idea how to access any information within this core. But I know someone who does.\n\nHead over to \"Like Clockwork\", the engineering shop three doors down from here. Timofey Oshenko owes me a favor. He should be able to extract the memory out of the core.", objectives = "" }
WordHunterWoW_QuestEN[38506] = { title = "Chicken Scratch", description = "I think I have just the thing to extract the information from this core for you.\n\n<Timofey loads the core into the hopper of a clearly goblin-made machine, then covers his ears.>\n\nYou may wish to avert your eyes, blacksmith.", objectives = "" }
WordHunterWoW_QuestEN[38507] = { title = "Secrets of Leysmithing", description = "I could spend hours poring over the details of this fascinating manuscript!\n\n...is what I would say if this weren't the simplest of tasks for someone of my skill level. It's about something called \"Leysmithing\". Here.\n\n<The gnome scribbles down a translation on the back of the scroll.>\n\nThere it is, word-for-word. Bring me something interesting next time.", objectives = "" }
WordHunterWoW_QuestEN[38513] = { title = "The Highmountain Smiths", description = "I think we've gone as far as we can go with what I know, {name}.\n\nThe tauren of Highmountain must have some smiths among their ranks. See if you can find out how to further progress our leysmithing abilities from them.", objectives = "" }
WordHunterWoW_QuestEN[38514] = { title = "You Are Not Worthy", description = "You wish me to teach you how to strengthen your crafts? We do not simply share the secrets of our trade with outsiders who ask for them.\n\nWe do, however, respect craftsmanship and discipline.\n\nLet's see your hammerwork. Our greenhorn trainees use those small anvils over there. Craft your best pair of gauntlets so I may judge your work.", objectives = "" }
WordHunterWoW_QuestEN[38515] = { title = "Nature Provides", description = "This is interesting, it says that leystone reacts violently with anything it views as a contaminant. Our foreign-mined flux was enough to cause the small explosion.\n\nLocal ingredients, however, have learned to coexist with leystone. Up in Highmountain, an herb called foxflower grows that can be turned into a suitable flux.\n\nGo and gather some foxflower that we can turn into a usable flux.", objectives = "" }
WordHunterWoW_QuestEN[38518] = { title = "From One Master to Another", description = "Now young one, go back to your master\nin Dalaran and continue to practice your swing. We'll always be here if you wish to come back and learn more.", objectives = "" }
WordHunterWoW_QuestEN[38519] = { title = "Grayheft", description = "Our tribe regularly crafts legplates out of leystone. I will share our pattern with you... if you do me a favor.\n\nMy father fell to the drogbar several years ago, and they took his hammer as a trophy. That hammer was in my family for countless generations. Now, it languishes in the hands of the vile drogbar, Kubrul.\n\nI would very much like to have it back.", objectives = "" }
WordHunterWoW_QuestEN[38522] = { title = "Not Just Weapons and Armor", description = "You know, we aren't just limited to armorsmithing and weaponsmithing. I regularly make chisels for the scribes, crucibles for the alchemists, and even thimbles for the tailors.\n\nThey should sew in full plate gauntlets if they're really all that worried about their poor little thumbs.\n\nAnyhow, I have a recipe I think an adventurer like you might be interested in. Let's try it out.", objectives = "" }
WordHunterWoW_QuestEN[38523] = { title = "Leystone Hoofplates", description = "Here, bring these hoofplates to Mei Francis, down at the mounts and pets store, to get your mount properly shod.\n\nI'll share the pattern when you return.", objectives = "" }
WordHunterWoW_QuestEN[38524] = { title = "Felsmith Nal'ryssa", description = "Word has been circulating in smithing circles about a pair of Illidari blacksmiths that have been doing exciting work out on the demon-infested front lines of Suramar. I'd follow up myself, but anything described as \"demon-infested\" is a little too exotic for my tastes.\n\nI just make the armor. I prefer not to wear it.\n\nYou, though... you could follow up on this tip. Be on the lookout for Nal'ryssa. From what I hear, she's a hell of a smith.", objectives = "" }
WordHunterWoW_QuestEN[38525] = { title = "Part of the Team", description = "You're a blacksmith?\n\n<The elf looks down at your hammer.>\n\nStill working in leystone, are you? I might be able to help you out.\n\nAlliances out here are hard-won. You've got a pretty face, but that's no guarantee that you aren't working for the demons. I can't afford to trust you yet.\n\nDon't come back until you're caked in demon's blood. Then we'll talk smithing.", objectives = "" }
WordHunterWoW_QuestEN[38526] = { title = "Smith Under Fire", description = "You lack recipes for boots?\n\nWhat, were you trained by a tauren or something?\n\nHurry up, then. We probably have a few minutes before the demons attack again. Here's a pattern - show me your work.", objectives = "" }
WordHunterWoW_QuestEN[38527] = { title = "Nal'ryssa's Technique", description = "Listen, {class}. We need smiths like you to carry on the traditions of the Illidari, should we fail in our crusade against the Legion. You are ready to learn.\n\nBring me materials. Lots of them. When you return, we will have much to discuss.", objectives = "" }
WordHunterWoW_QuestEN[38528] = { title = "Leystone's Potential", description = "As I'm sure you've deduced, all of the leystone recipes you know can be improved.\n\nBy learning to harness leystone's true potential, you can reduce the amount of material you use and still yield an equivalent result. Here, I'll show you.\n\nWe'll start, as one does, with the humble bracer. This particular piece of armor benefits from the addition of brimstone runes. See for yourself.", objectives = "" }
WordHunterWoW_QuestEN[38530] = { title = "The Firmament Stone", description = "When working with felslate and demonsteel, one must use special equipment. Specifically, an anvil hard enough to withstand the energy given off when felslate is hammered.\n\nUrael and I no longer possess such an anvil. But your friends, the Highmountain tauren, do.\n\nGain access to the Firmament Stone, their sacred anvil, and we can start working with demonsteel again.", objectives = "" }
WordHunterWoW_QuestEN[38531] = { title = "Leystone Mastery", description = "Smiths that seek access to the Firmament Stone must first prove complete mastery over leystone.\n\nCraft an entire set of Leystone Armor, then submit it to me for inspection. Thala can provide you with an armor stand.", objectives = "" }
WordHunterWoW_QuestEN[38532] = { title = "Maw of Souls: Hammered By The Storm", description = "Your hammer looks weak, and would probably break upon striking the Firmament Stone.\n\nThe vrykul master blacksmiths of old were known for the strength of their hammers. The only way to get our hands on such a hammer would be to go where vrykul go when they die. To the Maw of Souls.\n\nThe goddess that resides over that realm is named Helya. She hoards the trinkets they bring for her own desires.\n\nDefeat her and you may be able to acquire such a hammer.", objectives = "" }
WordHunterWoW_QuestEN[38533] = { title = "Tribal Knowledge", description = "First, however, you'll need proper patterns for demonsteel armor. While access to the stone is earned through hard work and perseverance, access to our recipes is limited to the trusted members of our tribe.\n\nPerhaps you should seek another smith if you wish to discuss demonsteel patterns.", objectives = "" }
WordHunterWoW_QuestEN[38534] = { title = "Demonsteel Armguards", description = "", objectives = "" }
WordHunterWoW_QuestEN[38536] = { title = "Demonsteel Waistguard", description = "", objectives = "" }
WordHunterWoW_QuestEN[38537] = { title = "Demonsteel Pauldrons", description = "", objectives = "" }
WordHunterWoW_QuestEN[38538] = { title = "Demonsteel Boots", description = "", objectives = "" }
WordHunterWoW_QuestEN[38539] = { title = "Demonsteel Gauntlets", description = "", objectives = "" }
WordHunterWoW_QuestEN[38540] = { title = "Demonsteel Helm", description = "", objectives = "" }
WordHunterWoW_QuestEN[38541] = { title = "Demonsteel Greaves", description = "", objectives = "" }
WordHunterWoW_QuestEN[38542] = { title = "Demonsteel Breastplate", description = "", objectives = "" }
WordHunterWoW_QuestEN[38552] = { title = "Lord Hal'shara's Tomb", description = "The tomb, I've found it.", objectives = "" }
WordHunterWoW_QuestEN[38558] = { title = "See Ya Later, Oscillator", description = "Those jawless mooks are actually trying to salvage parts from our ship! They can't possibly appreciate superior gnomish technology... Perhaps its shiny nature is appealing to their simple inclinations.\n\nIn any case, I need a crystal oscillator for our new transponder. It's the shiniest part of the whole system, they're bound to have it set aside somewhere!", objectives = "" }
WordHunterWoW_QuestEN[38559] = { title = "Worthy of the Stone", description = "You have nothing more to prove to me, {name}. Your training is complete.\n\nOnly a very small herd of smiths have earned the right to the Firmament Stone. You should speak with Muirn Ironhorn, who maintains vigil over our sacred stone. He will tell you what to do next.", objectives = "" }
WordHunterWoW_QuestEN[38560] = { title = "Garrison Campaign: The Bane of the Bleeding Hollow", description = "Commander, now that we've had time to get scouts all over the jungle we have heard some news near Zeth'Gol.\n\nIt appears that somebody else has a vendetta against the Bleeding Hollow and has been... hunting... them. Their hunters are closing in on the assassin.\n\nYou know what they say about \"the enemy of my enemy...\" We should collect their tracking maps and try to find the killer first!", objectives = "" }
WordHunterWoW_QuestEN[38561] = { title = "Garrison Campaign: The Warlock", description = "Commander, you have a visitor. One of Gul'dan's warlocks just walked up to the base and surrendered. He says he has information of a terrible event that is about to occur.\n\nI suggest you speak with him immediately.", objectives = "" }
WordHunterWoW_QuestEN[38562] = { title = "Secrets of the Sargerei", description = "The Auchenai have been reporting for some time that something was... wrong... with Auchindoun since Teron'gor's original assault. Now suddenly the Sargerei attacked and blew open a hole into one of the underhalls.\n\nCorruption leaks from that breach. We must investigate!", objectives = "" }
WordHunterWoW_QuestEN[38563] = { title = "Flower-Pickers and Potion-Quaffers", description = "Now that we know the foxflower flux is safe to use, we can start stocking it. That being said, I don't particularly feel like picking flowers. Do you feel like picking flowers? Didn't think so.\n\nGo talk to the alchemists and herbalists across the way. I'm sure we can set up some sort of work order arrangement.", objectives = "" }
WordHunterWoW_QuestEN[38564] = { title = "A Sweet Bargain", description = "Reading over this research, I found an interesting method that I'd like you to try.\n\nThe method would require us to chill the metal to sub-freezing temperatures during the pre-tempering phase. Simple water quenching won't do.\n\nGood thing you can't walk two steps in this city without bumping into a frost mage! See if you can recruit one for the shop, {name}.", objectives = "" }
WordHunterWoW_QuestEN[38565] = { title = "The Sargerei Menace", description = "This attack surprised our defenders. Forces are marshalling to push them out, but it will take some time for them to arrive.\n\nAny Sargerei you can slay will make retaking this area much easier commander.", objectives = "" }
WordHunterWoW_QuestEN[38566] = { title = "A United Force", description = "The paladins of Azeroth must stand united behind a single leader. With Tirion's passing, you are the one most worthy to wear the mantle of Highlord.\n\nIf you agree to accept this duty, inscribe your name into the Libram of Ancient Kings and I will address the masses on your behalf.\n\nThe Order of the Silver Hand is reborn, with you as its champion!", objectives = "" }
WordHunterWoW_QuestEN[38567] = { title = "Garrison Campaign: War Council", description = "Your garrison is in an uproar. Warchief Vol'jin himself is visiting your fortress to discuss your invasion plan for Tanaan Jungle.\n\nThe Warchief is ready for you inside your Town Hall. It would be wise not to keep him waiting...", objectives = "" }
WordHunterWoW_QuestEN[38568] = { title = "We Need a Shipwright", description = "Whatever be left of da Iron Horde be fallin' back ta Tanaan Jungle, where Gul'dan is turnin' them into sumthun' even worse. A frontal assault be suicide.\n\nBut da seas be open. If we attack by both land an' sea, Gul'dan got ta fall back somewhere. {name}, it be time ta build a shipyard!\n\nWe need local resources. Go to da Iron Docks. Gazlowe's boys are already there. Gather any equipment ya find, and see if ya can recruit us a proper Horde Shipwright!", objectives = "" }
WordHunterWoW_QuestEN[38570] = { title = "Derailment", description = "Some orcs have spoken out against Gul'dan, and they've been taken prisoner. One of them is what you'd call an engineering prodigy: Solog Roark, \"The Iron Shipwright.\" This guy's good. Designed all these docks, as well as the big dreadnaughts you fought around Shattrath.\n\nIf my scouts are right, he's in a prison train as we speak... And I betcha he'd be willing to defect!\n\nGather up some explosives and meet Durotan next to the train to the south.", objectives = "" }
WordHunterWoW_QuestEN[38571] = { title = "The Train Gang", description = "My warriors will surround and cover the train car. Hit the detonator to blow open the doors.\n\nI will speak to Roark and convince him to defect to our cause. He built all of this - he's our best hope for building a shipyard of our own.\n\nIf this doesn't work, execute him on the spot. The last thing we need is someone rebuilding the Iron Fleet.", objectives = "" }
WordHunterWoW_QuestEN[38572] = { title = "Hook, Line, and... Sink Him!", description = "I can build you a shipyard. And not some wasteful piece of over-engineering like this place.\n\nBut I'm going to need my blueprints. My work was confiscated when Gul'dan turned this harbor over to Admiral Knar.\n\n<Roark spits.>\n\nGul'dan's green poison courses through Knar's veins. He's calling the shots from on high. We'll need to grapple up there to take him out.", objectives = "" }
WordHunterWoW_QuestEN[38573] = { title = "Nothing Remains", description = "Nothing is left for me here. My old clanmates have turned into foes, and Gul'dan is desecrating what remains of my people.\n\nYou and your Frostwolf allies still have some fight left. If you pledge to depose Gul'dan, I will stand by your side. I will go to this garrison of yours and together we will build a shipyard that will rule the red seas of Draenor!\n\nLet your people know I am coming.", objectives = "" }
WordHunterWoW_QuestEN[38574] = { title = "All Hands on Deck", description = "Let's put dis \"Iron Shipwright\" ta work, commander. If we ta take Tanaan from both land an' sea, we gonna need a shipyard. Work wit' Roark an' make it happen!\n\nHe be surveyin' tha land along tha road west of Frostwall.", objectives = "" }
WordHunterWoW_QuestEN[38576] = { title = "We Meet at Light's Hope", description = "With you on our side, I know the Legion will fall! But before we march on the Broken Isles, we must put Highlord Tirion to rest.\n\nThere is but one place suitable for a paladin of his caliber... Light's Hope Sanctum, a secret bastion of the Light hidden beneath our chapel.\n\nPaladins the world over are on their way to the ceremony. I know Tirion would want you there most of all.", objectives = "" }
WordHunterWoW_QuestEN[38577] = { title = "The Battle for the West", description = "Our base is barely built and already the Iron Horde sets up defenses against us. Still the plan worked and we fight on two fronts.\n\nI have received word that Durotan has finally breached the western gates as well, but is bogged down in a pitched battle. You should go see the situation for yourself.", objectives = "" }
WordHunterWoW_QuestEN[38578] = { title = "A Message of Terrible Import", description = "Your scout... he got me out of that hellish place. Fel orcs surprised us out in the jungle and dragged us up the mountain. They tortured us... killed all but me. I fear one of us may have given up our secret before the end.\n\nI must ask you to go to the home of our order. Speak with Lagar, my leader, tell him... tell him Gul'dan knows.", objectives = "" }
WordHunterWoW_QuestEN[38581] = { title = "The Battle for the West", description = "Our base is barely built and already the Iron Horde sets up defenses against us. Still the plan worked and we fight on two fronts.\n\nI have received word that Exarch Maladaar has finally breached the western gates as well, but is bogged down in a pitched battle. You should go see the situation for yourself.", objectives = "" }
WordHunterWoW_QuestEN[38582] = { title = "To Old Friends", description = "I sense a powerful dark presence here, {name}, but it is not of Xavius. This feels too familiar.\n\nI sense a druid's touch here, a druid twisted by the shadow of the Nightmare.\n\nWe must deal with this threat if we are to find Xavius. I will take to the skies and lend you my aid.\n\nFind this corrupted druid and cut down his tainted and twisted plants.", objectives = "" }
WordHunterWoW_QuestEN[38585] = { title = "Assault on the Throne of Kil'jaeden", description = "The Shadow Council are summoning their demonic masters upon a mountain they are calling the Throne of Kil'jaeden. Make no mistake; This is the most dangerous region in Tanaan.\n\nGather together a war party and assault the Throne of Kil'jaeden before the Legion gains a foothold here!", objectives = "" }
WordHunterWoW_QuestEN[38586] = { title = "Assault on the Throne of Kil'jaeden", description = "The Shadow Council are summoning their demonic masters upon a mountain they are calling the Throne of Kil'jaeden. Make no mistake; This is the most dangerous region in Tanaan.\n\nGather together a war party and assault the Throne of Kil'jaeden before the Legion gains a foothold here!", objectives = "" }
WordHunterWoW_QuestEN[38595] = { title = "Malfurion's Fury", description = "The loss of Cenarius to the nightmare is a devastating blow to us all.\n\nThough Malfurion's rage is justified, his hatred of Xavius has burned for centuries and I fear that his blind rage will be used as a weapon against him.\n\nMay Elune guide us in our search for him, lest we have yet another friend to mourn today.", objectives = "" }
WordHunterWoW_QuestEN[38598] = { title = "TEST: Craft Some Legplates", description = "The Highmountain tauren craft their legplates piece-by-piece, then assemble them all at the end.\n\nSeems pretty slow and unnecessarily arduous if you ask me, but we should start here before making any efficiency improvements.\n\nHere's some leystone. I've added the recipe into your workbook, as well. Let's give this a shot!", objectives = "" }
WordHunterWoW_QuestEN[38599] = { title = "Infrastructure Improvements", description = "Sir, we built a vehicle to take ya up to the Throne of Kil'jaeden but whenever we try a test flight the navigation system goes crazy!\n\nIn my expert opinion it's 'cause of that crazy demon magic the Iron Horde is playing around with up there.\n\nIf you could travel up there and place these telemetry beacons we can program the vehicle and give you a stable flight all the way up.\n\nJust be sure to have some friends with you, the demons up there look especially vicious!", objectives = "" }
WordHunterWoW_QuestEN[38603] = { title = "Setting the Signal", description = "Sir, we built a vehicle to bypass the Horde camp and take you to the Throne of Kil'jaeden! There's one problem, the concentrated fel energy up there is causing the navigation system to go haywire!\n\nI'll need you to place some sensors along the edge of the summit. With them in place we can stabilize the flight controls.\n\nJust be sure to have some friends with you, the demons up there look especially vicious!", objectives = "" }
WordHunterWoW_QuestEN[38607] = { title = "Gates of Valhallas", description = "Escaping the grasp of Helya is no small feat. You may prove to be a worthy warrior after all.\n\nSkovald has entered Valhallas; you are running out of time. Legion has corrupted the minds of the Skovald's men. A battalion of unworthy vrykul is attempting to enter the portal to Valhallas.\n\nThe giants that protect the gates are fighting a losing battle. There is no end to Legion's onslaught.\n\nSpeak with the dragon, Vehdir, inside the gates near the portal. He will aid you on your next task.", objectives = "" }
WordHunterWoW_QuestEN[38611] = { title = "Will of the Thorignir", description = "In the summit of storms the dragons await. Born of the gods, they will test your will. \n\nThey roost above Hrydshal, where their children serve the Drekirjar. But they are no allies to man or vrykul, and so you must earn their blessing as they see fit.\n\nA friend of yours awaits in Hrydshal, no doubt searching for the answers you now possess. Go to her, and together, you will test your might against the storm!", objectives = "" }
WordHunterWoW_QuestEN[38612] = { title = "A Grapple a Day", description = "So some old magic vrykul is helping us out? I guess that's good, but this trial of yours might be tricky. You see, the only way up that mountain, is through those big walls.\n\nYou know, the ones with the mean-looking drakes on them.\n\nI scouted a bit, but couldn't get too far without those drakes trying to make lunch out of poor Duchess. The vrykul have them trained, which can't be good.\n\nI say we sneak in. I managed to snag a few grapple launchers earlier. Grab one and meet me outside the city walls.", objectives = "" }
WordHunterWoW_QuestEN[38613] = { title = "No Wings Required", description = "That thing looks like it's got the range to get us over the wall. There's a good spot to hook onto right past us - you should be able to spot it from here.\n\nOnce you're inside, do me a favor and see if you can distract the guards so I can slip through. I'll see what else I can find out about these vrykul.", objectives = "" }
WordHunterWoW_QuestEN[38614] = { title = "To Weather the Storm", description = "When I was scouting this place out, I noticed the vrykul here are no strangers to the treacherous mountain path we're trying to get to. They've got some specialized equipment they're using, and if I were you I'd try to get my hands on some.\n\nYou'll want to find some climbing treads to keep your grip and an oiled cloak to keep you dry. They've also got these stones they carry to keep the lightning at bay, so you'll want to pick one of those up as well.", objectives = "" }
WordHunterWoW_QuestEN[38615] = { title = "Impalement Insurance", description = "It looks like the elements aren't the only thing you'll need to worry about going up that path. Those harpoon launchers on the wall look pretty nasty, and unless we take them out first, they're likely to make short work of anyone trying to scale that path.\n\nThey're up on top of the walls, so you'll need to use that grapple launcher to get to them. Just try not to end up drake food!", objectives = "" }
WordHunterWoW_QuestEN[38616] = { title = "Built to Scale", description = "The vrykul around here seem to use scales from these drakes to fashion their armor. \n\nIf you were able to gather enough material from the local drakes, you may be able to make something useful out of it.", objectives = "" }
WordHunterWoW_QuestEN[38617] = { title = "Another Way", description = "Wait, do you still have that grapple launcher? I think you can still get to the path if you can launch from the top of that tower. The gap doesn't seem too bad there.\n\nOf course, we'll have to take out the big guy out front first. He looks tough, but I think we have a chance if we can flank him.", objectives = "" }
WordHunterWoW_QuestEN[38618] = { title = "Above the Winter Moonlight", description = "There, it looks like there's a good spot to launch to right across from here. This path should take you all the way to the top.\n\nAccording to my intel, your dragons should be up there. Let's just hope that they're still in a state to help you.", objectives = "" }
WordHunterWoW_QuestEN[38624] = { title = "Cry Thunder!", description = "You have proven yourself an ally of the Thorignir and we will lend you our strength. I would ask one last favor of our new champion, though. \n\nThe dragon who guided you to me awaits his vengeance against the vrykul. Together I wish for you to show these Drekirjar what it means to cross the Thorignir. Be they Felskorn or not, their malice has caused suffering to my brood. Their toll must be paid in blood.\n\nSpeak to Vethir when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[38641] = { title = "The Temple of Elune", description = "Cenarius is in danger.\n\nIf his condition is not reversed soon, he will be lost to the Nightmare that threatens the Emerald Dream. To spare him that fate, we must have the Tears of Elune - the same relic you were sent here to retrieve.\n\nElune's temple is not far. Go there. Find Lyanis. Show her my seal and instruct her to release the tears into your custody.\n\nHurry, {name}. Time is short.", objectives = "" }
WordHunterWoW_QuestEN[38643] = { title = "A Village in Peril", description = "The corpse of Darcy Heathrow lies before you pierced by several arrows and knife wounds.\n\nIn one hand she clutches a note, written with a feeble hand, that reads:\n\n\"The dead march on Bradensbrook.\n\nHelp us, please!\"", objectives = "" }
WordHunterWoW_QuestEN[38644] = { title = "The Farmsteads", description = "Forgive us, stranger. Mayor Heathrow has been under a lot of stress recently.\n\nI can't blame him: his own daughter, Penelope, has been missing for two days.\n\nIn fact, we could use information on several farmsteads to the south: Mayor Heathrow's house, Granny Marl's farm, and the Radcliffes' dock. Can you go check on the situation out there?\n\nHelp us, and perhaps the mayor's heart will soften.", objectives = "" }
WordHunterWoW_QuestEN[38645] = { title = "Children of the Night", description = "I am no enemy to these people, but there is no convincing them of that.\n\nTheir village has come under attack by some very old friends of mine. Friends who are no longer... living.\n\nThere's no telling who or what controls them, but in life these noble soldiers would never engage in such acts. That's a mystery for another time.\n\nFor now, help me earn the trust of these villagers. Strike down the Black Rook enemies who are terrorizing their citizens.", objectives = "" }
WordHunterWoW_QuestEN[38646] = { title = "A Sight For Sore Eyes", description = "Do you see those ravenous birds flying above my farm? Vicious creatures are spreading their filth an' eatin' my crops.\n\nI'd get rid of them with my trusty gun, but my eyesight's gone downhill.\n\nTake this flare gun and mark them for me.\n\nOnce I get my sights on them, I'll make 'em scatter.", objectives = "" }
WordHunterWoW_QuestEN[38647] = { title = "For the Corn!", description = "I've got a full summer's corn harvest just sittin' out in the field. I need some muscle to bring it in before the night elf raiders can destroy it.\n\nGet out there and bring me those crops, and I'll reward you handsomely.\n\nThe folks back in town need this food, and I sure as heck ain't eating rats for another winter.", objectives = "" }
WordHunterWoW_QuestEN[38648] = { title = "Black Rook Orders", description = "The letter is written in midnight ink:\n\n\"A demon invasion is imminent, but as long as the fires of Black Rook Hold blaze, we shall protect kaldorei lands. Kill any intruders who stand in our way.\"\n\n- K.R.\"\n\nPerhaps Jarod Shadowsong will want to see this.", objectives = "" }
WordHunterWoW_QuestEN[38649] = { title = "Silence in the City", description = "There is a troubling silence from Suramar City this day.\n\nOculeth just informed me that the teleporter to the Waning Crescent has gone dark. He is not able to reach Vanthir, nor am I.\n\nWhile I am hesitant to believe something dire has happened, I do feel this warrants investigation.\n\nSpeak with Oculeth and see if he can transport you to the Waning Crescent. We need to find out what happened.", objectives = "" }
WordHunterWoW_QuestEN[38655] = { title = "Root Cause", description = "The massive roots of Shaladrassil are spreading a horrible corruption throughout the forest.\n\nIf we are to save Val'sharah, we will need to find a way to stop the encroachment of the world tree.\n\nIf you bring me enough corrupted root samples, I may be able to discover their secrets.", objectives = "" }
WordHunterWoW_QuestEN[38656] = { title = "Mark of the Demon", description = "The demonic rune glows in your hand, emanating dark power. A single word, inscribed in demon tongue, glows coldly... \n\n...GRAVAX...", objectives = "" }
WordHunterWoW_QuestEN[38659] = { title = "Val'sharah", description = "We recently received word from that the druid Malfurion Stormrage has identified the location of the next Pillar of Creation - the Tears of Elune.\n\nMalfurion awaits your arrival in Dalaran as soon as you are able, Highlord.", objectives = "" }
WordHunterWoW_QuestEN[38662] = { title = "Tears for Fears", description = "The Tears of Elune are a sacred artifact, protected by my order for thousands of years. I tell you this so that you may understand the gravity of your request.\n\nThat said, Ysera is noble and wise and I trust in her guidance. You will find the tears in a vault at the eastern edge of the temple grounds.\n\nProceed with caution though, as that area has been overrun by demons.", objectives = "" }
WordHunterWoW_QuestEN[38663] = { title = "The Die is Cast", description = "Thanks to your efforts the temple is safe, for now.\n\nBut the Tears of Elune are stolen and Shaladrassil, the world tree that once protected this land, is now an instrument in the hands of our enemy. The Emerald Dream itself is being overrun by Nightmare.\n\nThe hearts of our people falter, their faith tested like never before. Return to Ysera with my report, {name}, such as it is.\n\nI shall plead with Elune with what time I have left here. May we somehow yet prevail.", objectives = "" }
WordHunterWoW_QuestEN[38669] = { title = "Our Last Hope", description = "The Vault has fallen to the Burning Legion.\n\nIt pains me to say it, but all is lost, but for one glimmer of hope... YOU. Believe me when I say, I did NOT want to have to do this. However, it would seem I have no choice.\n\nHelp me, demon hunter, and I will grant you your freedom.", objectives = "" }
WordHunterWoW_QuestEN[38671] = { title = "Lost in Retreat", description = "Is this the end?\n\nOur beloved Malfurion. I saw him in the Dreamer's clutches, but Ysera was... changed. Twisted.\n\nShaladrassil, our mighty world tree, is corrupted beyond recognition.\n\nWe were forced to flee our home without our belongings. Some were heirlooms, sacred to us. Return them to me if you can, {class}, I beg you.", objectives = "" }
WordHunterWoW_QuestEN[38672] = { title = "Breaking Out", description = "We cannot fight our way out of the Vault alone.\n\nTwo of your allies, Kayn Sunfury and Altruis the Sufferer, are imprisoned within this room. \n\nFree them with haste. Their strength will be of great use to us.", objectives = "" }
WordHunterWoW_QuestEN[38675] = { title = "Heart of the Nightmare", description = "I know only that my husband is somewhere deeper in this twisted forest.\n\nHe is still alive, but it remains to be seen if he is whole.\n\n<Tyrande's expression hardens into a scowl as she peers at you.>\n\nElune herself cannot protect Xavius if he is not.", objectives = "" }
WordHunterWoW_QuestEN[38684] = { title = "Reading the Leaves", description = "{name}, my friend. You must succeed where I have failed. You must find our dear Malfurion.\n\nAs the Nightmare consumes my thoughts, I hear the voices of these twisted trees. I must cling to sanity long enough to aid you.\n\nVenture into Ash'theran and bring me Corrupted Petals from the fallen denizens there.\n\nWith them, I might find your Archdruid while my mind is still my own.", objectives = "" }
WordHunterWoW_QuestEN[38687] = { title = "Close Enough to Touch", description = "He is near, {name}, I can feel it.\n\nWe must scour this place in search of my husband. I fear if we do not find him soon it will be too late.\n\nYou have been courageous throughout our search. I know you will not fail me now, {name}.\n\nThank you, and please hurry.", objectives = "" }
WordHunterWoW_QuestEN[38689] = { title = "Fel Infusion", description = "So many years of imprisonment has left us weak.\n\nThe Vault is overrun with demons.  Kill them and gather their souls to regain your strength.", objectives = "" }
WordHunterWoW_QuestEN[38690] = { title = "Rise of the Illidari", description = "Look down there. We are vastly outnumbered.\n\nWe will need more allies on our side if we are to escape from here intact. Free the other Illidari imprisoned within the cells of this chamber.\n\nWe will need everyone to escape this place alive.", objectives = "" }
WordHunterWoW_QuestEN[38691] = { title = "Jarod's Mission", description = "Since Maiev chased after Gul'dan at the Vault of the Wardens, her sisters among the Wardens have been searching far and wide for her whereabouts.\n\nWith so few Wardens remaining, I volunteered to join the search. I hope I will find sign of her within Black Rook Hold.\n\nThe fortress will be well guarded, and I will need help to break through. Help me find her, and I will reward you handsomely.", objectives = "" }
WordHunterWoW_QuestEN[38692] = { title = "Answering Aggression", description = "I weep for the Nightborne this day.\n\n<Silgryn gestures out the door.>\n\nElisande demonstrates the ultimate disdain for her people. So many lives... wasted!\n\nAll to relay a message: This is what happens to those who defy her.\n\n{name}, my friend, we must answer her. We must show her that she cannot slay her people without retribution.\n\nFight back, {name}.", objectives = "" }
WordHunterWoW_QuestEN[38694] = { title = "Regroup", description = "These people may be able to hold out here, but I know for certain that we cannot.\n\nEvery moment we spend here places them in danger of Elisande's forces retaliating against us.\n\nWe need to move. We need to find a place to regroup and recover.\n\nFollow me. I think I know how we can get out of here.", objectives = "" }
WordHunterWoW_QuestEN[38695] = { title = "Crackdown", description = "Thalyssra is right to be concerned!\n\nThe network has not responded to my attempts to re-establish connection with the Waning Crescent. I do not know what happened, but given the circumstances I believe it prudent to investigate in person.\n\n{name}, would you do the honors? I will send you as close to the Waning Crescent as I can.", objectives = "" }
WordHunterWoW_QuestEN[38697] = { title = "The Sword of Truth", description = "Lord Ravencrest's army rises from the dead, but I believe they are controlled by Gul'dan's will.\n\nTake this - Lord Ravencrest's blade, Fal'shathil. It was known for a unique, magical quality. Those who gazed upon its mirrored blade found themselves unable to deny the truth.\n\nTake the blade and plant it in the ground. Attack the night elven ghosts near its light. Once they are weakened in its presence, perhaps they will regain their senses.", objectives = "" }
WordHunterWoW_QuestEN[38710] = { title = "An Urgent Gathering", description = "A critical decision must be made, {name}.\n\nThe Legion devastated our forces at the Broken Shore. The mightiest army this world has ever known was reduced to cinders in moments.\n\nWe must gather those with the conviction to save our home. Travard of Tyr's Guard and Orik Trueheart have each made plans to do just that, but we must not let them walk alone.\n\nI ask that you seek them out and guide them to Krasus' Landing so that we may make this decision together.", objectives = "" }
WordHunterWoW_QuestEN[38714] = { title = "Maiev's Trail", description = "The fortress grounds are just up ahead. There is a large area to search, but if we split up, I believe we can cover a lot of ground.\n\nSearch the prison cages, the forge, and the guard tower for any signs of Maiev. I will check the upper ramparts and meet you on the other side of the keep.", objectives = "" }
WordHunterWoW_QuestEN[38715] = { title = "The Rook's Guard", description = "Black Rook Hold is not the same place I knew. Its walls have crumbled, a ghostly echo of its former glory.\n\nIf Lord Ravencrest has returned, then surely he will have his former officers at his side.\n\nKester Farseeker, captain of the guard.\n\nTrelan Shieldbreaker, peerless master of maces.\n\nStarlys Strongbow, who could split arrows while blindfolded.\n\nIf we stand any chance of entering the tower itself, they must be eliminated.", objectives = "" }
WordHunterWoW_QuestEN[38717] = { title = "Black Rook Prison", description = "I did not come this far to lose her in the final moments.\n\nMaiev must be in the cells beneath Black Rook Hold.\n\nI scouted above, and the entrance to the prison is guarded by a fearsome jailor.\n\nI will sneak past and take out the guards inside. Defeat Araxxas, take the keys, and then meet me within.", objectives = "" }
WordHunterWoW_QuestEN[38718] = { title = "Kur'talos Ravencrest", description = "Lord Ravencrest was a fearless leader, a seasoned commander, a man of integrity and honor, a teacher, and a protector of his people.\n\nMalfurion, Illidan, Tyrande, and I... we were still young when he helped shape our destinies.\n\nThe sigil of his house was legendary. Observe, for a moment, the sigil over his former resting place and I shall tell you more of his legacy.", objectives = "" }
WordHunterWoW_QuestEN[38719] = { title = "Illidari Freedom", description = "<The Illidari demon hunter is bleeding from several ghastly wounds. It appears he was left here to die.>\n\nWithin the prison are three of my... <cough>... comrades.\n\nWe were taken by surprise while scouting the area.\n\nI am not long for this world, but please, save them.", objectives = "" }
WordHunterWoW_QuestEN[38720] = { title = "No Reason to Stay", description = "Elisande's purge of the Waning Crescent came so swiftly that few could react. Many of my people are dead or taken.\n\nSome may have endured this atrocity. We need to make sure they are not left behind.\n\nI need you to search the houses nearby for any survivors. See that they flee before they are discovered. Reassure them that there is no reason to stay. \n\nNot here, not while Elisande's insanity reigns.", objectives = "" }
WordHunterWoW_QuestEN[38721] = { title = "Lieutenant of the Tower", description = "All of your instincts were correct. Gul'dan raised Lord Ravencrest, and his ghostly army, from beyond the grave. Now, they serve the Legion, protecting secrets within the tower.\n\nAlthough Ravencrest commands from above, Lieutenant Desdel Stareye operates the prisons.\n\nHe tormented me these past few moons, but I did not yield.\n\n<Maiev runs a finger along her curved blade.>\n\nHis life must be ended.", objectives = "" }
WordHunterWoW_QuestEN[38723] = { title = "Stop Gul'dan!", description = "After his defeat at the Black Temple, we brought Illidan's lifeless body here, to be interred forever within the Vault of the Wardens.\n\nGul'dan has found his way through our defenses and is trying to steal the Betrayer's corpse.\n\nEven in death, Illidan's body can be used by the Burning Legion. Gul'dan CANNOT succeed.", objectives = "" }
WordHunterWoW_QuestEN[38724] = { title = "Brotherly Love", description = "Maiev will be somewhere in the prison. I found her discarded armor on my way here.\n\nLet's split up to search the cells more quickly.\n\nWe must find her.", objectives = "" }
WordHunterWoW_QuestEN[38725] = { title = "Into the Foul Creche", description = "One of the demons that I interrogated revealed a particularly juicy bit of information. Apparently, there's an imp mother in the volcano that scribes Legion secrets.\n\nKor'vas has gone out to find that demon and bring those secrets back for us.", objectives = "" }
WordHunterWoW_QuestEN[38727] = { title = "Stop the Bombardment", description = "Jace's wards are not going to hold out much longer. We need someone to go out there and make sure those Legion devastators are destroyed.\n\n<Kayn pointedly looks at you with his spectrally-enhanced vision.>", objectives = "" }
WordHunterWoW_QuestEN[38728] = { title = "The Keystone", description = "{name}, Brood Queen Tyranna is just ahead in the command chamber. The others already charged in. She has the Sargerite Keystone in her possession.\n\nFinally, the object of all our sacrifice is at hand.", objectives = "" }
WordHunterWoW_QuestEN[38729] = { title = "Return to the Black Temple", description = "Quickly, {name}, use the Sargerite Keystone.\n\nWe must get back to the Black Temple before it is too late!", objectives = "" }
WordHunterWoW_QuestEN[38743] = { title = "The Fate of Val'sharah", description = "Malfurion, my love.... My heart breaks for him, but I cannot follow where he goes.\n\nI have sworn myself to Elune, my goddess, to defend her temples and lands with all that I am. I cannot stand by while my order is in danger.\n\nMay she keep you in her graces, Malfurion.\n\n<Tyrande turns away, eyes glistening with tears.>", objectives = "" }
WordHunterWoW_QuestEN[38753] = { title = "The Demon's Trail", description = "Malfurion is nearby. I can sense him.\n\nSearch the summit of Andu'talah while I continue to scour the forest.\n\nBe swift, {name}. Time is of the essence!", objectives = "" }
WordHunterWoW_QuestEN[38759] = { title = "Set Them Free", description = "Cyana went down to the Molten Shore. She was going to help some of the demon hunters who came in through the gateway ahead of us. Instead, she got herself into trouble.\n\nThis inquisitor revealed they're being held prisoner by some new type of demon called a 'jailer'. The thing sucks the souls out of its victims. I doubt they can hold out much longer.", objectives = "" }
WordHunterWoW_QuestEN[38765] = { title = "Enter the Illidari: Shivarra", description = "Our Shivarra demonesses are waiting at the Black Temple. It's a gamble bringing them here... they used to be part of the Burning Legion after all. But, they are some of the most powerful in Lord Illidan's arsenal.\n\n<Jace looks at you for a long moment.>\n\nI have a feeling that the ultimate sacrifice is going to have to be made in order to summon them in.", objectives = "" }
WordHunterWoW_QuestEN[38766] = { title = "Before We're Overrun", description = "The doomguard commander and his queen must be dealt with. His eredar are summoning in a huge number of reinforcements.\n\nWe need to put an end to him before the Legion overruns our new foothold up in the volcano!\n\nAs an added benefit, you can steal his demonic power.", objectives = "" }
WordHunterWoW_QuestEN[38777] = { title = "Leystone Deposit Sample", description = "This ore looks like nothing you've seen before.\n\nA mystical sheen moves through the metal in complex, unpredictable patterns. Your trainer in Dalaran would certainly like to see this.", objectives = "" }
WordHunterWoW_QuestEN[38778] = { title = "Turn the Keys", description = "My roots wither... my branches die...\n\nThe Bonespeakers, they seek to silence the Runewood.  The runestones are the key...\n\nTurn the stones... release my bonds...", objectives = "" }
WordHunterWoW_QuestEN[38784] = { title = "Leystone Seam Sample", description = "This ore has clearly absorbed some of the latent ley energies within the Broken Isles. It is cool to the touch, and reflects light in odd, playful angles.\n\nYour trainer in Dalaran should analyze this.", objectives = "" }
WordHunterWoW_QuestEN[38785] = { title = "Living Leystone Sample", description = "This is no normal leystone. It is much livelier, shimmering in complex, enthralling patterns. It is easy to stare at.\n\nYour trainer in Dalaran would certainly like to have a look at this.", objectives = "" }
WordHunterWoW_QuestEN[38786] = { title = "Where Respect is Due", description = "Leystone is a sensitive ore. Our smiths can coax great power out of it, but as miners, we must treat it with respect, or else its power will retreat inward.\n\n<The tauren hands you what appears to be a GLASS mining pick.>\n\nThe next time you mine some leystone ore, use this pick. It will break if you strike too hard. THIS is the respect that leystone requires.", objectives = "" }
WordHunterWoW_QuestEN[38787] = { title = "The Legend of Rethu Ironhorn", description = "A long, long time ago, a tauren by the name of Rethu entered this land. His exploits paved the road that all miners walk.\n\nIf you wish to learn more about mining, you must first learn about Rethu.", objectives = "" }
WordHunterWoW_QuestEN[38789] = { title = "Rethu's Journal", description = "Tucked in between a few pieces of rubble, a scrap of paper catches your eye.\n\nMining carefully, you uncover the tattered remains of an old scroll. The tauren handwriting is archaic, but one word catches your eye:\n\n\"Rethu\".", objectives = "" }
WordHunterWoW_QuestEN[38790] = { title = "Rethu's Pick", description = "This seam has been mined before - it bears the telltale diagonal ruts of a miner's pick.\n\nLooking down, that pick now lays on the ground - handle broken, pick-point dulled with use and years.\n\nCarved into the haft is a familiar name:\n\n\"Rethu\"", objectives = "" }
WordHunterWoW_QuestEN[38791] = { title = "Rethu's Horn", description = "The corpse of the rocky beast yielded an unusual treasure: a battered chunk of tauren's horn.\n\nIt is clearly very, very old, but something about its color and curve reminds you of Ronos Ironhorn at the Ironhorn Enclave.", objectives = "" }
WordHunterWoW_QuestEN[38792] = { title = "Rethu's Lesson", description = "You... miner... let me see your pick a moment.\n\n<The tauren spirit eyes your mining equipment.>\n\nYou remind me of myself, when I once walked this land. Savor these moments, miner. They cannot last forever.\n\n<With a bow, the spirit disappears.>", objectives = "" }
WordHunterWoW_QuestEN[38793] = { title = "Rethu's Experience", description = "Miner... you... you know who I am?\n\nI see. That is good. My tribe continues to honor its roots.\n\nIf you return to the land of the Ironhorn tribe... let them know that they are looked upon with pride.", objectives = "" }
WordHunterWoW_QuestEN[38794] = { title = "Rethu's Sacrifice", description = "Miner... speak with me a moment. I haven't much time in this place.\n\nI see you fight for your ore. I believe that is the most noble way to obtain your stone. It gives the land a fighting chance.\n\nStill, one mustn't be callous with their own life. Dig too deep, and the land will overcome you. No stone is worth the price I paid.\n\nBut that is a tale for another day...", objectives = "" }
WordHunterWoW_QuestEN[38795] = { title = "Felslate Deposit Sample", description = "This is one nasty-looking stone.\n\nYour trainer in Dalaran should see this.", objectives = "" }
WordHunterWoW_QuestEN[38796] = { title = "Felslate Seam Sample", description = "This ore is remarkably heavy. More disturbingly, it seems to darken and hiss at your touch.\n\nPerhaps your mining trainer in Dalaran has some insights.", objectives = "" }
WordHunterWoW_QuestEN[38797] = { title = "Living Felslate Sample", description = "Your miner's instinct is kicking in. Chunks of the infernal's corpse appear to be usable.\n\nStill, there must be a way to extract more ore from the demon's body. Perhaps your mining trainer in Dalaran will know how.", objectives = "" }
WordHunterWoW_QuestEN[38798] = { title = "A Shred of Your Humanity", description = "To mine for felslate is to seek the very blood of demons. To improve at it, you must become part demon yourself.\n\nWhy the dirty look? You said it yourself: you're willing to make sacrifices.\n\nLuckily for you, I'm an expert in this area. I won't put you in any danger, as long as you trust me.\n\nAre you ready?", objectives = "" }
WordHunterWoW_QuestEN[38799] = { title = "Darkheart Thicket: Nal'ryssa's Sisters", description = "I was not the only miner in my family. I was the youngest of four sisters.\n\nI say \"was\" because the other three are gone.\n\nTwo of them went too far. They overloaded their bodies with felslate and succumbed to the will of Sargeras. They are more demon than elf, now.\n\nThe third, I have not heard from in quite some time. The last I heard, she was investigating the Darkheart Thicket.\n\nI fear she may have fallen, too - one way or the other.", objectives = "" }
WordHunterWoW_QuestEN[38800] = { title = "Rin'thissa's Eye", description = "Oddly enveloped within the felslate deposit is a humanoid eye.\n\nIt quivers with life. You get the sense that it would blink at you if it had an eyelid.\n\nA mining expert should take a look at this.", objectives = "" }
WordHunterWoW_QuestEN[38801] = { title = "Lyrelle's Right Arm", description = "You blink and rub your eyes, but they do not deceive you. This is a woman's arm, completely enveloped within a felslate seam.\n\nThe arm is bloodless, but still twitches. Fel-colored streaks remain where veins once were.\n\nFelsmith Nal'ryssa will certainly want to see this.", objectives = "" }
WordHunterWoW_QuestEN[38802] = { title = "Ondri's Still-Beating Heart", description = "What at first looked like another chunk of felslate is, in fact, a humanoid heart, encrusted in rock and filled not with blood but a vile, demonic substance.\n\nIt does not appear to belong to the beast you carved it out of... it seems that the infernal was holding it like a keepsake. Luckily your mining pick didn't hit it straight on.\n\nFelsmith Nal'ryssa will want to see this.", objectives = "" }
WordHunterWoW_QuestEN[38803] = { title = "Rin'thissa", description = "My sister Nal'ryssa has her claws in you, doesn't she?\n\nThat weakling doesn't know the first thing about mining. She was always too afraid to take the leap. True knowledge comes only from the Great One, the God of Fel and Flame.\n\nYou want to truly learn how to mine? Come to Suramar's northwestern corner, and speak my name:\n\nRin'thissa.", objectives = "" }
WordHunterWoW_QuestEN[38804] = { title = "Lyrelle", description = "Look at you, miner. Still held back by the limitations of your fragile, decaying flesh.\n\nTo truly become one with the demon-tinged rocks of these lands, you must shed your skin and submit to a darker power.\n\nJoin us, miner. Bring your feeble body to Felsoul Hold, and speak my name:\n\nLyrelle.", objectives = "" }
WordHunterWoW_QuestEN[38805] = { title = "Ondri", description = "You are nothing compared to me. You think yourself hardened, experienced... heroic, even. Hah!\n\nYou have no idea what I've been through. The tortures I've endured, the sacrifices I've made. All for the sake of my trade!\n\nYes, I'm a miner, just like you. Want to learn what I have to teach? Come to the Crimson Thicket in Suramar, and speak my name:\n\nOndri.", objectives = "" }
WordHunterWoW_QuestEN[38806] = { title = "Infernal Brimstone Sample", description = "This ore. Smells. Horrible. It combines the odor of sulfur with all the worst parts of a rotting corpse.\n\nSomeone will probably want it for something.\n\nMaybe your mining trainer in Dalaran will take it off of your hands.", objectives = "" }
WordHunterWoW_QuestEN[38807] = { title = "Infernal Brimstone Analysis", description = "In order to mine Infernal Brimstone, we first need to understand the way in which ore comes into being. I currently have three of my apprentices doing research on different ores around the world.\n\nFind Forinn Stoneheart in Deepholm, Rhol Landers in Twilight Highlands and Krul Rockhorn in Icecrown and collect any information they've gathered on the ore at those locations.", objectives = "" }
WordHunterWoW_QuestEN[38808] = { title = "Bjornharta", description = "The afterlife leaves the dead hungry for the delicacies of their former lives. For the vrykul kings, none such offering is prized more than Bjornharta - a celebratory feast of an engorged bear heart. \n\nThe bears of the Runewood eat well, and have long been prized for their tender meat. Hunt them and find a suitable heart of offer to the ancient rulers. They will not be able to resist such an offering.", objectives = "" }
WordHunterWoW_QuestEN[38810] = { title = "The Dreaming Fungus", description = "So an outsider would seek to be judged by the ancient rulers of the vrykul? Curious, this. Know that they will not take to your presence kindly, stranger.\n\nIf you are so hasty to meet judgment, you can call them forth with a ritual of wakening. To complete this ritual, you will require an aromatic to burn and an offering to present.\n\nA plant grows in the Runewood that will make a suitable incense. Gather it, and I will instruct you further.", objectives = "" }
WordHunterWoW_QuestEN[38811] = { title = "Judgment Day", description = "You have proven resourceful thus far, stranger. As promised, I will instruct you on the ritual of wakening.\n\nFirst, you must place the offering directly atop the grave of the ruler you wish to awaken. Burn the incense so that its aroma wafts over the grave. If your offering is adequate, the ruler will rise, and you may ask your judgment.\n\nTake care, outsider. The dead vrykul kings will not enjoy being awakened from their slumber.", objectives = "" }
WordHunterWoW_QuestEN[38813] = { title = "Orders for Your Captains", description = "All that is left is to deliver your orders to our Illidari captains. The mightiest of the Legion's forces have arrayed themselves within the volcano. But, they will not remain on the defensive for long.\n\nWe must strike first and we must strike hard.\n\nOnce we destroy them, we can fly up to the command ship, defeat Brood Queen Tyranna, and take the keystone for our own. Lord Illidan will be pleased.", objectives = "" }
WordHunterWoW_QuestEN[38815] = { title = "Waking the Shieldmaiden", description = "With the rituals disrupted and her bones returned, we may be able to wrest Ashildir from the grasp of these Bonespeakers.\n\nDeeper within Haustvald, the mystics possess a special altar that can reunite the body and spirit of a fallen warrior. With this, we may be able to return Ashildir's spirit into her bones, and out of the grasp of these foul mystics.\n\nGo outsider, I will rally her guard.", objectives = "" }
WordHunterWoW_QuestEN[38816] = { title = "Breaking the Bonespeakers", description = "The crimes of these ritualists must not go unpunished, but we cannot be their executioners. The rune magic they practice grants them untold power over the dead.\n\nYou, however, are not dead, and I can sense great power from you. Take the fight to these heretics, and show Ashildir that you are truly worthy of her judgment!", objectives = "" }
WordHunterWoW_QuestEN[38817] = { title = "Regal Remains", description = "So you seek the judgment of the queen of the Valkyra? This must be your fault!\n\nThe Bonespeakers of Haustvald have committed an atrocity and stolen Ashildir's bones. They must have done this to keep an outsider from completing the trials. You must not let this stand!\n\nEnter Haustvald and retrieve her remains. I hope, for your sake, that Ashildir is in a forgiving mood.", objectives = "" }
WordHunterWoW_QuestEN[38818] = { title = "The Final Judgment", description = "In my fragmented state, I captured glimpses of a hero meting out justice to the corrupted mystics of Haustvald. I see now, this hero was you, {class}. \n\nI know you seek my judgment, but my spirit is still fragmented. As we speak,  Runeseer Faljar is calling upon dark, forbidden magics in an attempt to banish my spirit to Helheim. If he succeeds, your trial will be lost.\n\nMy connection here is fading. Go, there is little time!", objectives = "" }
WordHunterWoW_QuestEN[38819] = { title = "Their Numbers Are Legion", description = "Yes, those devastators must be silenced, but there's also a great deal more to be done.\n\nDespite the odds, we're counting on you. The Brood Queen's primary leaders are in control of the volcano. They must be killed. We must smash the Legion and do anything else necessary to achieve absolute victory.", objectives = "" }
WordHunterWoW_QuestEN[38823] = { title = "The Runes that Bind", description = "The stone tablet here describes a ritual where a powerful spirit can be broken into weaker pieces by binding them to special runestones. It looks like the Bonespeakers may be using this very ritual to weaken the spirit of Ashildir.\n\nIt may be impossible to summon her with her spirit so weakened. The rituals must be stopped.", objectives = "" }
WordHunterWoW_QuestEN[38833] = { title = "The Art of Demonsteel", description = "The Firmament Stone is one of the few anvils beneath the sky that can tolerate the hammer strikes necessary to craft demonsteel.\n\nHere, I will show you.\n\nTwo parts leystone, one part felslate. No heat, no tempering, just pure strength and finesse.\n\nTry it. I will coach you.", objectives = "" }
WordHunterWoW_QuestEN[38834] = { title = "Into the Fray", description = "The Burning Legion has beaten us here, but so too have the Illidari. It looks like the demon hunters are holding their own, but just barely.\n\nCome, let's put that weapon of yours to use. I'll figure out our next move while you crush the Legion.", objectives = "" }
WordHunterWoW_QuestEN[38839] = { title = "Done with Waiting", description = "Mom got a message and said blood called for blood. She told me to wait here while she went out, but it's been two weeks since then. I'm tired of waiting.\n\nI'll stay home if you go find her. She said she was going to the cliffs far to the south.", objectives = "" }
WordHunterWoW_QuestEN[38843] = { title = "Smashing Eggs", description = "I promised I'd stay home, but there were satyrs, and you were taking so long....\n\nI'm sorry. Please don't tell Mom.\n\nBut did you see? Those fish-people are breeding! You've got to do something!", objectives = "" }
WordHunterWoW_QuestEN[38849] = { title = "Burn Those Bodies", description = "Looks like some people fought the fish-people and lost. Now their bodies are just lying there, rotting. Gross!\n\nWe can't leave everybody like that. If you could burn a few of those corpses, I'd feel better. Here, take this torch.", objectives = "" }
WordHunterWoW_QuestEN[38851] = { title = "Thank You", description = "Could we talk for a second?\n\nMeet up somewhere, I mean? AWAY from my sister?", objectives = "" }
WordHunterWoW_QuestEN[38857] = { title = "A Favor for Mr. Shackle", description = "Throm'ka, {class}. My name is Seska. I represent a... trading company. As you can see, I've fallen victim to these giants and their naga allies.\n\nThree of my associates were also captured while surveying this cove. I'm certain that my employer, Mr. Shackle, would be most grateful if you could procure their release.", objectives = "" }
WordHunterWoW_QuestEN[38862] = { title = "Thieving Thistleleaf", description = "Why the Thistleleaf are collecting the Lunarwing eggs is anyone's guess, but you can be sure it's not to give them a loving home.\n\nSaylanna Riverbreeze will know what to do with these.", objectives = "" }
WordHunterWoW_QuestEN[38872] = { title = "The Dark Lady's Bidding", description = "Uh, are these guys friendlies? I guess it's a good sign they haven't tried to eat Duchess... yet.\n\nAnyway, I have orders. Nathanos caught up with the dark rangers, who were sent forward aboard the Oblivion on a secret mission from Lady Sylvanas herself! Unfortunately the Alliance caught wind of our plan, and now Greymane is attacking the outpost!\n\nWe could really use you over there, {name}. Duchess can take you there, just give me the word.", objectives = "" }
WordHunterWoW_QuestEN[38873] = { title = "Clear the Deck!", description = "Our mission in Skold-Ashil will have to wait, {class} - for now, we have more pressing matters to attend to.\n\nI had just recently arrived with reinforcements for our assault when Greymane's ship sailed in and began barraging our walls. We deployed our siege weapons, but their ground forces quickly overwhelmed us.\n\nIf you can get to those catapults and take out the dogs manning the cannons, it may give us the window we need to push the attack!", objectives = "" }
WordHunterWoW_QuestEN[38878] = { title = "Shielded Secrets", description = "Our goal lies within that vault, {class}. I don't have time to explain in detail - just know that it is vital to the Forsaken that we succeed.\n\nThe shieldmaidens have proven tenacious in their defense, but I believe there may be another way in. A chosen few of their order are allowed entrance, and I need you to find out how.\n\nIn the town I have seen intricately engraved shields which I believe are passed down from these champions. The scenes they depict may be the key to passing into the vault.", objectives = "" }
WordHunterWoW_QuestEN[38882] = { title = "A New Life for Undeath", description = "It seems that you are full of surprises, {name}. With the blessing of the Valkyra queen, you have opened a path that will shape the destiny of Azeroth.\n\nI invite you to bear witness, for today a new day dawns on the Forsaken!", objectives = "" }
WordHunterWoW_QuestEN[38888] = { title = "The Highmountain Tauren", description = "Ye've brought me a bit of interesting rocks to look at, {name}. I've got a special assignment for ye, if ye're up for it.\n\nI hear stories about these tauren, up in Highmountain, who claim mastery over minin'. I don't know if they're as talented as you or me, but they've been minin' leystone longer.\n\nPay 'em a visit. See what they have to say.", objectives = "" }
WordHunterWoW_QuestEN[38889] = { title = "Adopting the Adorable", description = "", objectives = "" }
WordHunterWoW_QuestEN[38901] = { title = "The Felsmiths", description = "Ye have a knack with this felslate, lad. Best ship ye off to someone who knows the stuff better than I.\n\nThe Illidari have a knack with all things demonic, really, and I've heard about a few miners who've set up shop out near the demons in Suramar.\n\nPay 'em a visit. See what they have to teach ye.", objectives = "" }
WordHunterWoW_QuestEN[38904] = { title = "Return to the Broken Shore", description = "Fear not, {name}. I'm angry, but I don't chase my own death.\n\nWe will fly in and scout the ideal point of attack. The demons are still drunk on their victory, but we will put a swift end to their revelry!\n\nTake my spare mount and we will fly to the Broken Shore. There we will bring honor to our dead.", objectives = "" }
WordHunterWoW_QuestEN[38907] = { title = "Keepers of the Hammer", description = "The Highmountain Tribes had intended to pledge our allegiance to your forces. We know war has come with the Burning Legion.\n\nHowever, we have been betrayed from within and must now ask for your aid.\n\nA great relic, the Hammer of Khaz'goroth, was stolen from our people by the vile drogbar.\n\nWe need your help in recovering it.", objectives = "" }
WordHunterWoW_QuestEN[38909] = { title = "Get to High Ground", description = "It is no accident that Dargrul attacked the Rivermane in force. It is their farms and their pastures that supply food for the region.\n\nPlease, get Jale to Thunder Totem. With luck, Mayla will have reinforcements to send to the area.\n\nWe will rally the survivors here and follow as quickly as we can.", objectives = "" }
WordHunterWoW_QuestEN[38910] = { title = "Rocs vs Eagles", description = "High Crawliac has taught her witches how to curse our beloved eagles into the vile rocs you see assaulting the valley.\n\nThere is no way to break this curse once it has taken hold.\n\nWe will take to the skies and do battle with the rocs, but we need your help on the ground.\n\nHead north through Darkfeather Valley and release any eagles that you find.\n\nEvery eagle you save is one less roc we must kill later.", objectives = "" }
WordHunterWoW_QuestEN[38911] = { title = "The Rivermane Tribe", description = "What has happened here requires more time than I have to explain. In short, our tribes have scattered in the wake of the attack that left the Hammer of Khaz'goroth in the hands of the barbaric drogbar.\n\nEven now the drogbar are raiding the Rivermane tribe, and I have too few braves left to send to their aid. \n\nWe need a hero. Please, go to Earthmother's Bounty and lend what aid you can.", objectives = "" }
WordHunterWoW_QuestEN[38912] = { title = "The Bloodtotem Tribe", description = "The Bloodtotem are led by Torok, a volatile but useful tauren chieftain. He is wary of outsiders, but I believe you have already met an emissary to their tribe--Oakin Ironbull--whom you rescued at Riverbend.\n\nUse that small thread and you may be able to bring the Bloodtotem back into the fold. Highmountain needs them if we are to defeat the drogbar and reclaim the Hammer of Khaz'goroth. Be on your guard, {name}.", objectives = "" }
WordHunterWoW_QuestEN[38913] = { title = "The Skyhorn Tribe", description = "The Skyhorn people are some of the greatest pathfinders and hunters this world has ever known.\n\nThey are a proud people, but should be willing to listen to reason.\n\nIf the roads feel unsafe, you may ask any flight master in Highmountain to fly you there.\n\nPlease, {name}, go to their leader Lasan and remind him that only together, we are Highmountain.", objectives = "" }
WordHunterWoW_QuestEN[38915] = { title = "Battle of Snowblind Mesa", description = "Your timing is fortunate. Our forces at Snowblind Mesa report seeing the Underking above ground.\n\nWhat is more, he is lightly guarded, and has the hammer with him. Thanks to your efforts, we can meet them in battle.\n\nMeet us at Snowblind Mesa and let us take the fight to Dargrul together.", objectives = "" }
WordHunterWoW_QuestEN[38916] = { title = "Secrets of Highmountain", description = "Mayla's father, Ulan, was our last high chieftain. He was slain trying to stop the Underking from seizing the Hammer of Khaz'goroth.\n\nI have watched Mayla all her life and can tell you she has both the courage and the strength to wear the mantle of High Chieftain.\n\nShe needs only our help to realize it herself.\n\nWill you meet us at the city entrance along the southern bluff? There is a ritual that might help, but we will need your aid to survive it.", objectives = "" }
WordHunterWoW_QuestEN[38922] = { title = "Littlefur", description = "Stranger, I beseech you! My once peaceful brethren are now cursed with insatiable wrath.\n\nMy nephew and I tried to leave against the Chieftain's wishes. The clan wrested him from me, and would have torn me apart if I did not flee.\n\nHe is trapped in the village, and I fear the worst.\n\nGreat {class}, please save him. I am too old and too weak to do it myself.", objectives = "" }
WordHunterWoW_QuestEN[38927] = { title = "Battle Hardened", description = "Defeat your opponents on the battlefield and you will be rewarded.", objectives = "" }
WordHunterWoW_QuestEN[38929] = { title = "Battle Hardened", description = "Defeat your opponents on the battlefield and you will be rewarded.", objectives = "" }
WordHunterWoW_QuestEN[38932] = { title = "Equipment Blueprint: Bilge Pump", description = "This appears to be a blueprint for some sort of naval equipment.  We should take it back to our Shipyard and see if someone can decipher it.", objectives = "" }
WordHunterWoW_QuestEN[38933] = { title = "Logistical Matters", description = "I think we are ready to... reintroduce ourselves to the Legion on the Broken Isles.\n\nLord Grayson Shadowbreaker has volunteered to help coordinate our forces on the ground. You should speak with him immediately, Highlord.", objectives = "" }
WordHunterWoW_QuestEN[38934] = { title = "Silas' Secret Stash", description = "A great Darkmoon prize do you now seek, but be ye warned, it is not for the meek.\n\nYour very first clue to send you on this caper, you will find printed on the back of this paper.", objectives = "" }
WordHunterWoW_QuestEN[38935] = { title = "His Name Was... Stormstout", description = "The land is ripe with rumors of an unusual pandaren monk whose power was matched only for his appetite for brew.\n\nHe was traveling with his young niece who's mouth seems to get them into a lot of trouble.\n\nThe locals say these two were headed to the Valley of the Four Winds. You should meet him! Just... watch out for that right hook.", objectives = "" }
WordHunterWoW_QuestEN[38936] = { title = "The Road to Kun-Lai", description = "Lorewalker Cho has sent word that several of your companions survived the conflict in the Jade Forest and have been moved to Kun-Lai Summit to seek healing.\n\nThey need your help if they are to survive!\n\nTo reach Kun-Lai Summit, travel to the Valley of the Four Winds and look for the Highroad Grummle that can be found at the base of the Veiled Stair along the northeastern border.\n\nThey can guide you the rest of the way.", objectives = "" }
WordHunterWoW_QuestEN[38944] = { title = "Sew It Begins", description = "Every time Dalaran takes us to a new shore, I get anxious over what types of fabric and cloth we might find below.\n\nThreads imbued with magic? Something demonically-tinged?\n\nUgh, I hope it's not FURS again.\n\nYou're an adventurer... and tailor to boot. Head on down there and see what you can scrounge up!", objectives = "" }
WordHunterWoW_QuestEN[38945] = { title = "This Should Be Simple... Right?", description = "I have plenty of silk patterns that we can put this cloth to work on.\n\nHelp me to prepare the materials, {name}. We're going to put this cloth to good use and make you a new robe.", objectives = "" }
WordHunterWoW_QuestEN[38946] = { title = "Consult the Locals", description = "Whoever wove this fabric CAN'T have intended it only for belts and shoulderpads. There must be some way to sew thread into this material.\n\nHead on down to Azsuna and try to find a tailor. We need to sew if we're going to do any real tailoring.", objectives = "" }
WordHunterWoW_QuestEN[38947] = { title = "Runic Catgut", description = "Let me guess... thread troubles? Mm-hm.\nI suspected as much. My people weave sumptuous silks, but those silks can be fickle about the types of thread they'll accept.\n\nShal'dorei silk has a bit of ley energy woven right into it. You need something that's learned to coexist with the ley energies of this land.\n\nI'm talking about owlcats, my good friend! They have what you need. You'll find them amongst the ruins of Llothien.", objectives = "" }
WordHunterWoW_QuestEN[38948] = { title = "Hard Times", description = "When I worked at the tailoring guild in Suramar, I would usually work off of a pattern. Something that inspired me.\n\nUnfortunately, I've run into streak of bad luck, and I'm ashamed to say that I no longer have my patterns.\n\nThe naga sorceresses in the lagoon to the west, however, have expertly-sewn wristwraps. And the nightfallen to the north wear robes that we can use... if you can pry one from their greedy clutches.", objectives = "" }
WordHunterWoW_QuestEN[38949] = { title = "So You Think You Can Sew", description = "Very good, I think we're ready to begin.\n\n<Lyndras steals a glance at your powerful weapon. A look of hunger washes over his face before he shakes it off and continues.>\n\nLet's prepare our materials and make the robe and bracers that you so rightfully deserve!", objectives = "" }
WordHunterWoW_QuestEN[38950] = { title = "The Wayward Tailor", description = "Might I ask a favor, {name}?\n\nAs I am recently without a home, shop, family, or friends, I was wondering if you might show me your floating city? I must admit, I am VERY curious about the place. I've also heard good things about their tailoring shop.\n\nI have no way of getting there myself, but certainly such a magical city has SOMEONE who can summon me.\n\n<Lyndras looks at you with hopeful apprehension.>", objectives = "" }
WordHunterWoW_QuestEN[38951] = { title = "A Needle Need", description = "This shop has almost everything we need. Unfortunately, the quality of your sewing needles is lacking.\n\nI do know where you can get better needles. The sprites of Val'sharah are covered with spines which, fortuitously, are perfect for the type of sewing we need.\n\nI hate to be such a prickler stickler, but these needles really will make a difference.", objectives = "" }
WordHunterWoW_QuestEN[38952] = { title = "Meticulous Precision", description = "The needles are sharp, but look at them closely. Some have a curve to them, others have a spur hanging off the side. Look at this one... it's got a ninety-degree crook in it! I have no desire to sew around a corner.\n\nTiffany Cartier in the jewelcrafting shop has a good eye for this sort of thing. Bring these needles to her, and she'll straighten them out.", objectives = "" }
WordHunterWoW_QuestEN[38953] = { title = "Advanced Needlework", description = "You've already learned the patterns for bracers, belts, epaulets, and of course, robes. Unfortunately, your technique was wasteful... you need a better method.\n\nThat's where our needles come in.\n\nHere, I'll show you how to improve the process of these patterns.", objectives = "" }
WordHunterWoW_QuestEN[38954] = { title = "Where's Lyndras?", description = "That's strange. Lyndras was here one moment, and then he ran off the next. He had such a strange look on his face.\n\nPerhaps we should track him down.", objectives = "" }
WordHunterWoW_QuestEN[38955] = { title = "Sew Far, Sew Good", description = "Your tailoring skill really is impressive and, although I don't have my patterns with me, I do have some patterns memorized. One of those patterns is for a simple bag.\n\nFollow my lead, {name}.", objectives = "" }
WordHunterWoW_QuestEN[38956] = { title = "Where's Lyndras Again?", description = "Oh dear.\n\nHe had just promised you that he wouldn't wander off, and then he did it again!\n\nI'm starting to think that this Lyndras character might be a bit too impetuous for my tastes.\n\nPlease, go find him, before he gets into any more trouble.", objectives = "" }
WordHunterWoW_QuestEN[38957] = { title = "Taking Inspiration", description = "I wish I had more patterns to share, but my notebook was lost along with my shop. We'll need to come up with some patterns on our own.\n\nI've been thinking about the leather breeches that the Stormheim vrykul wear. They're certainly much thicker and heavier than anything we could sew, but their embellishing runework is quite impressive.\n\nIf I had a few pairs, perhaps I could re-imagine this runework on a more... refined garment.", objectives = "" }
WordHunterWoW_QuestEN[38958] = { title = "The Right Color", description = "Your assistance, {name}, if you have a moment.\n\nI've been attempting to reproduce a pattern for footwear that I spotted a while back, but I'm having trouble getting the right color for my dye. Our black dye is too dark, our blue dye is too bright, and mixing the two doesn't look right.\n\nThe color I'm looking for is more of a squid-ink blue. If, in your travels, you come across any dyes of this color, would you do me the favor of bringing some to me?", objectives = "" }
WordHunterWoW_QuestEN[38959] = { title = "Left Behind", description = "I do truly want to help you work on your tailoring, but without my patterns or my supplies, there isn't much more I can do save for teaching you what little I remember.\n\nIf my memory still serves true, you're just missing a good pattern for some gloves and a hood.\n\nThe first thing I need you to do is grab a few things from where you first met me. Here's what I need...", objectives = "" }
WordHunterWoW_QuestEN[38960] = { title = "Lining Them Up", description = "Since you're heading to Azsuna, you may as well gather some lining for our projects.\n\nThe bears of Azsuna are known for how soft, yet durable their fur is.\n\nHunt them in the woods around Llothien and bring their fur back with you.", objectives = "" }
WordHunterWoW_QuestEN[38961] = { title = "Eye of Azshara: The Depraved Nightfallen", description = "In order to craft the gloves, we'll require a special item. This will be no easy task to recover it, {name}.\n\nThe naga of Azsuna are said to be hard at work trying to summon a terrible creature into this world.\n\nThe creature's heart holds immense energy that we can use to channel into the gloves, making them incredibly powerful.\n\nI need... I mean, we need that heart if we are to produce a suitable pair of gloves for someone of your presence.", objectives = "" }
WordHunterWoW_QuestEN[38962] = { title = "The Path to Suramar City", description = "I recall Lyndras mentioning a guild of tailors within Suramar City. Perhaps they could further our understanding of how to utilize this new cloth.\n\nUnfortunately from what I've heard, they've sided with the demons and anyone opposed to them is to be killed on sight.\n\nYou must find a way to move safely within the confines of their city if we're to continue our research.", objectives = "" }
WordHunterWoW_QuestEN[38963] = { title = "The Final Lesson?", description = "Now that we have everything we need, let's work on the hood.\n\nAfter we're finished, we'll move onto the gloves.", objectives = "" }
WordHunterWoW_QuestEN[38964] = { title = "Where's Lyndras Now?", description = "Lyndras couldn't have gone very far. I mean, we're floating a thousand feet over the sea. \n\nI heard some commotion across the way this morning near the alchemy shop. I pray that wasn't Lyndras.\n\nCould you please go over there and make sure?", objectives = "" }
WordHunterWoW_QuestEN[38965] = { title = "Assault on Violet Hold: Into the Hold", description = "With Lyndras being locked up in Violet Hold, you feel responsible for him and must discover the truth behind his actions.\n\nPerhaps if you were able to speak with him, you could find a way to have him released from the hold and put back into your custody.\n\nGo into Violet Hold and find out what happened to Lyndras.", objectives = "" }
WordHunterWoW_QuestEN[38966] = { title = "Secret Silkweaving Methods", description = "Okay, done mourning! Let's look through his stuff.\n\n<Tanithria takes a moment to leaf through Lyndras' journal. Her eyes open wide.>\n\nOur friend has been keeping secrets from us. Look at this! Every single one of the recipes he's taught us can be improved.\n\nLet's start simple, with some bracers. I can supply most of the materials, but you'll have to talk to Alard Schmied in the blacksmithing shop to get this powdered brimstone.", objectives = "" }
WordHunterWoW_QuestEN[38967] = { title = "The Nightborne Connection", description = "Now that you're able to disguise yourself, you should go to Suramar City and try to find this guild of tailors.\n\nGood luck, {name}, and try not to get caught.", objectives = "" }
WordHunterWoW_QuestEN[38968] = { title = "Proof of Loyalty", description = "<Tytallo listens as you recount what happened with Lyndras.>\n\nI see. You sound almost... sympathetic to the wretch.\n\nThe nightfallen are liars and thieves. ALL of them. Lyndras included.\n\nI will not tolerate a student that has any respect or sympathy for those... things. And have you witnessed what they turn into at the depths of their depravity?\n\nIf you want to get on my good side, do not return until you are covered in the blood of the withered.", objectives = "" }
WordHunterWoW_QuestEN[38969] = { title = "Master of Silkweave", description = "While Tytallo is busy exacting withered genocide, it falls on me to take care of the more mundane aspects of training.\n\nWe're going to need to see how talented you are.\n\nCraft an entire set of silkweave armor for me. Leyweaver Mithrogane can provide you with a proper mannequin for displaying it.", objectives = "" }
WordHunterWoW_QuestEN[38970] = { title = "The Queen's Grace Loom", description = "Great power comes only with sacrifice. Even the most masterful tailor can only do so much with silkweave. To improve your patterns any further, bargains must be made.\n\nYou are prepared, {name}, to learn about working with Imbued Silkweave.\n\nUse the teleportation crystal behind me, and speak with Azayna, the leader of our order.", objectives = "" }
WordHunterWoW_QuestEN[38971] = { title = "Exotic Textiles", description = "I'm risking my life and career to be here, tailor.\n\nI've been curious about demonic cloth, and my attempts to obtain some through approved means have been met with resistance.\n\nI simply must see this cloth for myself.\n\nI don't wish to disrupt Azayna's pact with the demons, but you - you can attack the demons without drawing attention to our guild.\n\nI'm particularly interested in a particular demon's set of robes. Bring me a scrap, and I'll teach you what I know.", objectives = "" }
WordHunterWoW_QuestEN[38974] = { title = "Halls of Valor: The Right Question", description = "One might ask what a leyweaver is doing standing over a dead vrykul's body. But such questions only stir up trouble.\n\nInstead let us ask what can be learned from those who have passed on. A question like that promotes progress.\n\nI assume you're here to learn from me, the pattern for Imbued Silkweave pants, yes?\n\nIf that's true, then I'll need something from one who has passed on. In the Halls of Valor the great guardian, Hymdall resides.\n\nBring me his loincloth and I will teach you my pattern.", objectives = "" }
WordHunterWoW_QuestEN[38975] = { title = "Inspire Me!", description = "I am, and always will be, a student of robemaking and dressmaking. You can keep your gloves, belts, and cloaks. Nothing beats a good robe.\n\nI'll share my pattern for an imbued silkweave robe with you if you can teach me some of the robe and dress patterns you've learned along your tailoring journey.", objectives = "" }
WordHunterWoW_QuestEN[38989] = { title = "Your Orders, General?", description = "General, your forces in Tanaan Jungle await your orders. Travel to the Planning Map there to issue your commands.\n\nFor the Horde!", objectives = "" }
WordHunterWoW_QuestEN[38990] = { title = "The Call of Icecrown", description = "<A powerful presence again touches your thoughts.>\n\nI have ordered your brethren to Icecrown to prepare for the coming conflict, but I have a more important fate in mind for you. You, {name}, will be the hand of our vengeance!\n\nUse the Death Gate to return to Acherus and I shall reveal your role in this.", objectives = "" }
WordHunterWoW_QuestEN[38996] = { title = "Your Orders, General?", description = "Exarch Yrel has sent word from Lion's Watch in Tanaan Jungle that your forces stand ready for their new orders.\n\nFor the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[39000] = { title = "We Don't Need No Library Card", description = "If history is any indication, Gul'dan is training a whole generation of warlocks to marshal against us. If we act fast, we can stem the tide and make things easier on ourselves.\n\nAs you and your fellow heroes venture into the depths of the Hellfire Citadel, seek out Tomes of Chaos from Gul'dan's lieutenants.\n\nThey're dangerous, so don't read any of them. Not even the pictures.\n\n<Khadgar shudders.>\n\nESPECIALLY the pictures.", objectives = "" }
WordHunterWoW_QuestEN[39003] = { title = "Cooking the Books", description = "{name}, we've got to destroy these tomes. Many of them have actual tortured souls bound into the pages, so we can't just burn them. Cordana will know what to do.\n\nTake these books to my tower in Zangarra and give them to Cordana. Let me know when the deed is done.", objectives = "" }
WordHunterWoW_QuestEN[39004] = { title = "Darkness Incarnate", description = "We have one final task before us, {name}. We must defeat Gul'dan and unravel his plans for this world.\n\nI have no reward to offer you - I have given you everything I can.\n\nCome. When you and your allies are ready, we march on Hellfire Citadel... and end this.", objectives = "" }
WordHunterWoW_QuestEN[39011] = { title = "Black Rook Invasion", description = "Once, this area was peaceful and prosperous. Then we saw the first bad omens: strange ailments, spoiled crops, and the like. Now ghosts attack us from that castle across the river, and undead assassins slay our fishers so as to cut off the village's food supply.\n\nWe're the last family living this close to the castle, but we daren't retreat: this river is the best route for fishers to bring their hauls in to town. Please, will you take the fight to these undead?", objectives = "" }
WordHunterWoW_QuestEN[39015] = { title = "Grumpy", description = "", objectives = "" }
WordHunterWoW_QuestEN[39018] = { title = "Call of the Archmage", description = "Archmage Khadgar has a very urgent favor to ask. He is gravely concerned about additional threats this world may hold for Azeroth, and he will need your assistance pursuing them. Please see him at his tower, east of Talador, in the Zangarra swamp.", objectives = "" }
WordHunterWoW_QuestEN[39019] = { title = "Call of the Archmage", description = "Archmage Khadgar has devised the next course of action against the Shadow Council. Please see him at his tower, east of Talador, in the Zangarra swamp.", objectives = "" }
WordHunterWoW_QuestEN[39022] = { title = "Call of the Archmage", description = "Archmage Khadgar has devised the next course of action against the Shadow Council. Please see him at his tower, east of Talador, in the Zangarra swamp.", objectives = "" }
WordHunterWoW_QuestEN[39023] = { title = "Call of the Archmage", description = "Archmage Khadgar has devised the next course of action against the Shadow Council. Please see him at his tower, east of Talador, in the Zangarra swamp.\n\nThis will not take long.", objectives = "" }
WordHunterWoW_QuestEN[39024] = { title = "Call of the Archmage", description = "Archmage Khadgar has devised the next course of action against the Shadow Council. Please see him at his tower, east of Talador, in the Zangarra swamp.\n\nThis will not take long.", objectives = "" }
WordHunterWoW_QuestEN[39025] = { title = "Grasp of the Underking", description = "If we have one good fortune in this it is that Dargrul has no knowledge of how to use the hammer.\n\nHe keeps thinking of the hammer as a weapon instead of a tool of creation.\n\nEven so, he has imprisoned our tribesman in fists of stone summoned from the earth. Our weapons have proven useless against this magic.\n\nYou might have power enough to break these fists. Can you help?", objectives = "" }
WordHunterWoW_QuestEN[39026] = { title = "The Drogbar", description = "It wasn't enough for Dargrul to just destroy this village. He has also sent his Stoneraiders to take what is left.\n\nPlease champion, prove to my people that you are the hero I foresaw.\n\nSlay enough of these Stoneraiders that it breaks their resolve.", objectives = "" }
WordHunterWoW_QuestEN[39027] = { title = "Dargrul and the Hammer", description = "We are about to follow a drogbar into a cave, something we warn our children never to do.\n\nEven so, several of our warbraves have already followed Dargrul inside.\n\nCome, join us in battle and let us reclaim the Hammer of Khaz'goroth.", objectives = "" }
WordHunterWoW_QuestEN[39032] = { title = "A Summons from Saylanna", description = "Sprites have always been mischievous creatures, but lately their mischief has turned to violence.\n\nOne of the druids I call friend, Saylanna Riverbreeze, reports that they are assaulting the faerie dragon nesting grounds.\n\nThe Lunarwing Shallows lie to the south. You will find Saylanna there.", objectives = "" }
WordHunterWoW_QuestEN[39033] = { title = "The Time to Strike", description = "This configuration of the stars causes an unusual vibration in the crystals strewn across Draenor, relics of the ancient Apexis. Some swear that the crystals will multiply when left unattended beneath the night sky, but none have seen the phenomenon firsthand. Regardless of the true cause, these crystals should be far more plentiful should you seek them out.", objectives = "" }
WordHunterWoW_QuestEN[39034] = { title = "Emissary of War", description = "When the sign of the emissary shines in the night sky, the stars strengthen existing bonds and forge new ones. Friendship is still not cheaply won, and deeds will prove loyalty, but trust comes more readily during these days. Venture deep into caverns and strongholds to prove your worth.", objectives = "" }
WordHunterWoW_QuestEN[39040] = { title = "A Call to Battle", description = "The favorite star of warlords and generals dominates the sky, offering good fortune to tacticians everywhere. Some say that the battle star hones the instincts of commanders to the point of near-prophecy. If ever you were going to test yourself on the field of battle, now is the time.", objectives = "" }
WordHunterWoW_QuestEN[39041] = { title = "The Arena Calls", description = "This alignment of the stars is a dire sign, stirring bloodlust and calling warriors to battle to the death in close quarters. Arena masters turn a tidy profit during these days, likely not understanding why their stands are overflowing. Amidst the excitement, great rewards do await those brave, or foolhardy, enough to venture into the arena....", objectives = "" }
WordHunterWoW_QuestEN[39042] = { title = "The Very Best", description = "This alignment of the stars is truly a strange one, causing the tiniest of creatures to gain unnatural aptitude. None of our sages can explain the phenomenon, but cunning tamers have much to gain, especially by testing their skills against those of their peers.", objectives = "" }
WordHunterWoW_QuestEN[39043] = { title = "Bitestone Enclave", description = "This is an old drogbar enclave that we used to trade with. Now it is a base of operations for their raids.\n\nI need more time to gather what is left of our warbraves. Go, enter the enclave, and slay any you find in there.\n\nBuy us the time we need to gather our strength.", objectives = "" }
WordHunterWoW_QuestEN[39047] = { title = "Call of the Illidari", description = "{name}, Altruis requests that you meet him at Krasus' Landing at once.\n\n<Kor'vas leans in close, her voice an urgent whisper.>\n\nYou must hurry. The Legion has eyes everywhere.", objectives = "" }
WordHunterWoW_QuestEN[39049] = { title = "Eye On the Prize", description = "This demon has proved less than useful. I have been using the Scythe of Souls on it, but so far, it has resisted my inquiries. We will see how long that lasts.\n\nI have a different idea...\n\nThere is a fresh inquisitor demon ahead. They are horrific fel casters who see through their floating eyes and specialize in dark pacts. If you steal its power, Jace Darkweaver could use some of it in his ritual to spy on the Legion.\n\nBetter yet, you will gain its power by ripping it from its smoking corpse.", objectives = "" }
WordHunterWoW_QuestEN[39050] = { title = "Meeting With the Queen", description = "We can use some of that essence to complete my ritual. You'll be able to spy upon the Legion leaders and see what they're planning.\n\nUse the nether crucible and complete the ritual.", objectives = "" }
WordHunterWoW_QuestEN[39051] = { title = "By Any Means", description = "We need to figure out what rock Varedis is hiding under - the only way we're going to do that is by getting inside this prison.\n\nDo what you must.", objectives = "" }
WordHunterWoW_QuestEN[39054] = { title = "Shipbuilding", description = "The first thing we need to start building ships is a blueprint. With your help, I grabbed some of the best ones from the Iron Docks before we broke out of there.\n\nLet's make sure these don't fall back into the hands of the Iron Horde. Memorize these blueprints, {class}, and then destroy the evidence. Let me know when you are done.", objectives = "" }
WordHunterWoW_QuestEN[39055] = { title = "Ship Shape", description = "Now that we have the blueprints, let's get started on our first ship, a transport!  Speak to me when you are ready to begin construction.", objectives = "" }
WordHunterWoW_QuestEN[39056] = { title = "Naval Commander", description = "We have come a long way in a short time on this shipyard, {name}.  Now it's time to run our first naval mission and control the seas of Draenor!\n\nI will need to setup shop from a high vantage point to plan out these seafaring missions.  Meet me near the shipyard entrance and we can get started.", objectives = "" }
WordHunterWoW_QuestEN[39057] = { title = "Command of the Seas", description = "Gul'dan wasted no time integrating his Shadow Council minions into every rank of the Iron Horde. The naval fleet that once owed loyalty only to Grommash is now his to command. If we want to fight back, we're going to need more than just a couple of transport ships. We must build an arsenal.\n\nWe need your expertise, commander. Upgrade your dockyards and create a fleet capable of dominating the seas!", objectives = "" }
WordHunterWoW_QuestEN[39058] = { title = "Critters of Draenor", description = "I love collecting pets, and I've picked up a few unusual pets here in Draenor.  What would you say to a battle?  If you can defeat my humble team, I think we'll both learn a few new tricks.", objectives = "" }
WordHunterWoW_QuestEN[39059] = { title = "To Catch a Banshee", description = "The strange-talking vrykul said I might be able to meet you here. I have orders from Greymane.  It seems he may have a lead on Sylvanas' location.\n\nHe's set up a camp near the base of the mountain. We've run into some troubles, though. It looks like the Horde may have homed in on our position.\n\nWe could use your help. You can take my gryphon. Just speak to me when you're ready to leave.", objectives = "" }
WordHunterWoW_QuestEN[39060] = { title = "Combustible Contagion", description = "It is true that we may have a lead on Sylvanas. Though I want nothing more than to get my hands on the Banshee Queen, the situation here at Greywatch requires immediate attention.\n\nYesterday, a regiment of guards returned with word of Forsaken forces in the woods. Several of them bore signs of a blight, similar to the one we endured in Gilneas. It would appear these Forsaken seek to unleash this blight upon Greywatch.\n\nSeek out their caches and destroy them, before the blight overtakes us!", objectives = "" }
WordHunterWoW_QuestEN[39061] = { title = "Whispers from the Dark", description = "We still have little knowledge of the Horde's activities in the region, but I'm hoping you can help change that.\n\nLately the woods have been crawling with Sylvanas' agents. The few we have taken out carried orders from her Dark Rangers, who are no doubt in command of her forces here.\n\nWhile you're on the hunt, keep an eye out for any scouting orders. They may help us pinpoint Sylvanas' objective in the area.", objectives = "" }
WordHunterWoW_QuestEN[39062] = { title = "To Skold-Ashil", description = "We have her now! According to these reports, Sylvanas' forces are after something in Skold-Ashil - a vrykul town not far from here. We must make our way there and track her down.\n\nI had previously dispatched Commander Lorna Crowley and a detachment of Gilneas Brigade to scout the position. Meet up with her there and find out what Sylvanas is after.\n\nMeanwhile, I will muster the fleet to assault their outpost. We will have justice if I have to reduce their camp to rubble!", objectives = "" }
WordHunterWoW_QuestEN[39063] = { title = "Shielded Secrets", description = "It's obvious at this point that the Horde wants something in Skold-Ashil. Unfortunately we still don't know what they're after.\n\nWe think the secret lies with the shieldmaidens here, so we need to find out more about them. Some early scouting revealed that they have a method of carving their shields to tell their stories. \n\nGo into the city and find as many of these shields as you can. With luck, we will find what Sylvanas seeks.", objectives = "" }
WordHunterWoW_QuestEN[39067] = { title = "Upgrading The Fleet", description = "You have been doing a great job out there commander.  However, we are going to need more experience and resources to upgrade this shipyard.  Once we reach our goals, we can upgrade the capacity of the shipyard to hold more ships!", objectives = "" }
WordHunterWoW_QuestEN[39068] = { title = "Naval Domination", description = "Our naval domination continues!\n\nHowever, we are going to need even more experience and resources to take this shipyard to the next level.  Once we reach our goals, we can upgrade the capacity of the shipyard to hold even more ships!", objectives = "" }
WordHunterWoW_QuestEN[39082] = { title = "Let's Get To Work", description = "Now that the shipyard is complete, we need to get busy making ships!  Solog ran off to the dry docks, why don't you meet him down there?  He said he had a plan.", objectives = "" }
WordHunterWoW_QuestEN[39092] = { title = "Becoming the Ascendant", description = "Our course is now clear. We must enter the vault and prevent Sylvanas from obtaining the power to create more Val'kyr. \n\nThe entrance is barred, which is likely what has kept her out so far, but you may have already uncovered the key to this barrier.\n\nYou must become the next ascendant.\n\nComplete the rites as depicted on the shields and take down the barrier to the vault. I will send word to Greymane of our findings - he will wish to confront Sylvanas himself.", objectives = "" }
WordHunterWoW_QuestEN[39107] = { title = "An Even Bigga Score", description = "So these mooks in Tanaan, they be carryin' all manner of valuable treasures. It still be complicated, but I can give ya a lot more now!", objectives = "" }
WordHunterWoW_QuestEN[39117] = { title = "Shriek No More", description = "Papa loved this village. He'd never hear of leaving, even in these dread times.\n\nBefore he died, he told me what attacked him: a monstrous falcon we call Rotbeak.\n\nYou're fighting these undead, aren't you? Will you avenge my father? If so, you can find the beast northwest of here, patrolling our western route to the sea.", objectives = "" }
WordHunterWoW_QuestEN[39122] = { title = "Ending the New Beginning", description = "The Banshee Queen is here! I'd recognize those tainted arrows anywhere.\n\nThis is the moment we have been fighting for. Sylvanas will answer for her crimes against Varian Wrynn and the Alliance!\n\nTo arms!", objectives = "" }
WordHunterWoW_QuestEN[39123] = { title = "Lion Stalkin'", description = "The hills are crawlin' with lions that stalk their prey from afar. These big cats will pounce at anything that catches their eye, including a {race}. \n\nWhile most would fall to such a formidable predator, anyone in my huntin' party would be able to best those beasts.\n\nProve you've got what it takes by taking down a few of those stalkers.", objectives = "" }
WordHunterWoW_QuestEN[39124] = { title = "Moose Shootin'", description = "Highmountain is home to wildlife that can't be hunted anywhere else in the world. Tell me, {name}, have you ever laid eyes on a moose before? \n\nThe roaming Elderhorn may look like gentle giants, but only a fool would underestimate their strength. \n\nThey should prove to be a good challenge, even for someone as experienced as you.", objectives = "" }
WordHunterWoW_QuestEN[39125] = { title = "Demon Destroyer", description = "The demons spreading this corruption must be dealt with. Kill their generals and their plans will unravel.\n\nI have a gift for you. This horn was given to me by Odyn himself, use it to strike down all that stand in your way.\n\nThe gods will surely smile upon you if you thwart the advances of Legion.", objectives = "" }
WordHunterWoW_QuestEN[39127] = { title = "Beyond the Wall", description = "We received word the Shado-Pan have begun a counter attack in to Townlong Steppes. It sounds like they are going after the root of the yaungol invasion.\n\nThe pandaren have not traveled in force in to Townlong for thousands of years. The Shado-Pan are strong and brave, but they are also proud and few. They will need help from heroes like yourself. Can you travel through the Gate of Winter's Blossom in the northwest? Find the Shado-Pan leaders and lend your help and experience?", objectives = "" }
WordHunterWoW_QuestEN[39129] = { title = "Ill Tempered", description = "<Prying the lid off the scroll case reveals a plan by the Iron Horde to use large fish in the oceans around Draenor to interfere with Alliance and Horde naval power. Incredibly, the plan seems to have already worked on smaller sharks, but only up to a point.>", objectives = "" }
WordHunterWoW_QuestEN[39131] = { title = "Possessions of Power", description = "Echoes of a thousand worlds swirl in the palm of your hand. Its true value lies in the eye of the beholder.", objectives = "" }
WordHunterWoW_QuestEN[39133] = { title = "No Time to Talk", description = "Dargrul has sent his pets to do battle with us.\n\nWe need to crush these elementals before their rage swarms into Thunder Totem.", objectives = "" }
WordHunterWoW_QuestEN[39134] = { title = "Wrathshard", description = "The Underking has used the Hammer of Khaz'goroth to render the mountainside into a weapon against us. The hammer is a tool for creation, not a weapon for his amusement!\n\nEven now, his crystal servant, Wrathshard, is driving these elementals out of the mountain down upon my people.\n\nWe must hold the bridge against this onslaught.\n\nEnter the cave, find Wrathshard, and send him back to his master in pieces.", objectives = "" }
WordHunterWoW_QuestEN[39142] = { title = "Testing a Theory", description = "Now that the Bloodstone has fed, I hope to use its power to bend the will of demons that would otherwise not be so easily controlled.\n\nOf course, this is all theory. I have never witnessed the direct effect of the Bloodstone's power on a demon. This is where you come in.\n\nI have procured a few imps that should make suitable test subjects. Use the Bloodstone on them and report back to me with your findings.", objectives = "" }
WordHunterWoW_QuestEN[39149] = { title = "A Village in Peril", description = "Another outsider? Some bloke named Jarod just went off to our village down the road claiming he might be able to help us with our problem.\n\nIf you're here to help as well, then you best speak to the Mayor.\n\nJust know this is a bad time, and he's got an itchy trigger finger.", objectives = "" }
WordHunterWoW_QuestEN[39153] = { title = "Dreadwake's Dilemma", description = "The situation has taken a dire turn, {name}. We were unprepared for Greymane's sudden assault, with only a token force left behind at Dreadwake's Landing, and we are paying the toll.\n\nThe beach is now swarming with worgen infiltrators, and if the cannons breach our defenses, they will likely swarm in on us. We're spread too thin here to take the fight to them, but you could change that.\n\nWipe them out.", objectives = "" }
WordHunterWoW_QuestEN[39154] = { title = "To Skold-Ashil", description = "Thanks to your initiative, {class}, the situation at Dreadwake's Landing is under control. We have no time to rest on our laurels, however - Sylvanas's mission must still be carried out.\n\nThe dark rangers are heading up operations in Skold-Ashil from the tower overlooking the river junction. Seek them out there, and see if you can aid in completing this task.", objectives = "" }
WordHunterWoW_QuestEN[39155] = { title = "Becoming the Ascendant", description = "It would seem that the engravings depict a rite of ascension, which allows the shieldmaidens to enter the vault. I believe we can use this to our advantage.\n\nYou must become the next ascendant.\n\nGo to the temple and perform the rites. Should you need to wade through the corpses of the shieldmaidens to do so, then so be it. \n\nFind me when you have completed this task, and we will take the vault for the Horde!", objectives = "" }
WordHunterWoW_QuestEN[39175] = { title = "Gems of the Apexis", description = "Listen, boss. I know you're a jewelcrafter. It's OK, I totally understand - I like money, too!\n\nI heard some of them bird fellas talking about some new gem-cuttin' device they got up in Tanaan. I'd be interested in checkin' it out myself, but I've got this whole shipyard mess to deal with right now.", objectives = "" }
WordHunterWoW_QuestEN[39176] = { title = "Mastery Of Taladite", description = "You - you are a gemcutter, no? You have the look of it in the twitch of your knuckles, in the focus of your eyes.\n\nI've been looking for something specific out here in Tanaan. We did not find it in our excavations in Arak... but the Apexis did not only dwell in Arak.\n\nWhat I am looking for is a storied Apexis construct that specialized in cutting gems. Be on the lookout, jewelcrafter. Such a marvel could benefit the both of us.", objectives = "" }
WordHunterWoW_QuestEN[39177] = { title = "Ruined Construct", description = "<It is in disrepair, but it is not broken. More than anything, the construct appears to be in need of re-energizing.>\n\n<A slot on the backside of the machine lies open, waiting to accept... whatever the Apexis used as a source of energy.>", objectives = "" }
WordHunterWoW_QuestEN[39178] = { title = "Moose on the Loose", description = "There's been chatter around the hunters' lodge about a crazed moose that is terrorizing the basin. \n\nI've never laid eyes on the beast myself, but they say its antlers are illuminated with magic. \n\nWhere other lesser hunters have tried and failed, you will prevail, and collect me a one-of-a-kind trophy!", objectives = "" }
WordHunterWoW_QuestEN[39179] = { title = "Bloodstone Bandit", description = "Something of personal value has been taken from me, and my work here cannot continue until I get it back.\n\nTo most it would appear to be an ordinary stone, but it is so much more than a simple rock - it lives and breathes!\n\nThe nearby naga have been snatching anything with any sort of magical significance, my stone included. Fortunately, they do not know how to access its power.\n\nReturn my stone to me, and I will consider your request for help.", objectives = "" }
WordHunterWoW_QuestEN[39180] = { title = "Warchief's Command: Zangarmarsh!", description = "The Cenarion Circle's main expeditionary force in Outland is known as the Cenarion Expedition.  Though it began as a small venture controlled directly by the Cenarion Circle, it's become a large and fairly autonomous body.\n\nThe expedition's leader, Ysiel Windsinger, has asked us to direct volunteers to her outpost.  Report to her at the Cenarion Refuge in eastern Zangarmarsh.  Take the main path to the west and it will lead you directly there.", objectives = "" }
WordHunterWoW_QuestEN[39181] = { title = "Hero's Call: Zangarmarsh!", description = "The Cenarion Circle's main expeditionary force in Outland is known as the Cenarion Expedition.  Though it began as a small venture controlled directly by the Cenarion Circle, it's become a large and fairly autonomous body.\n\nThe expedition's leader, Ysiel Windsinger, has asked us to direct volunteers to her outpost.  Report to her at the Cenarion Refuge in eastern Zangarmarsh.  Take the main path to the west and it will lead you directly there.", objectives = "" }
WordHunterWoW_QuestEN[39182] = { title = "Warchief's Command: Terokkar Forest!", description = "We have lost contact with the druids of the Cenarion Thicket\n\nThe Warchief has commanded any able bodies of the Horde to venture into Terokkar Forest and discover what has happened.\n\nThe thicket can be found by heading northwest through Terokkar Forest from Zangarmarsh.", objectives = "" }
WordHunterWoW_QuestEN[39188] = { title = "Hero's Call: Terokkar Forest!", description = "We have lost contact with the druids of the Cenarion Thicket\n\nThe King has commanded any able bodies of the Alliance to venture into Terokkar Forest and discover what has happened.\n\nThe thicket can be found by heading northwest through Terokkar Forest from Zangarmarsh.", objectives = "" }
WordHunterWoW_QuestEN[39189] = { title = "Warchief's Command: Nagrand!", description = "We have lost contact with the druids of the Cenarion Thicket\n\nThe Warchief has commanded any able bodies of the Horde to venture into Terokkar Forest and discover what has happened.\n\nThe thicket can be found by heading northwest through Terokkar Forest from Zangarmarsh.", objectives = "" }
WordHunterWoW_QuestEN[39191] = { title = "Legacy of the Icebreaker", description = "The greatest warrior should wield the greatest weapons. Long ago a great king, Magnar Icebreaker, wielded weapons crafted from a scale of the mightiest dragon in the land. He should be here, but he is not. Instead he languishes in his tomb.\n\nHis son, Hruthnir, is here. He will lead you to the tomb. If Magnar can be saved, do so. Either way, return with his weapons.", objectives = "" }
WordHunterWoW_QuestEN[39195] = { title = "Gems of the Apexis", description = "Commander! I've noticed you have been keeping up with your jewelcrafting, despite all of this war going on. I find that to be most admirable.\n\nI overheard some of the arakkoa discussing a gemcutting device that they believe is located within Tanaan Jungle. They got their information from one named \"Chakkis.\"\n\nJust thought you might be interested.", objectives = "" }
WordHunterWoW_QuestEN[39196] = { title = "Warchief's Command: Nagrand!", description = "The Warchief has asked for any able bodied champions of the Horde to ride to the aid of Garadar.\n\nThe home of the Mag'har, lies to the south, in Nagrand. Take the southern road out of the marsh, then turn east at the first fork and look for a large settlement on the lake.\n\nReport to Captain Kroghan there and offer him what assistance you can. Garadar must not fall!", objectives = "" }
WordHunterWoW_QuestEN[39197] = { title = "Hero's Call: Nagrand!", description = "The King has requested you represent him with the Kurenai settlement of Telaar in Nagrand.\n\nSeek out Warden Moi'bff Jill upon arrival.", objectives = "" }
WordHunterWoW_QuestEN[39198] = { title = "Warchief's Command: Blade's Edge Mountains!", description = "The Warchief is calling for champions to put an end to the ogre threat in Blade's Edge Mountains. Make your way north into the mountains, to the orcish stronghold of Thunderlord Stronghold and let Gor'drek know of our plight. Any help he can spare would be most welcome.", objectives = "" }
WordHunterWoW_QuestEN[39199] = { title = "Hero's Call: Blade's Edge Mountains!", description = "The Alliance forces of Sylvanaar in the Blade's Edge Mountains require reinforcements.\n\nThe King has asked for any able bodied members of the Alliance to journey to the mountains along the northern border of Zangarmarsh.", objectives = "" }
WordHunterWoW_QuestEN[39201] = { title = "Warchief's Command: Netherstorm!", description = "The goblins of Area 52 in Netherstorm have called for assistance from any able bodied champions willing to provide them the support they need in their endevours.\n\nThe Warchief feels their position and aid in the region will provide a tactical advantage against the nearby forces of Kael'thas.\n\nArea 52 can be reached by following the northeastern road of Blade's Edge Mountains until you see the world crumbling away into the Twisting Nether.", objectives = "" }
WordHunterWoW_QuestEN[39202] = { title = "Hero's Call: Netherstorm!", description = "The goblins of Area 52 in Netherstorm have called for assistance from any able bodied champions willing to provide them the support they need in their endevours.\n\nThe King feels their position and aid in the region will provide a tactical advantage against the nearby forces of Kael'thas.\n\nArea 52 can be reached by following the northeastern road of Blade's Edge Mountains until you see the world crumbling away into the Twisting Nether.", objectives = "" }
WordHunterWoW_QuestEN[39203] = { title = "Warchief's Command: Dragonblight!", description = "The Warchief wishes to reinforce the Horde's presence at Agmar's Hammer in the Dragonblight.\n\nThe fortress is a vital staging point for our assault on Icecrown and pivotal to containing the chaotic magic energies being released throughout the land.\n\nReport to Archmage Aethas Sunreaver.", objectives = "" }
WordHunterWoW_QuestEN[39204] = { title = "Hero's Call: Dragonblight!", description = "Volunteers are needed to aid the Silver Covenant forces in the Dragonblight as they attempt to counter the chaotic arcane energies that threaten to rip the land apart.\n\nThose skilled in fighting dragons and undead are greatly welcome.\n\nThose willing to answer the call should report to Archmage Modera at Stars' Rest in Dragonblight.", objectives = "" }
WordHunterWoW_QuestEN[39206] = { title = "Warchief's Command: Grizzly Hills!", description = "We've received a request for help from our base in the Grizzly Hills. Go to see Conqueror Krenna.\n\nShe's attempting to secure all of the natural resources. Just watch your back around her. The word is that she's aggressive even for an orc.\n\nYou can reach her by traveling east from Dragonblight.", objectives = "" }
WordHunterWoW_QuestEN[39207] = { title = "Hero's Call: Grizzly Hills!", description = "While we focus to hold our ground at Wintergarde and deal with the unfolding events of the Wrathgate, battalions from as far away as Westfall battle their way through the dense foliage and inhospitable denizens of Grizzly Hills. All in hopes of finding an alternate route into Icecrown.\n\nLieutenant Dumont, stationed at Amberpine Lodge, has enlisted the aid of able bodied citizens willing to risk life and limb in the uncharted wilds. Will you rise to meet this challenge?", objectives = "" }
WordHunterWoW_QuestEN[39208] = { title = "Zul'Drak", description = "Our death knight allies in Zul'Drak are in need of heroes to aid them in securing the troll lands from the Scourge.\n\nThose willing to aid should travel to the southwestern camp of Ebon Watch and speak with Stefan Vadu there.", objectives = "" }
WordHunterWoW_QuestEN[39209] = { title = "Sholazar Basin", description = "Hemet Nesingwary was last heard from leading an expedition into the jungle depths of Sholazar Basin. His expedition has not been heard from since.\n\nMonte Muzzleshot is a pilot who was dispatched to provide them supplies, but he hasn't returned, either.\n\nVolunteers are needed to mount an expedition to find the missing expedition. Monte's flying machine was last seen in the Wildgrowth Mangal south of the Suntouched Pillar in Sholazar Basin.", objectives = "" }
WordHunterWoW_QuestEN[39210] = { title = "The Magical Kingdom of Dalaran", description = "The Kirin Tor have moved their city here to Northrend.\n\nNo longer does Dalaran sit under its protective dome on the shores of Lordamere Lake. Now the city magically floats above the Crystalsong Forest.\n\nThey believe you to be ready for your journey to the city. Look for the teleportation crystal in Crystal Song Forest.\n\nWhen you arrive, seek out Archmage Celindra.", objectives = "" }
WordHunterWoW_QuestEN[39212] = { title = "Sholazar Basin", description = "Hemet Nesingwary was last heard from leading an expedition into the jungle depths of Sholazar Basin. His expedition has not been heard from since.\n\nMonte Muzzleshot is a pilot who was dispatched to provide them supplies, but he hasn't returned, either.\n\nArchmage Pentarus in Dalaran is standing by with a flying machine to take you to the last known location of Monte Muzzleshot.", objectives = "" }
WordHunterWoW_QuestEN[39214] = { title = "The Eye of Odyn", description = "It is time to begin the war in Azeroth. We have prepared a tool for you to direct your warriors and your own operations from here. It is called the Eye of Odyn. \n\nIf you will follow me, I will take you to it, and someone that will help you use it.", objectives = "" }
WordHunterWoW_QuestEN[39221] = { title = "Pits of Mannoroth", description = "In the Hellfire Citadel, they work to corrupt a magnaron with fel energy within the Pits of Mannoroth.\n\nIf you delve into the fel pools of that place, be on your guard.", objectives = "" }
WordHunterWoW_QuestEN[39225] = { title = "Maw of Souls", description = "Falling into the heart of the mausoleum in Auchindoun, Teron'gor gorged upon hundreds of draenei souls, becoming a bloated abomination in the process. \n\nNo longer recognizable as an orc, Teron'gor gave up his old name and has taken on the mantle of Gorefiend.", objectives = "" }
WordHunterWoW_QuestEN[39228] = { title = "Temple of Tyranny", description = "Tyrant Velhari was once a promising vindicator, but has turned to Shadow for reasons known only to her.\n\nPurge this Eredar of darkness.", objectives = "" }
WordHunterWoW_QuestEN[39231] = { title = "Destructor's Rise", description = "We believed we were done with Mannoroth, at least for a time. But Gul'dan is more powerful than we had predicted.\n\nMannoroth is nearly back in this world. His bones have been seen within the citadel, and he must be destroyed before he can reach his full power.", objectives = "" }
WordHunterWoW_QuestEN[39232] = { title = "The Black Gate", description = "We have heard rumors that one of the strongest of the eredar could soon enter this world through the Black Gate.\n\nIf these rumors are to be believed, it could even be Archimonde the Defiler. Should he arrive uncontested, Draenor itself is likely to fall.", objectives = "" }
WordHunterWoW_QuestEN[39236] = { title = "Let's Get To Work", description = "Now that the shipyard is complete, we need to get busy making ships!  Solog ran off to the dry docks, why don't you meet him down there?  He said he had a plan.", objectives = "" }
WordHunterWoW_QuestEN[39241] = { title = "Shipbuilding", description = "The first thing we need to start building ships is a blueprint. With your help, I grabbed some of the best ones from the Iron Docks before we broke out of there.\n\nLet's make sure these don't fall back into the hands of the Iron Horde. Memorize these blueprints, {class}, and then destroy the evidence. Let me know when you are done.", objectives = "" }
WordHunterWoW_QuestEN[39242] = { title = "Ship Shape", description = "You want to take the fight to Gul'dan? You need a transport! Speak to me when you are ready to begin construction.", objectives = "" }
WordHunterWoW_QuestEN[39243] = { title = "Naval Commander", description = "You're a natural at this, {name}. You've got the salt in your veins. Now it's time to run our first naval mission and control the seas of Draenor!\n\nYou will want a high vantage point to plan out these seafaring missions.  I know a good spot just up the path behind us. Meet me near the shipyard entrance and we can get started on our first mission.", objectives = "" }
WordHunterWoW_QuestEN[39245] = { title = "Upgrading The Fleet", description = "You have been doing a great job out there commander.  However, we are going to need more experience and resources to upgrade this shipyard.  Once we reach our goals, we can upgrade the capacity of the shipyard to hold more ships!", objectives = "" }
WordHunterWoW_QuestEN[39246] = { title = "Naval Domination", description = "Our naval domination continues!\n\nHowever, we are going to need even more experience and resources to take this shipyard to the next level.  Once we reach our goals, we can upgrade the capacity of the shipyard to hold even more ships!", objectives = "" }
WordHunterWoW_QuestEN[39247] = { title = "The Hunt", description = "This hunt is yours to lead, {name} - a select few Illidari will join you to make sure Varedis meets his end.\n\nThe rest of us must stay behind; a small team will have the best chance of making it to his hold undetected.\n\nWe will meet you at Krasus' Landing to see you off when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[39250] = { title = "Pits of Mannoroth", description = "In the Hellfire Citadel, they're corruptin' a magnaron with fel energy in the Pits o' Mannoroth.\n\nIf ye delve into the fel pools of that place, be on yer guard.", objectives = "" }
WordHunterWoW_QuestEN[39253] = { title = "Maw of Souls", description = "Falling into the heart o' the mausoleum in Auchindoun, Teron'gor gorged upon hundreds o' draenei souls, becoming a bloated abomination in the process. \n\nNo longer recognizable as an orc, Teron'gor gave up his old name and has taken on the mantle of Gorefiend.", objectives = "" }
WordHunterWoW_QuestEN[39256] = { title = "Temple of Tyranny", description = "Tyrant Velhari was once a promising vindicator, but has turned to Shadow for reasons known only to her.\n\nPurge this Eredar of darkness.", objectives = "" }
WordHunterWoW_QuestEN[39259] = { title = "Destructor's Rise", description = "We believed we were done with Mannoroth, at least for a time. But Gul'dan is more powerful than we thought.\n\nMannoroth is nearly back in this world. His bones have been seen within the citadel, and he must be destroyed before he can reach his full power.", objectives = "" }
WordHunterWoW_QuestEN[39260] = { title = "The Black Gate", description = "We've heard rumors that one o' the strongest eredar might enter this world through the Black Gate soon.\n\nIf these rumors are to be believed, it could even be Archimonde the Defiler. If he arrives unchallenged, Draenor itself is likely to fall.", objectives = "" }
WordHunterWoW_QuestEN[39261] = { title = "Call of the Illidari", description = "{name}, Kayn requests that you meet him at Krasus' Landing at once.\n\n<Kor'vas leans in close, her voice an urgent whisper.>\n\nYou must hurry. The Legion has eyes everywhere.", objectives = "" }
WordHunterWoW_QuestEN[39262] = { title = "Give Me Sight Beyond Sight", description = "Jace Darkweaver swears that for a split second he sensed a demonic presence up and behind us. He took some of our forces up to the cave just to the southeast to investigate.\n\nThey found nothing in the cave, but he is certain that something is amiss.\n\nWould you lend him your guidance, and more importantly, your spectral sight?", objectives = "" }
WordHunterWoW_QuestEN[39272] = { title = "Poisoned Crops", description = "After driving us from the farmland and infesting our crops with insects, the drogbar placed wicked totems that further poison our harvest.\n\nI can only hope that if you destroy them, we'll be able to heal the land using Jale's water magic.\n\nThank you for coming to help us, {name}. We are but simple farmers and fishermen, and have little prowess in combat.", objectives = "" }
WordHunterWoW_QuestEN[39276] = { title = "Strange Tools", description = "We are well on our way to building our first ship, but unfortunately, I am not the orc for the job.  I have no idea how to work with these human tools.  Your shipwright, Yanas Seastrike, is going to take over from here on out.\n\nI will be here at the dry docks if you need anything from me.", objectives = "" }
WordHunterWoW_QuestEN[39277] = { title = "Spray and Prey", description = "The Bug Sprayer you recovered from Ormgul the Pestilent seems like it could give us an advantage against the drogbar and their insects.\n\nSpray the Drogbar with their own alchemy and watch their insects turn against them.", objectives = "" }
WordHunterWoW_QuestEN[39278] = { title = "The Missing Manifest", description = "The water-proofed manifest contains some form of code for the most part, hiding the contents of the actual manifest. In the corner is a hastily scrawled note for a Mr. Knuckles. \"Shipment attacked, got away but boat is sinking. Get here before they do.\"\n\nThere are coordinates after that which lead to the sunken boat. Mr. Knuckles is definitely the kind of person you want owing you a favor, not the other way around.", objectives = "" }
WordHunterWoW_QuestEN[39296] = { title = "Crystal Fissure Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39299] = { title = "Black Marketeering", description = "Ya did us a real solid today, {name}. Boss Goya says you're big stuff in dese parts and we should keep an eye on --- uh, I mean we should be good buds. She's sent a repre... repre... del-e-g... um, a Black Market person to your garrison.\n\nGo say hi and stuff, and make sure to speak loudly when you plan what you're gonna do next.", objectives = "" }
WordHunterWoW_QuestEN[39305] = { title = "Empty Nest", description = "I've taken an inventory of the eggs you recovered. Some among the bunch may still have a chance to hatch.\n\nThey will need to be returned to an empty nest, and with any luck, an eagle will claim the eggs as her own and watch over them once again.\n\nThere is a nest just outside the entrance, on a rocky ledge above the cave.\n\nBe careful, {name}. The eggs are very delicate.", objectives = "" }
WordHunterWoW_QuestEN[39311] = { title = "Bitestone Enclave Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39312] = { title = "Thunder Totem Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39313] = { title = "Bring the Reinforcements", description = "Greetings, Commander! With all of the fighting concentrated here in Tanaan, we've got the breathing room to divert some of our resources from nearby outposts to help make headway.\n\nJust let me know which reinforcements to call, and I'll get them here on the double!", objectives = "" }
WordHunterWoW_QuestEN[39315] = { title = "Bring the Reinforcements", description = "Hey there, Commander. You know, with all of the fighting concentrated here in Tanaan, we've got plenty of extra supplies just sitting around in our nearby outposts.\n\nYou just give me the order and I'll make sure some of them get sent our way!", objectives = "" }
WordHunterWoW_QuestEN[39316] = { title = "Trapped Tauren", description = "The drogbar just rounded up those of us that they could and led them to a cave near here.\n\nIf you act quickly, I think they can still be saved. I know not what purpose they have for capturing our people.\n\nI shudder to think of it... in the deep places, the darkness rules.", objectives = "" }
WordHunterWoW_QuestEN[39318] = { title = "Nursing the Wounds", description = "I know why Mayla sent you. But as you have seen, the drogbar are not the only threat to Highmountain.\n\nI will not send forces to support until we deal with the minions of High Crawliac.\n\nIf you want to help, find my shaman. He was supposed to be dispersing these fires that are ravaging my village.\n\nHe was last seen heading for his spirit lodge to the south just before these Cinderwitches descended on us.", objectives = "" }
WordHunterWoW_QuestEN[39321] = { title = "The Three", description = "When High Crawliac seized control of the harpies she placed 3 powerful and deadly witches in charge of the covens under her command.\n\nThese witches must die. Feel up for the challenge?\n\nHead into the Haglands behind me and find these three evil creatures.\n\nWe will cover you from the air and give your prey no sky to retreat.\n\nLook for us higher up the mountain, should you survive.", objectives = "" }
WordHunterWoW_QuestEN[39322] = { title = "The Witchqueen", description = "The time has come to assault High Crawliac, the Witchqueen.\n\nYou should know that one does not become queen of the harpies through kindness.\n\nThis creature has killed, betrayed, and tormented countless tauren, harpies, kobolds, and anything else she had to in order to secure her position as queen.\n\nCome, friend, let us finish this.", objectives = "" }
WordHunterWoW_QuestEN[39323] = { title = "Moozy's Sojourn", description = "My son! They took him! My wife and I split up to look for him. She went upriver and I went downriver.\n\nLeave me, please, and find Moozy... I might be okay... If you find Moozy, please bring him to my wife upriver.", objectives = "" }
WordHunterWoW_QuestEN[39325] = { title = "Get Your Mix On", description = "Let's see... potion stains on your tabard, crushed herbs on your boots... I know a fellow alchemist when I see one!\n\nWe will do good work together, the two of us. I trust you're not averse to learning new tricks.\n\nBe sure to use my state-of-the-art alchemy table. I built her myself!", objectives = "" }
WordHunterWoW_QuestEN[39326] = { title = "Missing Shipments", description = "Now that we've gotten to know each other, perhaps you can lend me a hand.\n\nMy weekly supply shipment was lost when my longtime courier--you know, old whatsername--was shot out of the sky over the shores of Azsuna. Surely a hardy sort like you could retrieve my lost goods.", objectives = "" }
WordHunterWoW_QuestEN[39327] = { title = "There's a Scribe for That", description = "Fine! I admit, even my considerable intellect can't translate the strange tome you discovered. No doubt the water smears made it illegible.\n\nSay, one of those dimwitted scribes down the block owes me a favor. This sort of busywork is just his cup of tea.", objectives = "" }
WordHunterWoW_QuestEN[39328] = { title = "Ancient Knowledge", description = "The tome contains a wealth of ancient vrykul recipes! Why, I could be the first alchemist in untold ages to craft one! How fortunate for you, friend {name}, that you are here to bear witness to my greatness!\n\nAwful kind of that Svena person to die and leave her book for us, eh? Silly vrykul...", objectives = "" }
WordHunterWoW_QuestEN[39329] = { title = "A Dormant Burner", description = "I've heard that someone over in the engineering shop is selling a burner that might be usable. You could likely negotiate a fairer price than I could!\n\nThe shop is just across the street. I'll make a note on your map for you.", objectives = "" }
WordHunterWoW_QuestEN[39330] = { title = "Ley Hunting", description = "The leyflame burner you brought me is useless! This is why I never trust an engineer...\n\nThe burner needs to be charged in areas that resonate with ley energy before it can be used to craft our newfound alchemy recipes.\n\nLucky for us, Azsuna is rich with such power.", objectives = "" }
WordHunterWoW_QuestEN[39331] = { title = "Eye of Azshara: Put a Cork in It", description = "A thought occurred to me recently, {name}. The naga have been known to hoard all manner of potions, so they might have the sort of corks we need.\n\nIn my educated opinion, I believe the best place to start searching is around the Eye of Azshara!\n\nTry not to waste your time in there dealing with the naga's goings on, just look for some replacement corks.", objectives = "" }
WordHunterWoW_QuestEN[39332] = { title = "Furbolg Firewater", description = "Oh! I recognize these corks you brought me, {name}. I recently acquired several from a furbolg tribe in Val'sharah. They need sturdy corks to keep a tight seal on that potent firewater they brew.\n\nWe need more firewater potions--the corks would make an ideal addition to our alchemy table!", objectives = "" }
WordHunterWoW_QuestEN[39333] = { title = "An Imprecise Burette", description = "Here are your burettes. Should you ever be in the need of anything else, don't hesitate to ask.\n\n<Ms. Xiulan holds up the hair and continues to chuckle to herself.>", objectives = "" }
WordHunterWoW_QuestEN[39334] = { title = "Thanks for Flasking", description = "Here is your flask, good as new. A fair trade for those potions.\n\nBe a little more careful with your breakables next time!", objectives = "" }
WordHunterWoW_QuestEN[39335] = { title = "Neltharion's Lair: Potent Powder", description = "I've heard rumors that the ancient drogbar collected powder from the residue of dragon's breath. If it's true that Neltharion's Lair lies somewhere below us, it seems a likely source.\n\nGo there and try to find a replacement for my powder.", objectives = "" }
WordHunterWoW_QuestEN[39336] = { title = "We Need More Powder!", description = "The substance you brought me appears to be precipitating powder, a highly volatile reagent used by the vrykul in their recipes.\n\nThere are rumors that a vrykul elder named Katterin has built up quite a store of this powder. A substance this dangerous needs to be in our hands, not hers!", objectives = "" }
WordHunterWoW_QuestEN[39337] = { title = "Forlorn Filter", description = "Next on the list of things to replace are my filters. Now I'm sure you've concluded that an alchemist of my caliber uses only the finest of tools when mixing my potions.\n\nThe elves at the Temple of Elune in Val'sharah use Shaldorei silk to craft their robes. Perhaps they'd be willing to part with some for my filters.", objectives = "" }
WordHunterWoW_QuestEN[39338] = { title = "Return the Filter", description = "What was torn has now been mended. I hope you put this Shaldorei silk to good use.\n\nNow, run along.", objectives = "" }
WordHunterWoW_QuestEN[39339] = { title = "A Fragile Crucible", description = "I have customers asking for alchemist stones, but I'm unable to make any until I replace my crucible.\n\nIn order to create a new one, we'll need a few things, but first we'll need a proper container. Something that can be augmented to withstand a demon's breath.\n\nThere's a place in Suramar which the Legion has occupied. There surely must be a device there we can take that will be suitable for our needs.", objectives = "" }
WordHunterWoW_QuestEN[39340] = { title = "Lining the Crucible", description = "The first step in making this crucible useful is to restore the lining of its interior. That's going to require supplies you'll either gather yourself or obtain through trade with fellow adventurers.\n\nFelwort and yseralline seeds are familiar to herbalists.\n\nFelhide is obtained through skinning.\n\nBlood of Sargeras can be found all over the Broken Isles.", objectives = "" }
WordHunterWoW_QuestEN[39341] = { title = "Vault of the Wardens: Demon's Bile", description = "The key to a crucible like this is that it must be bathed in the foulest of fel energy. I hate to say it, but the most efficient method of accomplishing such a feat is to subject it to the bile of a demon.\n\nYes, I said the bile of a demon. Ready to get to work?\n\nIn the Vault of the Wardens, such a demon exists. An imp mother by the name of Grimoira. The door to her room is sealed by an invisible lock.\n\nI'd suggest bringing some Skaggldrynk with you. Use it when you get to her door.", objectives = "" }
WordHunterWoW_QuestEN[39342] = { title = "The Price of the Black Market", description = "I may have what you're looking for, burettes you say? Not a very common item.\n\nFor that, I require a moderate favor. Nothing too big, just a few things really.\n\nA silver hair from a high-ranking archmage... the blood of a titan, and, oh... some wine and cheese.\n\nWhat?! I have appetites that need satiating.", objectives = "" }
WordHunterWoW_QuestEN[39343] = { title = "Vault of the Wardens: Bendy Glass Tubes", description = "You find tubing formed from a bendable sort of glass. It appears as though Grimoira was using it to suck out the insides of her victims.\n\nIts magical properties, however, would seem ideal for use on an advanced alchemy table.", objectives = "" }
WordHunterWoW_QuestEN[39344] = { title = "Going Underground", description = "We're so close to replacing all my equipment, {name}. In order to make flasks again, we need to be able to precisely measure each ingredient.\n\nFor that, we need to replace my burette assembly. Unfortunately, burettes aren't easy to come by. We may be able to procure some though through other means by...\n\n<Deucus looks around and beckons you closer.>\n\nGoing underground, so to say. As in, the Black Market.\n\nGo see Ms. Xiulan. Mum's the word.", objectives = "" }
WordHunterWoW_QuestEN[39345] = { title = "Calibration Experts", description = "It will take the cooperation of several highly skilled sorts to calibrate these burettes for a variety of substances.\n\nChemist Emmara is an old friend from the Undercity who has helped me with similar endeavors.\n\nThunder Bluff smells like a barn to me, but Jana Winterhoof is an alchemist with exacting standards.\n\nAnd while I'd never travel to Booty Bay without a lock on my wallet, Tryks Pourtrue has proven reliable and fair.", objectives = "" }
WordHunterWoW_QuestEN[39346] = { title = "Testing the Calibration", description = "Now that you have the burettes calibrated, it's time to test them out! The only way to be sure is by crafting a sufficient quantity of a variety of potions.\n\nGlamorous work? No, but the most important reagent in alchemy is a bit of elbow grease!", objectives = "" }
WordHunterWoW_QuestEN[39347] = { title = "Channeling Our Efforts", description = "While it's no secret my time is more valuable than... well, anyone's, I fear I must step in and help to replace my decoction conduit.\n\nYou will also play a crucial part in this, {name}, as my liaison with the blacksmiths. The thought of getting soot on my robes curls my toes.\n\nHere's a list of what we'll need done. Meanwhile I'll be out gathering the rest of what's needed.", objectives = "" }
WordHunterWoW_QuestEN[39348] = { title = "Halls of Valor: The Prime Ingredient", description = "This first ingredient can only be obtained by visiting the next realm. Fortunately for us, there's a gate in Stormheim that can take you there.\n\nIn the Halls of Valor, there is a sand that's used for polishing their architecture. Eternity Sand, it's called. I'll need an ample amount of it as the base for the new glass.\n\nThis ingredient won't be easy to work with either. I'll need something to keep me going, you know, keep my stamina up.", objectives = "" }
WordHunterWoW_QuestEN[39349] = { title = "Black Rook Hold: Heavy, But Helpful", description = "The next ingredient on the list will supposedly add strength to the mix, according to Deucus. I've heard of it before, but haven't really used it.\n\nIt's called Sabelite Sulfate, and it's said the elves of Black Rook Hold use it in their blacksmithing.\n\nSomething like that won't just be lying around. You may have to delve deep into the hold to find it.\n\nAnd due to its weight, I may need a concoction of yours to compensate, something to give me a bit more strength.", objectives = "" }
WordHunterWoW_QuestEN[39350] = { title = "Maw of Souls: A Hope in Helheim", description = "For this last ingredient, well...\n\n<Alard begins pondering for a moment, then nods his head.>\n\nYes, that's the only way. For this last one, you'll need to go to the land of the damned, Helheim.\n\nWell, not there exactly, but aboard the boat that ferries the dead across the Maw of Souls. Upon that boat may be the final ingredient we need.\n\nIt's called Dragur Dust. Keep an eye out for it.\n\nAlso, one needs to be quick when adding this ingredient. I'll need something to heighten my reflexes.", objectives = "" }
WordHunterWoW_QuestEN[39351] = { title = "The Emerald Nightmare: Rage Fire", description = "Now that we have all the ingredients assembled, we need one last thing.\n\nThe fire of my forges burn hot, but not hot enough to work these ingredients into glass. For that, we need more heat. The heat of a dragon, to be exact.\n\nI'm aware of one that has emerged from the Emerald Dream in a corrupted state. Corrupted or not, a dragon's heart burns with enough heat to melt the strongest of materials.\n\nBring me its heart and you'll have your conduit.", objectives = "" }
WordHunterWoW_QuestEN[39354] = { title = "Wisp in the Willows", description = "Wisps are the spirits of our night elven brethren who have become one with the forest. But their minds and the way they perceive things are very different than in life.\n\nYou should bond with this little one. See through its eyes as it travels to the hidden pools and grows some trees.", objectives = "" }
WordHunterWoW_QuestEN[39355] = { title = "Equipment Blueprint: Trained Shark Tank", description = "This appears to be a blueprint for some sort of naval equipment.  We should take it back to our Shipyard and see if someone can decipher it.", objectives = "" }
